CREATE OR REPLACE FUNCTION private.demo_seed_analytics_after_evidence_delete()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  perform private.lock_case_graph(array[auth.uid()], array[]::uuid[]);

declare
  seeded_run record;
begin
  for seeded_run in
    select distinct evidence.lane, evidence.run_id
    from deleted_function_evidence evidence
    where evidence.function_id between 'CR-040' and 'CR-044'
  loop
    perform private.demo_seed_remove_analytics(seeded_run.lane, seeded_run.run_id);
  end loop;
  return null;
end;
end;
$function$

CREATE OR REPLACE FUNCTION private.demo_seed_analytics_after_page_evidence_insert()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  perform private.lock_case_graph(array[auth.uid()], array[]::uuid[]);

declare
  seeded_run record;
begin
  if pg_catalog.pg_trigger_depth() > 1 then
    return null;
  end if;
  for seeded_run in
    select distinct evidence.lane, evidence.run_id
    from inserted_page_evidence evidence
    where evidence.surface not in (
      'analyticsMemberExplorer',
      'analyticsOrganizationLayouts',
      'analyticsChapterLayouts'
    )
  loop
    perform private.demo_seed_apply_analytics(seeded_run.lane, seeded_run.run_id);
  end loop;
  return null;
end;
end;
$function$

CREATE OR REPLACE FUNCTION private.demo_seed_apply_administrative_evidence(p_lane text, p_run_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  perform private.lock_case_graph(array[auth.uid()], array[]::uuid[]);

declare
  org uuid := private.member_stress_uuid(p_run_id::text || case when p_lane='presg' then ':presg:organization' else ':ud:organization' end);
  actor uuid;
  note_source_id uuid;
  note_id uuid;
  packet_id uuid;
  ordinal integer;
  occurred_at timestamptz;
  issue text;
begin
  if p_lane not in ('presg','uniondemo') then raise exception 'unknown demo lane'; end if;
  if p_lane='presg' and not exists (select 1 from private.presg_demo_runs r where r.id=p_run_id and r.state in ('applied','verified')) then raise exception 'presg demo run is not applied'; end if;
  if p_lane='uniondemo' and not exists (select 1 from private.uniondemo_runs r where r.id=p_run_id and r.state in ('applied','verified')) then raise exception 'union demo run is not applied'; end if;
  if not exists (select 1 from public.organizations o where o.id=org and o.status='active') then raise exception 'demo organization is missing'; end if;
  actor := private.demo_seed_user(p_lane,p_run_id,case when p_lane='presg' then 1 else 3 end);
  if not exists (
    select 1 from public.organization_role_grants grant_row
    join public.organization_memberships membership
      on membership.organization_id=grant_row.organization_id and membership.user_id=grant_row.user_id and membership.status='active'
    where grant_row.organization_id=org and grant_row.user_id=actor and grant_row.role='admin'
  ) then raise exception 'administrative evidence seed actor is not an active Admin'; end if;
  perform private.demo_seed_remove_administrative_evidence(p_lane,p_run_id);

  for ordinal in 1..50 loop
    occurred_at := pg_catalog.now() - (((ordinal - 1) * 22) || ' days')::interval;
    issue := (array['accommodation','attendance','workplace-safety','scheduling','protected-leave'])[1 + ((ordinal - 1) % 5)];
    note_source_id := private.member_stress_uuid(p_run_id::text || ':administrative:field-source:' || ordinal);
    note_id := private.member_stress_uuid(p_run_id::text || ':administrative:field-note:' || ordinal);
    packet_id := private.member_stress_uuid(p_run_id::text || ':administrative:packet:' || ordinal);

    insert into public.organization_field_note_sources (
      id,organization_id,title,source_type,provenance,created_by,created_at
    ) values (
      note_source_id,org,
      (array['Member interview','Supervisor memorandum','Attendance record','Safety inspection','Schedule notice'])[1 + ((ordinal - 1) % 5)] || ' ' || pg_catalog.lpad(ordinal::text,2,'0'),
      (array['interview','document','observation','recording','other'])[1 + ((ordinal - 1) % 5)],
      (array['Recorded with consent','Member-provided copy','Organization record export','Steward observation log','Meeting follow-up note'])[1 + ((ordinal - 1) % 5)],
      actor,occurred_at
    );
    insert into public.organization_field_note_blocks (
      id,organization_id,source_id,issue_key,body,annotation,packet_state,created_by,created_at,updated_at
    ) values (
      note_id,org,note_source_id,issue,
      'The record documents a dated workplace event, the response, and the next evidence question for review.',
      'Confirm the timeline against the authorized source before marking the packet review ready.',
      case when ordinal % 7=0 then 'excluded' else 'included' end,
      actor,occurred_at,occurred_at
    );
    insert into public.organization_field_note_packets (
      id,organization_id,issue_key,title,body,status,created_by,created_at,updated_at
    ) select
      packet_id,org,issue,
      pg_catalog.initcap(pg_catalog.replace(issue,'-',' ')) || ' evidence packet ' || pg_catalog.lpad(ordinal::text,2,'0'),
      '## Field Note Evidence' || pg_catalog.chr(10) || 'Source title: ' || source.title || pg_catalog.chr(10) || 'Source type: ' || source.source_type || pg_catalog.chr(10) || 'Provenance: ' || source.provenance || pg_catalog.repeat(pg_catalog.chr(10), 2) || block.body ||
        case when block.annotation='' then '' else pg_catalog.repeat(pg_catalog.chr(10), 2) || 'Annotation: ' || block.annotation end,
      case when ordinal % 3=0 then 'review_ready' else 'draft' end,
      actor,occurred_at,occurred_at
    from public.organization_field_note_blocks block
    join public.organization_field_note_sources source on source.id=block.source_id and source.organization_id=org
    where block.organization_id=org and block.issue_key=issue and block.packet_state='included'
    order by block.created_at desc,block.id desc limit 1;
    insert into public.organization_object_action_runs (
      id,organization_id,target_kind,target_id,target_label,action_key,note,previous_state,resulting_state,actor_user_id,created_at
    ) select
      private.member_stress_uuid(p_run_id::text || ':administrative:action:' || ordinal),org,
      'field_note_block',block.id,block.issue_key || ' · ' || source.title,
      case block.packet_state when 'excluded' then 'exclude' else 'include' end,
      'Routine evidence review ' || pg_catalog.lpad(ordinal::text,2,'0'),
      pg_catalog.jsonb_build_object('packetState','draft'),
      pg_catalog.jsonb_build_object('packetState',block.packet_state),
      actor,occurred_at
    from public.organization_field_note_blocks block
    join public.organization_field_note_sources source on source.id=block.source_id and source.organization_id=org
    where block.organization_id=org and block.id=note_id;
  end loop;
end;
end;
$function$

CREATE OR REPLACE FUNCTION private.demo_seed_apply_auth_operations(p_lane text, p_run_id uuid, p_target_ref text, p_confirm_token text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  perform private.lock_case_graph(array[auth.uid()], array[]::uuid[]);

declare
  v_organization_id uuid;
  actor_user_id uuid;
  member_user_id uuid;
  member_email text;
  i integer;
  result jsonb;
begin
  if p_lane = 'presg' then
    perform private.presg_demo_authorize(p_target_ref, p_confirm_token);
    if not exists (
      select 1 from private.presg_demo_runs
      where id = p_run_id and state in ('applied', 'verified')
    ) then
      raise exception 'presg demo run must be applied before auth operations data';
    end if;
    v_organization_id := private.member_stress_uuid(p_run_id::text || ':presg:organization');
  elsif p_lane = 'uniondemo' then
    perform private.uniondemo_authorize(p_target_ref, p_confirm_token);
    if not exists (
      select 1 from private.uniondemo_runs
      where id = p_run_id and state in ('applied', 'verified')
    ) then
      raise exception 'union demo run must be applied before auth operations data';
    end if;
    v_organization_id := private.member_stress_uuid(p_run_id::text || ':ud:organization');
  else
    raise exception 'unknown demo lane';
  end if;

  if not exists (
    select 1 from public.organizations o
    where o.id = v_organization_id and o.status = 'active'
  ) then
    raise exception 'demo organization is missing';
  end if;

  actor_user_id := private.demo_seed_user(p_lane, p_run_id, 1);

  insert into public.organization_setting_values
    (organization_id, setting_key, value, updated_by, updated_at)
  values
    (v_organization_id, 'features.passkey_enrollment', 'true'::jsonb, actor_user_id, pg_catalog.now() - interval '2 days'),
    (v_organization_id, 'features.mfa_recovery_code_enrollment', 'true'::jsonb, actor_user_id, pg_catalog.now() - interval '2 days'),
    (v_organization_id, 'security.failed_login_retention_days', '90'::jsonb, actor_user_id, pg_catalog.now() - interval '2 days'),
    (v_organization_id, 'security.failed_login_alert_threshold', '3'::jsonb, actor_user_id, pg_catalog.now() - interval '2 days'),
    -- REQ-UG-STEWARD-ATTENTION-TREND-20261001: the old demo ran the
    -- attention-guided portal ON while production defaulted it OFF (0254).
    (v_organization_id, 'features.attention.guided_portal', 'true'::jsonb, actor_user_id, pg_catalog.now() - interval '2 days'),
    (v_organization_id, 'features.attention.dashboard', 'true'::jsonb, actor_user_id, pg_catalog.now() - interval '2 days'),
    (v_organization_id, 'features.attention.member_surfaces', 'true'::jsonb, actor_user_id, pg_catalog.now() - interval '2 days'),
    (v_organization_id, 'features.attention.navigation', 'true'::jsonb, actor_user_id, pg_catalog.now() - interval '2 days')
  on conflict (organization_id, setting_key) do update
    set value = excluded.value,
        updated_by = excluded.updated_by,
        updated_at = excluded.updated_at;

  insert into public.organization_label_overrides
    (organization_id, label_key, label_value, updated_by, updated_at)
  values
    (v_organization_id, 'nav.myCases', 'Case support', actor_user_id, pg_catalog.now() - interval '36 hours'),
    (v_organization_id, 'staff.chapterWork', 'Chapter work', actor_user_id, pg_catalog.now() - interval '36 hours')
  on conflict (organization_id, label_key) do update
    set label_value = excluded.label_value,
        updated_by = excluded.updated_by,
        updated_at = excluded.updated_at;

  for i in 1..6 loop
    member_user_id := private.demo_seed_user(p_lane, p_run_id, i + 1);
    select pg_catalog.lower(u.email) into member_email
    from auth.users u where u.id = member_user_id;
    if member_email is null then
      raise exception 'demo auth identity is missing';
    end if;

    insert into public.organization_failed_login_attempts (
      id, organization_id, member_user_id, identity_hash, method, source,
      user_agent, status, disposition_note, reviewed_by, reviewed_at, occurred_at
    ) values (
      private.member_stress_uuid(p_run_id::text || ':auth:failed-login:' || i::text),
      v_organization_id,
      member_user_id,
      pg_catalog.encode(
        extensions.digest(pg_catalog.convert_to(member_email, 'UTF8'), 'sha256'),
        'hex'
      ),
      case when i % 3 = 0 then 'passkey' else 'password' end,
      'web-sample',
      case when i % 2 = 0 then 'Mozilla/5.0 Safari/605.1.15' else 'Mozilla/5.0 Chrome/128.0.0.0' end,
      case when i <= 4 then 'open' else 'reviewed' end,
      case when i <= 4 then null else 'Confirmed member retry' end,
      case when i <= 4 then null else actor_user_id end,
      case when i <= 4 then null else pg_catalog.now() - ((i - 1)::text || ' hours')::interval end,
      pg_catalog.now() - (i::text || ' hours')::interval
    )
    on conflict (id) do update set
      organization_id = excluded.organization_id,
      member_user_id = excluded.member_user_id,
      identity_hash = excluded.identity_hash,
      method = excluded.method,
      source = excluded.source,
      user_agent = excluded.user_agent,
      status = excluded.status,
      disposition_note = excluded.disposition_note,
      reviewed_by = excluded.reviewed_by,
      reviewed_at = excluded.reviewed_at,
      occurred_at = excluded.occurred_at;
  end loop;

  result := private.demo_seed_auth_operations_status(p_lane, p_run_id);
  if not (result ->> 'ok')::boolean then
    raise exception 'auth operations seed contract failed: %', result;
  end if;
  return result;
end;
end;
$function$

CREATE OR REPLACE FUNCTION private.demo_seed_apply_casework(p_lane text, p_run_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET statement_timeout TO '300s'
AS $function$#variable_conflict use_variable

begin
  perform private.lock_case_graph(array[auth.uid()], array[]::uuid[]);

begin
  perform private.lock_message_lifecycle();


declare
  organization_id uuid := private.member_stress_uuid(
    p_run_id::text || case when p_lane = 'presg' then ':presg:organization' else ':ud:organization' end
  );
  featured_chapter text;
  featured_steward uuid;
  grant_user uuid;
  case_ids uuid[];
  case_row record;
  case_id uuid;
  next_case_id uuid;
  template_id uuid;
  checklist_id uuid;
  alert_id uuid;
  deadline_id uuid;
  management_person_id uuid;
  management_entry_id uuid;
  retaliation_report_id uuid;
  workspace_id uuid;
  proposal_id uuid;
  pattern_id uuid;
  pattern_row record;
  workspace_ordinal integer;
  event_ordinal integer;
  report_ordinal integer;
  result jsonb;
begin
  perform set_config('app.sensitive_seed_ticket', coalesce((select id::text from private.sensitive_write_tickets where operation='demo_seed' and arguments=jsonb_build_object('lane',p_lane,'runId',p_run_id) and expires_at>clock_timestamp() order by expires_at desc limit 1),''),true);
  if p_lane not in ('presg', 'uniondemo') then
    raise exception 'unknown demo lane';
  end if;
  if p_lane = 'presg' and not exists (
    select 1 from private.presg_demo_runs row
    where row.id = p_run_id and row.state in ('applied', 'verified')
  ) then
    raise exception 'presg demo run is not applied';
  end if;
  if p_lane = 'uniondemo' and not exists (
    select 1 from private.uniondemo_runs row
    where row.id = p_run_id and row.state in ('applied', 'verified')
  ) then
    raise exception 'union demo run is not applied';
  end if;
  if not exists (
    select 1 from public.organizations row
    where row.id = organization_id and row.status = 'active'
  ) then
    raise exception 'demo organization is missing';
  end if;

  perform private.demo_seed_remove_casework(p_lane, p_run_id);
  featured_chapter := private.demo_seed_chapter(p_lane, p_run_id, 1);
  featured_steward := private.demo_seed_user(p_lane, p_run_id, 1);
  grant_user := private.demo_seed_user(p_lane, p_run_id, 2);

  select pg_catalog.array_agg(expected.id order by expected.ordinal)
  into case_ids
  from (
    select numbered.ordinal,
      private.member_stress_uuid(p_run_id::text || ':parity:case:' || numbered.ordinal) as id
    from pg_catalog.generate_series(1, 120) as numbered(ordinal)
  ) as expected
  join public.member_cases row
    on row.id = expected.id
   and row.organization_id = organization_id
   and row.chapter_id is not null;
  if coalesce(pg_catalog.array_length(case_ids, 1), 0) < 120 then
    raise exception 'casework parity requires at least 120 organization-scoped cases';
  end if;

  for case_row in
    select row.id,
      row.chapter_id,
      row.user_id,
      numbered.ordinal::integer,
      coalesce(
        pg_catalog.lead(row.id) over (partition by row.chapter_id order by numbered.ordinal),
        pg_catalog.first_value(row.id) over (partition by row.chapter_id order by numbered.ordinal)
      ) as next_case_id
    from pg_catalog.unnest(case_ids) with ordinality as numbered(id, ordinal)
    join public.member_cases row on row.id = numbered.id
    order by numbered.ordinal
  loop
    case_id := case_row.id;
    next_case_id := case_row.next_case_id;
    template_id := private.member_stress_uuid(p_run_id::text || ':casework:template:' || case_row.ordinal);
    checklist_id := private.member_stress_uuid(p_run_id::text || ':casework:checklist:' || case_row.ordinal);
    alert_id := private.member_stress_uuid(p_run_id::text || ':casework:alert:' || case_row.ordinal);
    deadline_id := private.member_stress_uuid(p_run_id::text || ':casework:deadline:' || case_row.ordinal);
    management_person_id := private.member_stress_uuid(p_run_id::text || ':casework:management-person:' || case_row.ordinal);
    management_entry_id := private.member_stress_uuid(p_run_id::text || ':casework:management-entry:' || case_row.ordinal);
    retaliation_report_id := private.member_stress_uuid(p_run_id::text || ':casework:retaliation-report:' || case_row.ordinal);

    perform pg_catalog.set_config(
      'unionground.demo_seed_casework_scope',
      pg_catalog.jsonb_build_object(
        'lane', p_lane, 'runId', p_run_id, 'organizationId', organization_id
      )::text,
      true
    );
    begin
  perform set_config('app.sensitive_seed_ticket', coalesce((select id::text from private.sensitive_write_tickets where operation='demo_seed' and arguments=jsonb_build_object('lane',p_lane,'runId',p_run_id) and expires_at>clock_timestamp() order by expires_at desc limit 1),''),true);
      update public.member_cases row
      set steward_user_id = featured_steward,
          steward_name = 'Casework steward',
          assigned_at = pg_catalog.now() - ((121 - case_row.ordinal) || ' days')::interval,
          is_restricted = case_row.ordinal % 10 = 0,
          restriction_reason = case when case_row.ordinal % 10 = 0
            then 'Limited to the assigned team because the fictional file contains sensitive retaliation details.'
            else null end,
          restricted_at = case when case_row.ordinal % 10 = 0
            then pg_catalog.now() - ((121 - case_row.ordinal) || ' hours')::interval else null end,
          restricted_by = case when case_row.ordinal % 10 = 0 then featured_steward else null end
      where row.id = case_id and row.organization_id = organization_id;
    exception when others then
      perform pg_catalog.set_config('unionground.demo_seed_casework_scope', '', true);
      raise;
    end;
    perform pg_catalog.set_config('unionground.demo_seed_casework_scope', '', true);

    insert into public.casework_strength_analyses (
      id, case_id, organization_id, chapter_id, analyzed_by, inputs,
      score, band, recommendations, idempotency_key, created_at
    ) values (
      private.member_stress_uuid(p_run_id::text || ':casework:strength:' || case_row.ordinal),
      case_id, organization_id, case_row.chapter_id, featured_steward,
      pg_catalog.jsonb_build_object(
        'facts', 1 + (case_row.ordinal % 5),
        'documentation', 1 + ((case_row.ordinal + 1) % 5),
        'timeliness', 1 + ((case_row.ordinal + 2) % 5),
        'contract_support', 1 + ((case_row.ordinal + 3) % 5),
        'witnesses', 1 + ((case_row.ordinal + 4) % 5)
      ),
      35 + (case_row.ordinal % 61),
      case when case_row.ordinal % 3 = 0 then 'needs_evidence'
        when case_row.ordinal % 3 = 1 then 'developing' else 'strong' end,
      pg_catalog.jsonb_build_array(
        'Confirm the incident chronology.',
        'Attach the relevant contract language.'
      ),
      private.member_stress_uuid(p_run_id::text || ':casework:strength-idempotency:' || case_row.ordinal),
      pg_catalog.now() - ((121 - case_row.ordinal) || ' days')::interval
    );

    insert into public.casework_deadlines (
      id, case_id, organization_id, chapter_id, kind, label, due_at, status,
      reminder_at, created_by, created_at, updated_at
    ) values (
      deadline_id, case_id, organization_id, case_row.chapter_id,
      (array['filing','response','hearing','appeal','follow_up'])[1 + (case_row.ordinal % 5)],
      'Case milestone ' || pg_catalog.lpad(case_row.ordinal::text, 3, '0'),
      pg_catalog.now() + ((case_row.ordinal % 45) || ' days')::interval + interval '12 hours',
      (array['active','met','extended','waived','missed'])[1 + (case_row.ordinal % 5)],
      pg_catalog.now() + ((case_row.ordinal % 45) || ' days')::interval,
      featured_steward,
      pg_catalog.now() - ((121 - case_row.ordinal) || ' days')::interval,
      pg_catalog.now() - ((121 - case_row.ordinal) || ' hours')::interval
    );

    insert into public.casework_deadline_extensions (
      id, deadline_id, organization_id, requested_by, previous_due_at,
      requested_due_at, reason, status, decided_by, decided_at, decision_note,
      idempotency_key, created_at
    ) values (
      private.member_stress_uuid(p_run_id::text || ':casework:extension:' || case_row.ordinal),
      deadline_id, organization_id, case_row.user_id,
      pg_catalog.now() + ((case_row.ordinal % 45) || ' days')::interval + interval '12 hours',
      pg_catalog.now() + ((case_row.ordinal % 45 + 7) || ' days')::interval + interval '12 hours',
      'Additional time is requested to obtain the fictional records needed for a complete review.',
      case when case_row.ordinal % 3 = 0 then 'requested'
        when case_row.ordinal % 3 = 1 then 'approved' else 'denied' end,
      case when case_row.ordinal % 3 = 0 then null else featured_steward end,
      case when case_row.ordinal % 3 = 0 then null else pg_catalog.now() - interval '2 hours' end,
      case when case_row.ordinal % 3 = 0 then null
        when case_row.ordinal % 3 = 1 then 'Approved after review of the documented request.'
        else 'The existing milestone remains achievable with the available records.' end,
      private.member_stress_uuid(p_run_id::text || ':casework:extension-idempotency:' || case_row.ordinal),
      pg_catalog.now() - ((121 - case_row.ordinal) || ' hours')::interval
    );

    insert into public.casework_checklist_templates (
      id, organization_id, chapter_id, case_type, step, title, items,
      active, created_by, created_at, updated_at
    ) values (
      template_id, organization_id, case_row.chapter_id,
      (array['Discipline','Scheduling','Safety','Pay'])[1 + (case_row.ordinal % 4)],
      (array['Intake','Investigation','Step 1','Review'])[1 + (case_row.ordinal % 4)],
      'Case preparation template ' || pg_catalog.lpad(case_row.ordinal::text, 3, '0'),
      '[{"label":"Confirm timeline","required":true},{"label":"Collect records","required":true},{"label":"Review contract language","required":true}]'::jsonb,
      true, featured_steward,
      pg_catalog.now() - ((121 - case_row.ordinal) || ' days')::interval,
      pg_catalog.now() - ((121 - case_row.ordinal) || ' hours')::interval
    );

    insert into public.casework_checklists (
      id, case_id, organization_id, chapter_id, template_id, step, title,
      created_by, created_at, completed_at
    ) values (
      checklist_id, case_id, organization_id, case_row.chapter_id, template_id,
      (array['Intake','Investigation','Step 1','Review'])[1 + (case_row.ordinal % 4)],
      'Current case preparation', featured_steward,
      pg_catalog.now() - ((121 - case_row.ordinal) || ' days')::interval,
      case when case_row.ordinal % 4 = 3 then pg_catalog.now() - interval '1 day' else null end
    );

    insert into public.casework_checklist_items (
      id, checklist_id, organization_id, label, position, required,
      completed_at, completed_by
    )
    select
      private.member_stress_uuid(p_run_id::text || ':casework:checklist-item:' || case_row.ordinal || ':' || item.position),
      checklist_id, organization_id, item.label, item.position, true,
      case when item.position < (case_row.ordinal % 4) then pg_catalog.now() - interval '1 day' else null end,
      case when item.position < (case_row.ordinal % 4) then featured_steward else null end
    from (values
      (0, 'Confirm the member chronology'),
      (1, 'Collect supporting records'),
      (2, 'Review the governing language')
    ) as item(position, label);

    insert into public.casework_step_transitions (
      id, case_id, organization_id, chapter_id, from_step, to_step, outcome,
      transitioned_by, idempotency_key, created_at
    ) values (
      private.member_stress_uuid(p_run_id::text || ':casework:transition:' || case_row.ordinal),
      case_id, organization_id, case_row.chapter_id,
      (array['Intake','Investigation','Step 1','Step 2'])[1 + (case_row.ordinal % 4)],
      (array['Investigation','Step 1','Step 2','Review'])[1 + (case_row.ordinal % 4)],
      'The fictional file advanced after its required preparation items were reviewed.',
      featured_steward,
      private.member_stress_uuid(p_run_id::text || ':casework:transition-idempotency:' || case_row.ordinal),
      pg_catalog.now() - ((121 - case_row.ordinal) || ' hours')::interval
    );

    insert into public.casework_alerts (
      id, case_id, organization_id, chapter_id, kind, severity, message, status,
      escalation_due_at, escalated_at, resolved_at, created_by, created_at
    ) values (
      alert_id, case_id, organization_id, case_row.chapter_id,
      (array['deadline','safety','retaliation','legal','stalled','custom'])[1 + (case_row.ordinal % 6)],
      (array['info','warning','critical'])[1 + (case_row.ordinal % 3)],
      'Review the case condition and record the next authorized action.',
      (array['open','acknowledged','escalated','resolved'])[1 + (case_row.ordinal % 4)],
      pg_catalog.now() + ((case_row.ordinal % 5 - 2) || ' days')::interval,
      case when case_row.ordinal % 4 = 2 then pg_catalog.now() - interval '2 hours' else null end,
      case when case_row.ordinal % 4 = 3 then pg_catalog.now() - interval '1 hour' else null end,
      featured_steward,
      pg_catalog.now() - ((121 - case_row.ordinal) || ' hours')::interval
    );

    if case_row.ordinal % 4 = 1 then
      insert into public.casework_alert_acknowledgements (
        id, alert_id, organization_id, acknowledged_by, note, created_at
      ) values (
        private.member_stress_uuid(p_run_id::text || ':casework:alert-ack:' || case_row.ordinal),
        alert_id, organization_id, featured_steward,
        'The alert was reviewed and the next step was recorded.',
        pg_catalog.now() - ((121 - case_row.ordinal) || ' minutes')::interval
      );
    end if;

    insert into public.casework_management_people (
      id, organization_id, chapter_id, display_name, title, workplace,
      created_by, created_at, updated_at
    ) values (
      management_person_id, organization_id, case_row.chapter_id,
      'Management contact ' || pg_catalog.lpad(case_row.ordinal::text, 3, '0'),
      (array['Program manager','Operations director','Shift supervisor'])[1 + (case_row.ordinal % 3)],
      'Regional service site ' || (1 + (case_row.ordinal % 12)),
      featured_steward,
      pg_catalog.now() - ((121 - case_row.ordinal) || ' days')::interval,
      pg_catalog.now() - ((121 - case_row.ordinal) || ' hours')::interval
    );

    insert into public.casework_management_entries (
      id, management_person_id, case_id, organization_id, chapter_id,
      occurred_at, category, summary, created_by, created_at
    ) values (
      management_entry_id, management_person_id, case_id, organization_id,
      case_row.chapter_id,
      pg_catalog.now() - ((121 - case_row.ordinal) || ' days')::interval,
      (array['discipline','scheduling','safety','retaliation','bargaining','other'])[1 + (case_row.ordinal % 6)],
      'A factual fictional observation records the workplace conduct, participants, and immediate follow-up.',
      featured_steward,
      pg_catalog.now() - ((121 - case_row.ordinal) || ' days')::interval
    );

    insert into public.casework_management_addenda (
      id, entry_id, organization_id, body, created_by, created_at
    ) values (
      private.member_stress_uuid(p_run_id::text || ':casework:management-addendum:' || case_row.ordinal),
      management_entry_id, organization_id,
      'Follow-up confirmed the record and preserved the original observation unchanged.',
      featured_steward,
      pg_catalog.now() - ((121 - case_row.ordinal) || ' hours')::interval
    );

    insert into public.casework_retaliation_reports (
      id, organization_id, chapter_id, reporter_user_id, case_id, incident_at,
      management_person, protected_activity, adverse_action, requested_support,
      status, withdrawn_at, withdrawal_reason, idempotency_key, created_at, updated_at
    ) values (
      retaliation_report_id, organization_id, case_row.chapter_id, case_row.user_id,
      case_id,
      pg_catalog.now() - ((121 - case_row.ordinal) || ' days')::interval,
      '[encrypted]',
      '[encrypted]',
      '[encrypted]',
      '[encrypted]',
      case when case_row.ordinal % 4 = 0 then 'withdrawn'
        when case_row.ordinal % 4 = 1 then 'submitted'
        when case_row.ordinal % 4 = 2 then 'in_review' else 'closed' end,
      case when case_row.ordinal % 4 = 0 then pg_catalog.now() - interval '2 hours' else null end,
      case when case_row.ordinal % 4 = 0 then '[encrypted]' else null end,
      private.member_stress_uuid(p_run_id::text || ':casework:retaliation-idempotency:' || case_row.ordinal),
      pg_catalog.now() - ((121 - case_row.ordinal) || ' days')::interval,
      pg_catalog.now() - ((121 - case_row.ordinal) || ' hours')::interval
    );

    insert into public.casework_intake_drafts (
      id, organization_id, chapter_id, owner_user_id, member_user_id, case_id,
      payload, revision, created_at, updated_at
    ) values (
      private.member_stress_uuid(p_run_id::text || ':casework:draft:' || case_row.ordinal),
      organization_id, case_row.chapter_id, featured_steward, case_row.user_id,
      case_id,
      pg_catalog.jsonb_build_object(
        'summary', 'Draft intake for a fictional workplace concern.',
        'assignmentHint', case when case_row.ordinal % 2 = 0 then 'steward' else 'coordinator' end,
        'seedSequence', case_row.ordinal
      ),
      1 + (case_row.ordinal % 5),
      pg_catalog.now() - ((121 - case_row.ordinal) || ' days')::interval,
      pg_catalog.now() - ((121 - case_row.ordinal) || ' minutes')::interval
    );

    insert into public.casework_entity_links (
      id, organization_id, chapter_id, source_case_id, target_case_id,
      target_kind, target_id, relationship, note, created_by, created_at
    ) values (
      private.member_stress_uuid(p_run_id::text || ':casework:entity-link:' || case_row.ordinal),
      organization_id, case_row.chapter_id, case_id, next_case_id,
      'case', next_case_id, 'related workplace pattern',
      'The fictional files share a workplace condition and require coordinated review.',
      featured_steward,
      pg_catalog.now() - ((121 - case_row.ordinal) || ' hours')::interval
    );

    insert into public.casework_reminders (
      id, case_id, organization_id, chapter_id, owner_user_id, title, remind_at,
      recurrence, status, last_fired_at, completed_at, created_at, updated_at
    ) values (
      private.member_stress_uuid(p_run_id::text || ':casework:reminder:' || case_row.ordinal),
      case_id, organization_id, case_row.chapter_id, featured_steward,
      'Case follow-up ' || pg_catalog.lpad(case_row.ordinal::text, 3, '0'),
      pg_catalog.now() + ((case_row.ordinal % 30) || ' days')::interval,
      (array['none','daily','weekly','monthly'])[1 + (case_row.ordinal % 4)],
      (array['scheduled','snoozed','completed','dismissed'])[1 + (case_row.ordinal % 4)],
      case when case_row.ordinal % 4 in (2, 3) then pg_catalog.now() - interval '1 day' else null end,
      case when case_row.ordinal % 4 = 2 then pg_catalog.now() - interval '1 day' else null end,
      pg_catalog.now() - ((121 - case_row.ordinal) || ' days')::interval,
      pg_catalog.now() - ((121 - case_row.ordinal) || ' hours')::interval
    );

    if case_row.ordinal % 10 = 0 then
      insert into public.casework_access_grants (
        id, case_id, organization_id, chapter_id, grantee_user_id,
        granted_by, reason, granted_at
      ) values (
        private.member_stress_uuid(p_run_id::text || ':casework:grant:' || case_row.ordinal),
        case_id, organization_id, case_row.chapter_id, grant_user,
        featured_steward,
        'Temporary access for coordinated review of this restricted fictional file.',
        pg_catalog.now() - ((121 - case_row.ordinal) || ' hours')::interval
      );
    end if;

    insert into public.casework_audit_events (
      organization_id, chapter_id, case_id, actor_user_id, event_type,
      entity_type, entity_id, metadata, created_at
    ) values (
      organization_id, case_row.chapter_id, case_id, featured_steward,
      (array['strength_scored','deadline_requested','checklist_created','step_advanced',
        'restriction_changed','alert_acknowledged','behavior_logged','retaliation_submitted',
        'draft_saved','bulk_updated','entity_linked','reminder_changed'])[1 + (case_row.ordinal % 12)],
      'case', case_id,
      pg_catalog.jsonb_build_object(
        'reasonCode', 'sample-seed',
        'runId', p_run_id::text,
        'seedSequence', case_row.ordinal
      ),
      pg_catalog.now() - ((121 - case_row.ordinal) || ' minutes')::interval
    );
  end loop;

  for workspace_ordinal in 1..50 loop
    workspace_id := private.member_stress_uuid(
      p_run_id::text || ':casework:bargaining-workspace:' || workspace_ordinal
    );
    insert into public.casework_bargaining_workspaces (
      id, organization_id, chapter_id, title, status, starts_at,
      created_by, created_at, updated_at
    ) values (
      workspace_id, organization_id, featured_chapter,
      'Negotiation workspace ' || pg_catalog.lpad(workspace_ordinal::text, 2, '0'),
      (array['planning','live','paused','tentative_agreement','closed'])[1 + (workspace_ordinal % 5)],
      pg_catalog.now() + ((workspace_ordinal - 25) || ' days')::interval,
      featured_steward,
      pg_catalog.now() - ((51 - workspace_ordinal) || ' days')::interval,
      pg_catalog.now() - ((51 - workspace_ordinal) || ' hours')::interval
    );

    for report_ordinal in 1..2 loop
      proposal_id := private.member_stress_uuid(
        p_run_id::text || ':casework:bargaining-proposal:' || workspace_ordinal || ':' || report_ordinal
      );
      insert into public.casework_bargaining_proposals (
        id, workspace_id, organization_id, side, title, body, status,
        response_due_at, position, created_by, created_at, updated_at
      ) values (
        proposal_id, workspace_id, organization_id,
        case when report_ordinal = 1 then 'union' else 'management' end,
        case when report_ordinal = 1 then 'Scheduling safeguards' else 'Operational flexibility' end,
        'A realistic fictional proposal records the current position, supporting rationale, and response path.',
        (array['draft','proposed','countered','tentative','accepted','rejected','withdrawn'])
          [1 + ((workspace_ordinal + report_ordinal) % 7)],
        pg_catalog.now() + ((workspace_ordinal % 14) || ' days')::interval,
        report_ordinal - 1, featured_steward,
        pg_catalog.now() - ((51 - workspace_ordinal) || ' days')::interval,
        pg_catalog.now() - ((51 - workspace_ordinal) || ' hours')::interval
      );
    end loop;

    for event_ordinal in 1..6 loop
      proposal_id := private.member_stress_uuid(
        p_run_id::text || ':casework:bargaining-proposal:' || workspace_ordinal || ':' || (1 + (event_ordinal % 2))
      );
      insert into public.casework_bargaining_events (
        id, workspace_id, organization_id, proposal_id, event_type, body,
        pulse, created_by, created_at
      ) values (
        private.member_stress_uuid(
          p_run_id::text || ':casework:bargaining-event:' || workspace_ordinal || ':' || event_ordinal
        ),
        workspace_id, organization_id,
        case when event_ordinal % 3 = 0 then null else proposal_id end,
        (array['note','proposal_status','session_status','pulse'])[1 + (event_ordinal % 4)],
        'Session note ' || event_ordinal || ' records movement, open questions, and the next caucus action.',
        case when event_ordinal % 4 = 3
          then (array['steady','watch','urgent'])[1 + (workspace_ordinal % 3)] else null end,
        featured_steward,
        pg_catalog.now() - ((301 - ((workspace_ordinal - 1) * 6 + event_ordinal)) || ' minutes')::interval
      );
    end loop;
  end loop;

  for pattern_row in
    select report.chapter_id,
      pg_catalog.lower(pg_catalog.btrim(('Management contact ' || (1 + (seed.ordinal % 10))))) as person_key,
      pg_catalog.min(('Management contact ' || (1 + (seed.ordinal % 10)))) as subject_label,
      pg_catalog.count(*)::integer as report_count
    from public.casework_retaliation_reports report join generate_series(1,120) seed(ordinal) on report.id=private.member_stress_uuid(p_run_id::text || ':casework:retaliation-report:' || seed.ordinal)
    where report.organization_id = organization_id
      and report.status <> 'withdrawn'
      and report.incident_at >= pg_catalog.now() - interval '3 years'
    group by report.chapter_id, pg_catalog.lower(pg_catalog.btrim(('Management contact ' || (1 + (seed.ordinal % 10)))))
    having pg_catalog.count(*) >= 2
    order by report.chapter_id, pg_catalog.lower(pg_catalog.btrim(('Management contact ' || (1 + (seed.ordinal % 10)))))
  loop
    pattern_id := private.member_stress_uuid(
      p_run_id::text || ':casework:retaliation-pattern:'
        || pattern_row.chapter_id || ':' || pattern_row.person_key
    );
    insert into public.casework_retaliation_patterns (
      id, organization_id, chapter_id, fingerprint, subject_label,
      report_count, status, disposition, detected_at, reviewed_by, reviewed_at
    ) values (
      pattern_id, organization_id, pattern_row.chapter_id,
      pattern_id::text,
      '[encrypted]',
      pattern_row.report_count,
      (array['flagged','investigating','substantiated','dismissed'])
        [1 + (pattern_row.report_count % 4)],
      case when pattern_row.report_count % 2 = 0
        then 'Coordinated follow-up is documented.' else null end,
      pg_catalog.now() - interval '10 days',
      case when pattern_row.report_count % 2 = 0 then featured_steward else null end,
      case when pattern_row.report_count % 2 = 0 then pg_catalog.now() - interval '1 day' else null end
    );

    insert into public.casework_retaliation_pattern_reports (
      pattern_id, report_id, organization_id
    )
    select pattern_id, report.id, organization_id
    from public.casework_retaliation_reports report join generate_series(1,120) seed(ordinal) on report.id=private.member_stress_uuid(p_run_id::text || ':casework:retaliation-report:' || seed.ordinal)
    where report.organization_id = organization_id
      and report.chapter_id = pattern_row.chapter_id
      and report.status <> 'withdrawn'
      and report.incident_at >= pg_catalog.now() - interval '3 years'
      and pg_catalog.lower(pg_catalog.btrim(('Management contact ' || (1 + (seed.ordinal % 10))))) = pattern_row.person_key;

    insert into public.casework_retaliation_pattern_notes (
      id, pattern_id, organization_id, body, created_by, created_at
    ) values (
      private.member_stress_uuid(
        p_run_id::text || ':casework:retaliation-pattern-note:'
          || pattern_row.chapter_id || ':' || pattern_row.person_key
      ),
      pattern_id, organization_id,
      'The review note distinguishes shared facts from assumptions and records the authorized next action.',
      featured_steward,
      pg_catalog.now() - interval '10 hours'
    );
  end loop;

  result := private.demo_seed_casework_status(p_lane, p_run_id);
  if not coalesce((result ->> 'ok')::boolean, false) then
    raise exception 'casework SAMPLE parity verification failed: %', result;
  end if;
  perform set_config('app.sensitive_seed_ticket','',true);
  return result;
end;
end;
end;
$function$

CREATE OR REPLACE FUNCTION private.demo_seed_apply_dues(p_lane text, p_run_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  perform private.lock_case_graph(array[auth.uid()], array[]::uuid[]);

begin
  perform private.lock_message_lifecycle();

declare
  org uuid := private.dues_sample_seed_organization(p_lane, p_run_id);
  featured_user uuid;
  subject_id uuid;
  existing private.dues_sample_seed_runs%rowtype;
  ordinal integer;
  batch_id uuid;
  obligation_id uuid;
  assessment_event_id uuid;
  settlement_event_id uuid;
  reminder_id uuid;
  due_date date;
  settlement_kind text;
  settlement_amount integer;
  settlement_method text;
begin
  if p_lane not in ('presg', 'uniondemo') then
    raise exception 'unknown demo lane' using errcode = '22023';
  end if;
  if exists (
    select 1 from public.dues_provider_connections connection
    where connection.organization_id = org and connection.state <> 'unset'
  ) then
    raise exception 'SAMPLE Stripe must remain unset' using errcode = '55000';
  end if;
  featured_user := private.demo_seed_user(p_lane, p_run_id, 1);
  select subject.id into subject_id
  from public.dues_member_subjects subject
  where subject.organization_id = org and subject.user_id = featured_user;
  if subject_id is null then
    raise exception 'Dues subject provisioning incomplete' using errcode = '55000';
  end if;
  select * into existing from private.dues_sample_seed_runs row
  where row.lane = p_lane and row.run_id = p_run_id for update;
  if found and existing.state = 'applied' then
    return private.demo_seed_verify_dues(p_lane, p_run_id);
  end if;
  if found and existing.state = 'removed' then
    raise exception 'removed Dues SAMPLE run cannot be reapplied' using errcode = '55000';
  end if;
  insert into private.dues_sample_seed_runs (lane, run_id, organization_id, featured_subject_id, state, updated_at)
  values (p_lane, p_run_id, org, subject_id, 'applying', now())
  on conflict (lane, run_id) do update set state = 'applying', updated_at = now();

  for ordinal in 1..60 loop
    batch_id := private.member_stress_uuid(p_run_id::text || ':dues:batch:' || ordinal::text);
    obligation_id := private.member_stress_uuid(p_run_id::text || ':dues:obligation:' || ordinal::text);
    assessment_event_id := private.member_stress_uuid(p_run_id::text || ':dues:assessment:' || ordinal::text);
    settlement_event_id := null;
    reminder_id := null;
    -- 50 dated historical obligations at 22-day intervals reach slightly past
    -- three years while the first ten retain a realistic current/future mix.
    due_date := case when ordinal <= 10 then current_date + ordinal else current_date - ((ordinal - 10) * 22) end;
    insert into public.dues_assessment_batches (
      id, organization_id, chapter_id, title, description, scope_kind, amount_cents,
      currency, due_on, eligibility_fingerprint, idempotency_key, created_by, created_at
    ) values (
      batch_id, org, null, 'Monthly membership contribution',
      'A regular contribution supporting member services and chapter work.',
      'organization', 5000, 'USD', due_date,
      pg_catalog.encode(extensions.digest(p_run_id::text || ':dues:fingerprint:' || ordinal::text, 'sha256'), 'hex'),
      'dues-sample-batch:' || p_run_id::text || ':' || ordinal::text,
      null, due_date::timestamptz
    ) on conflict (id) do nothing;
    insert into public.dues_obligations (
      id, organization_id, batch_id, member_subject_id, chapter_id, issued_cents, due_on, created_at
    ) values (
      obligation_id, org, batch_id, subject_id, null, 5000, due_date, due_date::timestamptz
    ) on conflict (id) do nothing;
    insert into public.dues_ledger_events (
      id, organization_id, obligation_id, event_kind, amount_cents, effective_on,
      reason, payment_method, external_reference, receipt_number, idempotency_key, created_by, created_at
    ) values (
      assessment_event_id, org, obligation_id, 'assessment', 5000, due_date,
      'Monthly membership contribution', null, null, null,
      'dues-sample-assessment:' || p_run_id::text || ':' || ordinal::text, null, due_date::timestamptz
    ) on conflict (id) do nothing;

    settlement_kind := case when ordinal % 4 = 0 then 'waiver' when ordinal % 4 in (2, 3) then 'payment' else null end;
    settlement_amount := case when ordinal % 4 = 2 then 2500 else 5000 end;
    settlement_method := case when ordinal % 4 = 2 then 'manual_cash' when ordinal % 4 = 3 then 'manual_check' else null end;
    if settlement_kind is not null then
      settlement_event_id := private.member_stress_uuid(p_run_id::text || ':dues:settlement:' || ordinal::text);
      insert into public.dues_ledger_events (
        id, organization_id, obligation_id, event_kind, amount_cents, effective_on,
        reason, payment_method, external_reference, receipt_number, idempotency_key, created_by, created_at
      ) values (
        settlement_event_id, org, obligation_id, settlement_kind, settlement_amount,
        due_date + 3,
        case when settlement_kind = 'waiver' then 'Approved hardship waiver' else 'Recorded member contribution' end,
        settlement_method, null,
        case when settlement_kind = 'payment' then 'UG-' || extract(year from due_date)::text || '-' || pg_catalog.substr(pg_catalog.replace(p_run_id::text, '-', ''), 1, 8) || '-' || pg_catalog.lpad(ordinal::text, 3, '0') else null end,
        'dues-sample-settlement:' || p_run_id::text || ':' || ordinal::text,
        null, (due_date + 3)::timestamptz
      ) on conflict (id) do nothing;
    end if;
    if ordinal % 4 = 1 and ordinal > 10 then
      reminder_id := private.member_stress_uuid(p_run_id::text || ':dues:reminder:' || ordinal::text);
      insert into public.dues_reminder_attempts (
        id, organization_id, obligation_id, policy_window, channel, state,
        lease_epoch, attempt_count, outcome_code, request_idempotency_key, created_by, created_at, updated_at
      ) values (
        reminder_id, org, obligation_id, due_date, 'in_app', 'sent', 0, 1,
        'sample_seeded', 'dues-sample-reminder:' || p_run_id::text || ':' || ordinal::text,
        null, (due_date + 7)::timestamptz, (due_date + 7)::timestamptz
      ) on conflict (id) do nothing;
    end if;
    insert into private.dues_sample_seed_ledger (
      lane, run_id, ordinal, batch_id, obligation_id, assessment_event_id, settlement_event_id, reminder_attempt_id
    ) values (
      p_lane, p_run_id, ordinal, batch_id, obligation_id, assessment_event_id, settlement_event_id, reminder_id
    ) on conflict (lane, run_id, ordinal) do nothing;
  end loop;

  insert into private.demo_seed_page_contract (surface, page_size, minimum_rows, scope, source)
  values
    ('duesStaffObligations', 25, 50, 'organization', 'supabase/migrations/20260831170400_mi1_dues_settlement_reconciliation.sql'),
    ('duesMemberHistory', 25, 50, 'featured-member', 'supabase/migrations/20260831170400_mi1_dues_settlement_reconciliation.sql')
  on conflict (surface) do update set page_size = excluded.page_size, minimum_rows = excluded.minimum_rows,
    scope = excluded.scope, source = excluded.source;
  insert into private.demo_seed_page_evidence (lane, run_id, surface, actual_rows)
  values (p_lane, p_run_id, 'duesStaffObligations', 60), (p_lane, p_run_id, 'duesMemberHistory', 60)
  on conflict (lane, run_id, surface) do update set actual_rows = excluded.actual_rows, recorded_at = now();
  update private.dues_sample_seed_runs
  set state = 'applied', applied_at = coalesce(applied_at, now()), updated_at = now()
  where lane = p_lane and run_id = p_run_id;
  return private.demo_seed_verify_dues(p_lane, p_run_id);
end;
end;
end;
$function$

CREATE OR REPLACE FUNCTION private.demo_seed_apply_function_parity(p_lane text, p_run_id uuid, p_target_ref text, p_confirm_token text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET statement_timeout TO '300s'
AS $function$
begin
  perform private.lock_case_graph(array[auth.uid()], array[]::uuid[]);

begin
  perform private.lock_message_lifecycle();

declare
  v_organization_id uuid;
  chapter_id text;
  featured_user uuid;
  featured_steward uuid;
  featured_conversation uuid;
  template_key text;
  template_version integer;
  row_user uuid;
  row_chapter text;
  row_id uuid;
  i integer;
  page_result jsonb;
  gate record;
begin
  if p_lane = 'presg' then
    perform private.presg_demo_authorize(p_target_ref, p_confirm_token);
    if not exists (select 1 from private.presg_demo_runs where id = p_run_id and state in ('applied', 'verified')) then
      raise exception 'presg demo run must be applied before parity data';
    end if;
    v_organization_id := private.member_stress_uuid(p_run_id::text || ':presg:organization');
  elsif p_lane = 'uniondemo' then
    perform private.uniondemo_authorize(p_target_ref, p_confirm_token);
    if not exists (select 1 from private.uniondemo_runs where id = p_run_id and state in ('applied', 'verified')) then
      raise exception 'union demo run must be applied before parity data';
    end if;
    v_organization_id := private.member_stress_uuid(p_run_id::text || ':ud:organization');
  else
    raise exception 'unknown demo lane';
  end if;

  if not exists (select 1 from public.organizations o where o.id = v_organization_id and o.status = 'active') then
    raise exception 'demo organization is missing';
  end if;

  for gate in
    select function_id, gate_relation from private.demo_seed_function_catalog
    where coverage = 'schema-not-yet-landed' and gate_relation is not null
  loop
    if pg_catalog.to_regclass(gate.gate_relation) is not null then
      raise exception '% schema has landed; add deterministic seed evidence before applying', gate.function_id;
    end if;
  end loop;

  chapter_id := private.demo_seed_chapter(p_lane, p_run_id, 1);
  featured_steward := private.demo_seed_user(p_lane, p_run_id, 1);
  featured_user := private.demo_seed_user(p_lane, p_run_id, 2);
  featured_conversation := private.member_stress_uuid(p_run_id::text || ':parity:featured-conversation');

  select key, version into template_key, template_version
  from public.form_templates where active and is_platform_seed order by key, version desc limit 1;
  if template_key is null then raise exception 'an active form template is required'; end if;

  for i in 1..400 loop
    row_user := private.demo_seed_user(p_lane, p_run_id, i + 2);
    row_chapter := private.demo_seed_chapter(p_lane, p_run_id, i + 2);

    if i <= 200 then
      insert into public.member_steward_requests (id, user_id, status, created_at)
      values (private.member_stress_uuid(p_run_id::text || ':parity:request:' || i), row_user,
        (array['requested','acknowledged','closed'])[1 + (i % 3)], pg_catalog.now() - (i || ' hours')::interval)
      on conflict (id) do nothing;
    end if;

    if i <= 100 then
      row_id := private.member_stress_uuid(p_run_id::text || ':parity:conversation:' || i);
      insert into public.member_conversations (id, user_id, title, initials, created_at, updated_at)
      values (row_id, row_user, 'Workplace question ' || i, 'UG',
        pg_catalog.now() - (i || ' days')::interval, pg_catalog.now() - (i || ' hours')::interval)
      on conflict (id) do nothing;
      insert into public.member_messages (id, conversation_id, user_id, sender_kind, sender_name, body, created_at)
      values (private.member_stress_uuid(p_run_id::text || ':parity:conversation-message:' || i), row_id,
        row_user, case when i % 2 = 0 then 'member' else 'steward' end,
        case when i % 2 = 0 then 'Member' else 'Chapter steward' end,
        'Deterministic conversation preview ' || i || ' with enough detail to exercise search and paging.',
        pg_catalog.now() - (i || ' hours')::interval)
      on conflict (id) do nothing;

      insert into public.member_forms
        (id, user_id, template_key, template_version, status, answers, step, submitted_at, created_at, updated_at)
      values (private.member_stress_uuid(p_run_id::text || ':parity:form:' || i), row_user,
        template_key, template_version, case when i % 3 = 0 then 'in_review' else 'submitted' end,
        pg_catalog.jsonb_build_object('seedSequence', i), 1,
        pg_catalog.now() - (i || ' hours')::interval,
        pg_catalog.now() - (i || ' days')::interval, pg_catalog.now() - (i || ' hours')::interval)
      on conflict (id) do nothing;

      row_id := private.member_stress_uuid(p_run_id::text || ':parity:qa:' || i);
      insert into public.member_qa_questions
        (id, organization_id, chapter_id, author_user_id, title, body, status, upvote_count,
         idempotency_key, created_at, updated_at)
      values (row_id, v_organization_id, row_chapter, row_user,
        'Member question ' || pg_catalog.lpad(i::text, 3, '0') || ' about workplace rights',
        'A realistic fictional question used to exercise the member Q&A list, filters, and second page.',
        (array['open','replied','accepted'])[1 + (i % 3)], i % 17,
        private.member_stress_uuid(p_run_id::text || ':parity:qa-idempotency:' || i),
        pg_catalog.now() - (i || ' days')::interval, pg_catalog.now() - (i || ' hours')::interval)
      on conflict (id) do nothing;
    end if;

    insert into public.member_cases
      (id, user_id, reference, title, deadline, case_type, articles, step, status, created_at, updated_at)
    values (private.member_stress_uuid(p_run_id::text || ':parity:case:' || i), row_user,
      upper(p_lane) || '-PG-' || pg_catalog.lpad(i::text, 4, '0'),
      (array['Scheduling dispute','Overtime review','Safety follow-up','Discipline response'])[1 + (i % 4)] || ' ' || i,
      current_date + ((i % 120) - 30),
      (array['Contract enforcement','Discipline','Health and safety','Pay'])[1 + (i % 4)],
      case when i % 2 = 0 then 'Article 7' else 'Article 12' end,
      (array['Intake','Investigation','Step 1','Step 2','Review'])[1 + (i % 5)],
      case when i % 5 = 0 then 'resolved' else 'active' end,
      pg_catalog.now() - (i || ' days')::interval, pg_catalog.now() - (i || ' hours')::interval)
    on conflict (id) do nothing;
  end loop;

  insert into public.member_conversations (id, user_id, title, initials, created_at, updated_at)
  values (featured_conversation, featured_user, 'Scheduling follow-up archive', 'UG',
    pg_catalog.now() - interval '120 days', pg_catalog.now())
  on conflict (id) do update set updated_at = excluded.updated_at;

  for i in 1..100 loop
    insert into public.member_messages (id, conversation_id, user_id, sender_kind, sender_name, body, created_at)
    values (private.member_stress_uuid(p_run_id::text || ':parity:featured-message:' || i),
      featured_conversation, featured_user, case when i % 2 = 0 then 'member' else 'steward' end,
      case when i % 2 = 0 then 'Member' else 'Chapter steward' end,
      'Archived scheduling follow-up message ' || i || ' for deterministic two-page thread history.',
      pg_catalog.now() - ((101 - i) || ' hours')::interval)
    on conflict (id) do nothing;
  end loop;

  for i in 1..60 loop
    insert into public.member_point_events (id, user_id, action_key, action_kind, points, occurred_at)
    values (private.member_stress_uuid(p_run_id::text || ':parity:point:' || i), featured_user,
      'parity-' || p_run_id::text || '-' || i, 'rights', 1 + (i % 15),
      pg_catalog.now() - ((8 + i) || ' days')::interval)
    on conflict (id) do nothing;
  end loop;

  for i in 1..100 loop
    row_user := private.demo_seed_user(p_lane, p_run_id, i + 2);
    insert into public.member_appointments
      (id, user_id, steward_id, chapter_id, appointment_type, duration_minutes,
       starts_at, ends_at, status, routed_via, reason_category, created_at, updated_at)
    values (private.member_stress_uuid(p_run_id::text || ':parity:upcoming-appointment:' || i),
      row_user, featured_steward, chapter_id, (array['office_hours','grievance_followup','onboarding','contract_questions'])[1 + (i % 4)],
      30, (current_date + 400 + i)::timestamp at time zone 'America/New_York' + interval '15 hours',
      (current_date + 400 + i)::timestamp at time zone 'America/New_York' + interval '15 hours 30 minutes',
      'confirmed', 'steward', (array['general','pay','benefits','scheduling','safety'])[1 + (i % 5)],
      pg_catalog.now(), pg_catalog.now())
    on conflict (id) do nothing;
  end loop;

  for i in 1..40 loop
    row_user := private.demo_seed_user(p_lane, p_run_id, i + 102);
    insert into public.member_appointments
      (id, user_id, steward_id, chapter_id, appointment_type, duration_minutes,
       starts_at, ends_at, status, routed_via, reason_category, created_at, updated_at)
    values (private.member_stress_uuid(p_run_id::text || ':parity:recent-appointment:' || i),
      row_user, featured_steward, chapter_id, 'office_hours', 30,
      (current_date - 400 - i)::timestamp at time zone 'America/New_York' + interval '15 hours',
      (current_date - 400 - i)::timestamp at time zone 'America/New_York' + interval '15 hours 30 minutes',
      (array['completed','cancelled','no_show'])[1 + (i % 3)], 'steward', 'general',
      pg_catalog.now() - (i || ' days')::interval, pg_catalog.now() - (i || ' days')::interval)
    on conflict (id) do nothing;
  end loop;

  insert into public.organization_page_views (organization_id, path, hat, day, view_count)
  select v_organization_id, p.path, p.hat, current_date - d, 10 + ((d + p.n) % 90)
  from pg_catalog.generate_series(0, 119) d
  cross join (values (1, '/home', 'member'), (2, '/work', 'steward'),
    (3, '/casework', 'coordinator'), (4, '/admin', 'admin')) p(n, path, hat)
  on conflict (organization_id, path, hat, day) do update set view_count = excluded.view_count;

  insert into public.organization_engagement_events
    (organization_id, user_id, chapter_id, event_type, source_id, occurred_at)
  select v_organization_id, private.demo_seed_user(p_lane, p_run_id, series.n),
    private.demo_seed_chapter(p_lane, p_run_id, series.n),
    (array['meeting_check_in','qa_contribution','poll_vote','survey_response','event_rsvp','authorized_contact'])[1 + (series.n % 6)],
    p_lane || '-parity-engagement-' || series.n, pg_catalog.now() - (series.n || ' hours')::interval
  from pg_catalog.generate_series(1, 120) series(n)
  on conflict (organization_id, user_id, event_type, source_id) do nothing;

  insert into public.organization_analytics_exports
    (id, organization_id, export_format, expires_at, row_count, suppressed_count, created_by, created_at)
  select private.member_stress_uuid(p_run_id::text || ':parity:analytics-export:' || series.n),
    v_organization_id, case when series.n % 2 = 0 then 'csv' else 'json' end,
    pg_catalog.now() + interval '24 hours', 100 + series.n, series.n % 7, featured_steward,
    pg_catalog.now() - (series.n || ' hours')::interval
  from pg_catalog.generate_series(1, 20) series(n)
  on conflict (id) do nothing;

  insert into public.pay_scale_grades (organization_id, grade, title, job_family, step_count, description)
  select v_organization_id, 'G' || pg_catalog.lpad(series.n::text, 2, '0'),
    'Public service grade ' || series.n, (array['Direct care','Administration','Clinical','Operations'])[1 + (series.n % 4)],
    10, 'Fictional pay grade for calculator and table demonstrations.'
  from pg_catalog.generate_series(1, 12) series(n)
  on conflict (organization_id, grade) do update set title = excluded.title, step_count = excluded.step_count;

  insert into public.pay_scale_steps (organization_id, grade, effective_on, step_number, hourly_rate_cents)
  select v_organization_id, 'G' || pg_catalog.lpad(g::text, 2, '0'), date '2026-07-01', s,
    2000 + g * 125 + s * 55
  from pg_catalog.generate_series(1, 12) g cross join pg_catalog.generate_series(1, 10) s
  on conflict (organization_id, grade, effective_on, step_number)
  do update set hourly_rate_cents = excluded.hourly_rate_cents;

  insert into public.organization_integrations
    (id, organization_id, provider, status, account_owner, allow_chapter_overrides,
     allow_chapter_owned_accounts, allowed_chapter_override_keys, default_settings)
  select private.member_stress_uuid(p_run_id::text || ':parity:integration:' || p.provider),
    v_organization_id, p.provider,
    case when p.provider = 'scim' then 'disabled' else 'unset' end,
    'organization', p.provider in ('google_calendar','microsoft_calendar'), false,
    case when p.provider in ('google_calendar','microsoft_calendar') then array['enabled']::text[] else '{}'::text[] end,
    '{}'::jsonb
  from unnest(array['twilio','google_calendar','microsoft_calendar','constant_contact',
    'cba_ingest','customer_webhooks','customer_api','scim']) p(provider)
  on conflict (organization_id, provider) do update set status = excluded.status,
    credential_ref = null, default_settings = excluded.default_settings;

  insert into public.integration_webhooks
    (id, organization_id, url, events, secret_hash, active, last_delivery_status)
  values (private.member_stress_uuid(p_run_id::text || ':parity:webhook'), v_organization_id,
    'https://disabled.example.invalid/union-ground', array['case.updated'],
    pg_catalog.encode(extensions.digest(p_run_id::text || ':disabled-webhook', 'sha256'), 'hex'),
    false, 'blocked')
  on conflict (id) do update set active = false;

  insert into public.integration_api_keys
    (id, organization_id, name, key_hash, key_prefix, revoked_at, last_rotated_at)
  values (private.member_stress_uuid(p_run_id::text || ':parity:api-key'), v_organization_id,
    'Revoked demonstration key',
    pg_catalog.encode(extensions.digest(p_run_id::text || ':revoked-api-key', 'sha256'), 'hex'),
    'ug_demo', pg_catalog.now() - interval '30 days', pg_catalog.now() - interval '60 days')
  on conflict (id) do update set revoked_at = excluded.revoked_at;

  insert into public.organization_job_runs
    (id, organization_id, job_name, run_id, status, started_at, finished_at, failure_code, redacted_summary)
  select private.member_stress_uuid(p_run_id::text || ':parity:job:' || series.n), v_organization_id,
    (array['notifications-dispatch-tick','deadline-notices-tick','appointment-reminders-tick','task-maintenance-daily'])[1 + (series.n % 4)],
    p_lane || '-parity-' || series.n, (array['completed','failed','skipped'])[1 + (series.n % 3)],
    pg_catalog.now() - (series.n || ' hours')::interval, pg_catalog.now() - (series.n || ' hours')::interval + interval '2 minutes',
    case when series.n % 3 = 1 then 'sample-provider-disabled' else null end,
    'Fictional redacted job result; no provider delivery was attempted.'
  from pg_catalog.generate_series(1, 40) series(n)
  on conflict (job_name, run_id, organization_id) do nothing;

  insert into public.organization_audit_ledger
    (id, organization_id, domain, event_type, action, actor_user_id, entity_type,
     entity_id, occurred_at, idempotency_key, metadata, source)
  select private.member_stress_uuid(p_run_id::text || ':parity:audit-row:' || series.n), v_organization_id,
    (array['administration','casework','messages','data_access','communications','knowledge','operations','exports'])[1 + (series.n % 8)],
    'demo.parity.' || (series.n % 8), (array['create','update','read','export','settings_change','acknowledge'])[1 + (series.n % 6)],
    featured_steward, (array['organization','case','message','export','document','job_run'])[1 + (series.n % 6)],
    p_lane || '-parity-' || series.n, pg_catalog.now() - (series.n || ' hours')::interval,
    private.member_stress_uuid(p_run_id::text || ':parity:audit-idempotency:' || series.n),
    pg_catalog.jsonb_build_object('organizationId', v_organization_id, 'count', series.n,
      'reasonCode', 'sample-seed', 'runId', p_run_id::text), 'demo_seed'
  from pg_catalog.generate_series(1, 120) series(n)
  on conflict (idempotency_key) do nothing;

  insert into public.public_event_rsvps
    (id, organization_id, event_id, email, name, locale, created_at)
  select private.member_stress_uuid(p_run_id::text || ':parity:public-rsvp:' || series.n), v_organization_id,
    p_lane || '-public-open-house', p_lane || '-guest-' || series.n || '@example.invalid',
    'Community guest ' || series.n, case when series.n % 8 = 0 then 'es' else 'en' end,
    pg_catalog.now() - (series.n || ' minutes')::interval
  from pg_catalog.generate_series(1, 100) series(n)
  on conflict (event_id, email) do nothing;

  delete from private.demo_seed_function_evidence where lane = p_lane and run_id = p_run_id;
  insert into private.demo_seed_function_evidence
    (lane, run_id, function_id, status, evidence_key)
  select p_lane, p_run_id, function_id, coverage, evidence_key
  from private.demo_seed_function_catalog;

  page_result := private.demo_seed_record_page_evidence(
    p_lane, p_run_id, v_organization_id, featured_user, featured_steward, featured_conversation);
  if not (page_result ->> 'ok')::boolean then
    raise exception 'two-page seed contract failed: %', page_result;
  end if;

  return pg_catalog.jsonb_build_object(
    'ok', true,
    'functions', 114,
    'seededFunctions', (select pg_catalog.count(*) from private.demo_seed_function_catalog where coverage = 'seeded'),
    'schemaGates', (select pg_catalog.count(*) from private.demo_seed_function_catalog where coverage = 'schema-not-yet-landed'),
    'pageDepth', page_result,
    'outboundDeliveries', 0
  );
end;
end;
end;
$function$

CREATE OR REPLACE FUNCTION private.demo_seed_apply_member_support(p_lane text, p_run_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  perform private.lock_case_graph(array[auth.uid()], array[]::uuid[]);

declare
  org uuid := private.member_stress_uuid(
    p_run_id::text || case when p_lane = 'presg' then ':presg:organization' else ':ud:organization' end
  );
  actor uuid;
  member_id uuid;
  mentor_id uuid;
  pair_id uuid;
  entity_id uuid;
  step_ids uuid[] := array[]::uuid[];
  state text;
  result jsonb;
  lane_member_count integer;
  n integer;
begin
  perform set_config('app.sensitive_seed_ticket', coalesce((select id::text from private.sensitive_write_tickets where operation='demo_seed' and arguments=jsonb_build_object('lane',p_lane,'runId',p_run_id) and expires_at>clock_timestamp() order by expires_at desc limit 1),''),true);
  if p_lane not in ('presg', 'uniondemo') then raise exception 'unknown demo lane'; end if;
  if p_lane = 'presg' and not exists (
    select 1 from private.presg_demo_runs r where r.id = p_run_id and r.state in ('applied', 'verified')
  ) then raise exception 'presg demo run is not applied'; end if;
  if p_lane = 'uniondemo' and not exists (
    select 1 from private.uniondemo_runs r where r.id = p_run_id and r.state in ('applied', 'verified')
  ) then raise exception 'union demo run is not applied'; end if;
  if not exists (select 1 from public.organizations o where o.id = org and o.status = 'active') then
    raise exception 'demo organization is missing';
  end if;
  if p_lane = 'presg' then
    select r.member_count into lane_member_count from private.presg_demo_runs r where r.id = p_run_id;
  else
    select r.member_count into lane_member_count from private.uniondemo_runs r where r.id = p_run_id;
  end if;
  if lane_member_count < 38 then
    raise exception 'member support demo seed requires at least 38 seeded users' using errcode = '22023';
  end if;

  perform private.demo_seed_remove_member_support(p_lane, p_run_id);
  actor := private.demo_seed_user(p_lane, p_run_id, 1);

  insert into public.organization_hr_directory (
    organization_id, name, title, department, email, phone, hours, notes,
    enabled, updated_by, updated_at
  ) values (
    org, 'People Operations', 'Employee relations contact', 'Human Resources',
    'people-operations@example.invalid', '(555) 014-0188', 'Weekdays, 9 AM–5 PM',
    'Use the secure employer portal when a document contains medical or personnel information.',
    true, actor, pg_catalog.now() - interval '12 days'
  );

  for n in 1..4 loop
    entity_id := private.member_stress_uuid(p_run_id::text || ':member-support:onboarding-step:' || n);
    step_ids := pg_catalog.array_append(step_ids, entity_id);
    insert into public.organization_onboarding_steps (
      id, organization_id, title, description, position, active, created_by, created_at, updated_at
    ) values (
      entity_id, org,
      (array['Meet your chapter','Learn core workplace rights','Set communication preferences','Choose a first way to participate'])[n],
      (array[
        'Review the people and channels available when you need help.',
        'Complete the rights introduction and save the scripts you may need.',
        'Choose the contact channels and notification categories that work for you.',
        'Pick one meeting, pulse, or chapter activity that fits your schedule.'
      ])[n],
      n, true, actor, pg_catalog.now() - interval '3 years', pg_catalog.now() - interval '20 days'
    );
  end loop;

  -- The featured member receives all three emergency scenarios. Thirty-six
  -- lifecycle records per recurring program span a rolling three-year history.
  member_id := private.demo_seed_user(p_lane, p_run_id, 2);
  for n in 1..3 loop
    entity_id := private.member_stress_uuid(p_run_id::text || ':member-support:emergency:' || n);
    state := (array['draft','alerted','resolved'])[n];
    insert into public.member_emergency_checklists (
      id, organization_id, member_user_id, scenario, status, completed_steps,
      notes, alerted_at, resolved_at, created_at, updated_at
    ) values (
      entity_id, org, member_id,
      (array['disciplinary_meeting','pre_discipline_response','unsafe_work'])[n], state,
      case when n = 1 then array[0]::smallint[] when n = 2 then array[0,1]::smallint[] else array[0,1,2,3]::smallint[] end,
      case when n = 1 then 'Meeting details are ready to add.' when n = 2 then 'Response deadline and requested records were documented.' else 'Safety follow-up was completed.' end,
      case when n >= 2 then pg_catalog.now() - ((n * 170) || ' days')::interval else null end,
      case when n = 3 then pg_catalog.now() - interval '14 months' else null end,
      pg_catalog.now() - ((n * 180) || ' days')::interval,
      pg_catalog.now() - ((n * 170) || ' days')::interval
    );
  end loop;

  for n in 1..36 loop
    member_id := private.demo_seed_user(p_lane, p_run_id, 2 + n);
    entity_id := private.member_stress_uuid(p_run_id::text || ':member-support:accommodation:' || n);
    state := (array['submitted','under_review','approved','denied','withdrawn'])[1 + (n % 5)];
    insert into public.member_accommodation_requests (
      id, organization_id, member_user_id, request_type, description, status,
      staff_note, submitted_at, resolved_at, updated_at
    ) values (
      entity_id, org, member_id,
      (array['schedule','equipment','workspace','leave','communication','remote_work','other'])[1 + (n % 7)],
      '[encrypted]',
      state,
      case when state in ('approved','denied') then '[encrypted]' else '' end,
      pg_catalog.now() - ((n * 30) || ' days')::interval,
      case when state in ('approved','denied','withdrawn') then pg_catalog.now() - ((n * 30 - 7) || ' days')::interval else null end,
      pg_catalog.now() - ((n * 30 - 7) || ' days')::interval
    );
    insert into public.member_support_events (
      id, organization_id, actor_user_id, member_user_id, entity_type, entity_id, event_type, occurred_at
    ) values (
      private.member_stress_uuid(p_run_id::text || ':member-support:accommodation-event:' || n),
      org, actor, member_id, 'accommodation_request', entity_id,
      case when state = 'withdrawn' then 'withdrawn' when state in ('submitted','under_review') then 'created' else 'transitioned' end,
      pg_catalog.now() - ((n * 30 - 7) || ' days')::interval
    );

    entity_id := private.member_stress_uuid(p_run_id::text || ':member-support:hr-contact:' || n);
    state := (array['planned','attempted','reached','follow_up_due','resolved'])[1 + (n % 5)];
    insert into public.member_hr_contacts (
      id, organization_id, member_user_id, actor_user_id, channel, purpose,
      disposition, note, occurred_at, follow_up_on, created_at
    ) values (
      entity_id, org, member_id, actor,
      (array['email','phone','meeting','letter','portal','other'])[1 + (n % 6)],
      (array['Confirm paperwork receipt','Clarify the response timeline','Document the interactive-process meeting','Record the written disposition'])[1 + (n % 4)],
      state,
      case when state = 'resolved' then 'The response and next step were confirmed in writing.' else 'Contact attempt and current disposition recorded.' end,
      pg_catalog.now() - ((n * 31) || ' days')::interval,
      case when state = 'follow_up_due' then current_date + (n % 14) else null end,
      pg_catalog.now() - ((n * 31) || ' days')::interval
    );
    insert into public.member_support_events (
      id, organization_id, actor_user_id, member_user_id, entity_type, entity_id, event_type, occurred_at
    ) values (
      private.member_stress_uuid(p_run_id::text || ':member-support:hr-event:' || n),
      org, actor, member_id, 'hr_contact', entity_id, 'created',
      pg_catalog.now() - ((n * 31) || ' days')::interval
    );
  end loop;

  for n in 1..30 loop
    member_id := private.demo_seed_user(p_lane, p_run_id, 2 + n);
    state := case when n % 5 = 0 then 'in_progress' else 'completed' end;
    entity_id := private.member_stress_uuid(p_run_id::text || ':member-support:onboarding-plan:' || n);
    insert into public.member_onboarding_plans (
      id, organization_id, member_user_id, status, completed_step_ids,
      assigned_by, started_at, completed_at, created_at, updated_at
    ) values (
      entity_id, org, member_id, state,
      case when state = 'completed' then step_ids else step_ids[1:2] end,
      actor,
      pg_catalog.now() - ((36 - n) || ' months')::interval,
      case when state = 'completed' then pg_catalog.now() - ((36 - n) || ' months')::interval + interval '21 days' else null end,
      pg_catalog.now() - ((36 - n) || ' months')::interval,
      case when state = 'completed' then pg_catalog.now() - ((36 - n) || ' months')::interval + interval '21 days' else pg_catalog.now() - interval '4 days' end
    );
    insert into public.member_support_events (
      id, organization_id, actor_user_id, member_user_id, entity_type, entity_id, event_type, occurred_at
    ) values (
      private.member_stress_uuid(p_run_id::text || ':member-support:onboarding-event:' || n),
      org, actor, member_id, 'onboarding_plan', entity_id,
      case when state = 'completed' then 'step_completed' else 'started' end,
      pg_catalog.now() - ((36 - n) || ' months')::interval + interval '7 days'
    );
  end loop;

  mentor_id := private.demo_seed_user(p_lane, p_run_id, 1);
  for n in 1..24 loop
    member_id := private.demo_seed_user(p_lane, p_run_id, 2 + n);
    pair_id := private.member_stress_uuid(p_run_id::text || ':member-support:mentorship-pair:' || n);
    state := case when n % 4 = 0 then 'active' when n % 5 = 0 then 'cancelled' else 'completed' end;
    insert into public.member_mentorship_pairs (
      id, organization_id, mentor_user_id, mentee_user_id, status, started_on,
      ended_on, outcome, created_by, created_at, updated_at
    ) values (
      pair_id, org, mentor_id, member_id, state,
      current_date - (n * 45),
      case when state = 'active' then null else current_date - (n * 45) + 60 end,
      case when state = 'completed' then 'The agreed practice goal and follow-up reflection were completed.' when state = 'cancelled' then 'The pairing ended after schedules changed.' else '' end,
      actor, pg_catalog.now() - ((n * 45) || ' days')::interval,
      pg_catalog.now() - ((n * 45 - 30) || ' days')::interval
    );
    insert into public.member_mentorship_goals (
      id, organization_id, pair_id, title, completed, completed_at,
      created_by, created_at, updated_at
    ) values
      (private.member_stress_uuid(p_run_id::text || ':member-support:mentorship-goal:' || n || ':1'), org, pair_id,
       'Shadow a member intake and complete a debrief', true,
       pg_catalog.now() - ((n * 45 - 20) || ' days')::interval, actor,
       pg_catalog.now() - ((n * 45 - 35) || ' days')::interval,
       pg_catalog.now() - ((n * 45 - 20) || ' days')::interval),
      (private.member_stress_uuid(p_run_id::text || ':member-support:mentorship-goal:' || n || ':2'), org, pair_id,
       'Lead a follow-up conversation with feedback', state = 'completed',
       case when state = 'completed' then pg_catalog.now() - ((n * 45 - 5) || ' days')::interval else null end,
       actor, pg_catalog.now() - ((n * 45 - 18) || ' days')::interval,
       pg_catalog.now() - ((n * 45 - 5) || ' days')::interval);
    insert into public.member_mentorship_notes (
      id, organization_id, pair_id, author_user_id, body, created_at
    ) values
      (private.member_stress_uuid(p_run_id::text || ':member-support:mentorship-note:' || n || ':1'), org, pair_id, mentor_id,
       'Reviewed the next practice opportunity and agreed on a debrief question.',
       pg_catalog.now() - ((n * 45 - 28) || ' days')::interval),
      (private.member_stress_uuid(p_run_id::text || ':member-support:mentorship-note:' || n || ':2'), org, pair_id, member_id,
       'Captured what worked, what was difficult, and the next action to practice.',
       pg_catalog.now() - ((n * 45 - 12) || ' days')::interval);
    insert into public.member_support_events (
      id, organization_id, actor_user_id, member_user_id, entity_type, entity_id, event_type, occurred_at
    ) values (
      private.member_stress_uuid(p_run_id::text || ':member-support:mentorship-event:' || n),
      org, actor, member_id, 'mentorship_pair', pair_id,
      case when state = 'active' then 'created' else 'transitioned' end,
      pg_catalog.now() - ((n * 45 - 30) || ' days')::interval
    );
  end loop;

  -- Add emergency history events separately because the checklist relation is
  -- intentionally one current row per member and scenario.
  member_id := private.demo_seed_user(p_lane, p_run_id, 2);
  for n in 1..3 loop
    insert into public.member_support_events (
      id, organization_id, actor_user_id, member_user_id, entity_type, entity_id, event_type, occurred_at
    ) values (
      private.member_stress_uuid(p_run_id::text || ':member-support:emergency-event:' || n),
      org, member_id, member_id, 'emergency_checklist',
      private.member_stress_uuid(p_run_id::text || ':member-support:emergency:' || n),
      (array['saved','alerted','transitioned'])[n],
      pg_catalog.now() - ((n * 14) || ' months')::interval
    );
  end loop;

  result := private.demo_seed_member_support_status(p_lane, p_run_id);
  if not (result ->> 'ok')::boolean then
    raise exception 'member support seed contract failed: %', result;
  end if;
  perform set_config('app.sensitive_seed_ticket','',true);
  return result;
end;
end;
$function$

CREATE OR REPLACE FUNCTION private.demo_seed_apply_organization_coordination(p_lane text, p_run_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET statement_timeout TO '300s'
AS $function$
begin
  perform private.lock_case_graph(array[auth.uid()], array[]::uuid[]);

begin
  perform private.lock_message_lifecycle();

<<seed_coordination>>
declare
  organization uuid;
  partner uuid := private.member_stress_uuid('coordination:partner:' || p_lane);
  actor uuid;
  chapter text;
  current_record_id uuid;
  current_parent_id uuid;
  current_campaign_id uuid;
  current_work_id uuid;
  current_decision_id uuid;
  prefix text := 'coord-' || pg_catalog.substr(
    pg_catalog.md5(p_run_id::text || ':' || p_lane), 1, 8
  );
  created_public_record boolean;
begin
  if (select auth.role()) <> 'service_role' then
    raise exception 'service_role required' using errcode = '42501';
  end if;
  if p_lane = 'presg' then
    organization := private.member_stress_uuid(p_run_id::text || ':presg:organization');
  elsif p_lane = 'uniondemo' then
    organization := private.member_stress_uuid(p_run_id::text || ':ud:organization');
  else
    raise exception 'unknown demo lane';
  end if;
  actor := private.demo_seed_user(p_lane, p_run_id, 1);
  chapter := private.demo_seed_chapter(p_lane, p_run_id, 1);
  if not exists (
    select 1 from public.organization_memberships membership
    where membership.organization_id = organization
      and membership.user_id = actor and membership.status = 'active'
  ) then
    raise exception 'demo coordination actor is not an active organization member';
  end if;

  insert into public.organizations (id, slug, name, status)
  values (
    partner,
    case when p_lane = 'presg' then 'harbor-service-network'
      else 'pioneer-valley-workers-council' end,
    case when p_lane = 'presg' then 'Harbor Service Workers Network'
      else 'Pioneer Valley Public Workers Council' end,
    'active'
  ) on conflict (id) do update set status = 'active', updated_at = pg_catalog.now();

  insert into public.organization_network_directory_profiles (
    organization_id, display_name, summary, visibility, contact_mode, updated_by
  ) values (
    partner,
    case when p_lane = 'presg' then 'Harbor Service Workers Network'
      else 'Pioneer Valley Public Workers Council' end,
    'A neighboring worker organization coordinating training, resources, and public actions.',
    'directory', 'coordinator_routed', null
  ) on conflict (organization_id) do update set
    visibility = 'directory', contact_mode = 'coordinator_routed',
    updated_at = pg_catalog.now();

  created_public_record := not exists (
    select 1 from public.public_site_records record where record.id = chapter
  );
  insert into public.public_site_records (
    id, kind, title_en, title_es, body_en, body_es,
    region_en, region_es, sort_order, is_published, published_at,
    created_by, organization_id, chapter_code
  )
  select chapter, 'chapter', chapter_row.name, chapter_row.name,
    'Member resources, meeting information, and chapter updates.',
    'Recursos para miembros, información de reuniones y novedades del capítulo.',
    coalesce(chapter_row.region, 'Massachusetts'),
    coalesce(chapter_row.region, 'Massachusetts'),
    chapter_row.order_index, true, pg_catalog.now(), actor, organization, chapter
  from public.chapters chapter_row where chapter_row.id = chapter
  on conflict (id) do update set
    organization_id = excluded.organization_id,
    chapter_code = excluded.chapter_code,
    is_published = true,
    published_at = coalesce(public.public_site_records.published_at, excluded.published_at),
    updated_at = pg_catalog.now();

  insert into private.demo_seed_coordination_runs (
    lane, run_id, organization_id, partner_organization_id, chapter_id,
    actor_user_id, section_prefix, public_record_created
  ) values (
    p_lane, p_run_id, organization, partner, chapter,
    actor, prefix, created_public_record
  ) on conflict (lane, run_id) do update set
    organization_id = excluded.organization_id,
    partner_organization_id = excluded.partner_organization_id,
    chapter_id = excluded.chapter_id,
    actor_user_id = excluded.actor_user_id,
    section_prefix = excluded.section_prefix;

  -- Missions and objectives: enough distinct, completed and active work to
  -- exercise cards, member joins, badges, and anonymized leaderboard order.
  for i in 1..12 loop
    current_record_id := private.member_stress_uuid(p_run_id::text || ':coord:mission:' || i);
    insert into public.organization_coordination_records (
      id, organization_id, kind, title, summary, status, visibility,
      config, created_by, idempotency_key, created_at, updated_at
    ) values (
      current_record_id, organization, 'mission',
      (array['Weekend outreach sprint','Safety story collection','Meeting turnout drive'])[1 + (i % 3)] || ' ' || i,
      'A realistic shared mission with bounded objectives and participant progress.',
      case when i % 4 = 0 then 'completed' else 'active' end, 'members',
      pg_catalog.jsonb_build_object('demoRunId', p_run_id, 'sequence', i),
      actor, private.member_stress_uuid(p_run_id::text || ':coord:mission-key:' || i),
      pg_catalog.now() - (i || ' days')::interval,
      pg_catalog.now() - (i || ' hours')::interval
    ) on conflict (id) do nothing;
    insert into public.organization_coordination_user_participants (
      record_id, organization_id, user_id, role, status, points, privacy_alias, config
    ) select current_record_id, organization, seeded.user_id,
      case when ordinal = 1 then 'captain' else 'participant' end,
      case when i % 4 = 0 then 'completed' else 'active' end,
      20 + ordinal * 15 + i,
      'Member ' || pg_catalog.upper(pg_catalog.substr(pg_catalog.md5(seeded.user_id::text), 1, 6)),
      pg_catalog.jsonb_build_object('demoRunId', p_run_id)
    from (
      select ordinal, private.demo_seed_user(p_lane, p_run_id, i * 6 + ordinal) user_id
      from pg_catalog.generate_series(1, 6) ordinal
    ) seeded
    on conflict (record_id, organization_id, user_id) do nothing;
    insert into public.organization_mission_badges (
      mission_id, organization_id, user_id, privacy_alias, badge_key
    ) select participant.record_id, participant.organization_id,
      participant.user_id, participant.privacy_alias,
      case when participant.points >= 100 then 'silver' else 'bronze' end
    from public.organization_coordination_user_participants participant
    where participant.record_id = current_record_id
    on conflict do nothing;

    current_parent_id := current_record_id;
    insert into public.organization_coordination_records (
      id, organization_id, parent_id, kind, title, summary, status,
      visibility, config, created_by, idempotency_key, created_at, updated_at
    ) values (
      private.member_stress_uuid(p_run_id::text || ':coord:objective:' || i),
      organization, current_parent_id, 'mission_objective',
      'Complete assigned conversations ' || i,
      'Reach the next bounded milestone and record only the outcome.',
      case when i % 3 = 0 then 'completed' else 'active' end, 'members',
      pg_catalog.jsonb_build_object('demoRunId', p_run_id, 'points', 15),
      actor, private.member_stress_uuid(p_run_id::text || ':coord:objective-key:' || i),
      pg_catalog.now() - (i || ' days')::interval,
      pg_catalog.now() - ((i + 1) || ' hours')::interval
    ) on conflict (id) do nothing;
  end loop;

  -- Each active network has explicit reciprocal participants and capability
  -- grants before its conversation/request children are inserted.
  for i in 1..10 loop
    current_parent_id := private.member_stress_uuid(p_run_id::text || ':coord:network:' || i);
    insert into public.organization_coordination_records (
      id, organization_id, partner_organization_id, kind, title, summary,
      status, visibility, config, created_by, idempotency_key, created_at, updated_at
    ) values (
      current_parent_id, organization, partner, 'network_link',
      'Regional coordination channel ' || i,
      'An explicit partner connection for messages and bounded resource exchange.',
      'active', 'participants',
      pg_catalog.jsonb_build_object('demoRunId', p_run_id, 'sequence', i),
      actor, private.member_stress_uuid(p_run_id::text || ':coord:network-key:' || i),
      pg_catalog.now() - (i || ' days')::interval,
      pg_catalog.now() - ((20 + i) || ' minutes')::interval
    ) on conflict (id) do nothing;
    insert into public.organization_coordination_organization_participants (
      record_id, organization_id, role, status, invited_by, responded_by
    ) values
      (current_parent_id, organization, 'owner', 'active', actor, actor),
      (current_parent_id, partner, 'partner', 'active', actor, actor)
    on conflict (record_id, organization_id) do update set status = 'active';
    insert into public.organization_network_permission_grants (
      network_record_id, grantor_organization_id, grantee_organization_id,
      capability, status, granted_by
    ) select current_parent_id, organization, partner, capability, 'active', actor
    from unnest(array['directory_contact','message','resource_request','resource_share']) capability
    on conflict (network_record_id, grantor_organization_id, grantee_organization_id, capability)
    do update set status = 'active', revoked_at = null;

    current_record_id := private.member_stress_uuid(p_run_id::text || ':coord:conversation:' || i);
    insert into public.organization_coordination_records (
      id, organization_id, partner_organization_id, parent_id, kind,
      title, summary, status, visibility, config, created_by,
      idempotency_key, created_at, updated_at
    ) values (
      current_record_id, organization, partner, current_parent_id, 'network_conversation',
      'Partner planning thread ' || i,
      'Authorized staff coordinate the next shared step.', 'active', 'participants',
      pg_catalog.jsonb_build_object('demoRunId', p_run_id), actor,
      private.member_stress_uuid(p_run_id::text || ':coord:conversation-key:' || i),
      pg_catalog.now() - (i || ' days')::interval,
      pg_catalog.now() - ((30 + i) || ' minutes')::interval
    ) on conflict (id) do nothing;
    insert into public.organization_coordination_messages (
      id, conversation_id, sender_organization_id, sender_user_id,
      body, idempotency_key, created_at
    ) select private.member_stress_uuid(p_run_id::text || ':coord:message:' || i || ':' || message_number),
      current_record_id, case when message_number % 2 = 0 then partner else organization end,
      case when message_number % 2 = 0 then null else actor end,
      (array['Training materials are ready for review.','The shared meeting window is confirmed.','Please route questions through the named coordinators.'])[1 + (message_number % 3)],
      private.member_stress_uuid(p_run_id::text || ':coord:message-key:' || i || ':' || message_number),
      pg_catalog.now() - ((i * 20 + message_number) || ' minutes')::interval
    from pg_catalog.generate_series(1, 6) message_number
    on conflict (id) do nothing;

    current_record_id := private.member_stress_uuid(p_run_id::text || ':coord:request:' || i);
    insert into public.organization_coordination_records (
      id, organization_id, partner_organization_id, parent_id, kind,
      title, summary, status, visibility, config, created_by,
      idempotency_key, created_at, updated_at
    ) values (
      current_record_id, organization, partner, current_parent_id, 'network_request',
      'Request training resource ' || i,
      'A bounded request that links authorized material without copying member data.',
      'requested', 'participants',
      pg_catalog.jsonb_build_object('demoRunId', p_run_id), actor,
      private.member_stress_uuid(p_run_id::text || ':coord:request-key:' || i),
      pg_catalog.now() - (i || ' days')::interval,
      pg_catalog.now() - ((40 + i) || ' minutes')::interval
    ) on conflict (id) do nothing;
    insert into public.organization_coordination_resources (
      id, record_id, from_organization_id, to_organization_id,
      resource_kind, title, status, idempotency_key, created_by, created_at, updated_at
    ) values (
      private.member_stress_uuid(p_run_id::text || ':coord:resource:' || i),
      current_record_id, organization, partner, 'request',
      'Facilitation guide request ' || i,
      case when i % 3 = 0 then 'accepted' else 'requested' end,
      private.member_stress_uuid(p_run_id::text || ':coord:resource-key:' || i),
      actor, pg_catalog.now() - (i || ' days')::interval,
      pg_catalog.now() - ((50 + i) || ' minutes')::interval
    ) on conflict (id) do nothing;
  end loop;

  for i in 1..8 loop
    current_record_id := private.member_stress_uuid(p_run_id::text || ':coord:export:' || i);
    insert into public.organization_coordination_records (
      id, organization_id, kind, title, summary, status, visibility,
      config, created_by, idempotency_key, created_at, updated_at
    ) values (
      current_record_id, organization, 'network_export_schedule',
      'Authorized network export ' || i,
      'Internal download schedule; external delivery remains explicitly unset.',
      'active', 'staff',
      pg_catalog.jsonb_build_object(
        'demoRunId', p_run_id, 'cadence', case when i % 2 = 0 then 'monthly' else 'weekly' end,
        'format', case when i % 2 = 0 then 'json' else 'csv' end,
        'deliveryMode', 'internal_download',
        'nextRunAt', (pg_catalog.now() + (i || ' days')::interval)::text
      ), actor, private.member_stress_uuid(p_run_id::text || ':coord:export-key:' || i),
      pg_catalog.now() - (i || ' days')::interval,
      pg_catalog.now() - ((60 + i) || ' minutes')::interval
    ) on conflict (id) do nothing;
    insert into public.organization_coordination_export_runs (
      id, schedule_id, organization_id, requested_by, format,
      delivery_mode, status, row_count, expires_at, idempotency_key, created_at
    ) values (
      private.member_stress_uuid(p_run_id::text || ':coord:export-run:' || i),
      current_record_id, organization, actor,
      case when i % 2 = 0 then 'json' else 'csv' end,
      'internal_download', 'ready', 120 + i,
      pg_catalog.now() + interval '24 hours',
      private.member_stress_uuid(p_run_id::text || ':coord:export-run-key:' || i),
      pg_catalog.now() - (i || ' hours')::interval
    ) on conflict (id) do nothing;

    insert into public.organization_coordination_records (
      id, organization_id, chapter_id, kind, title, summary, status,
      visibility, config, created_by, idempotency_key, created_at, updated_at
    ) values (
      private.member_stress_uuid(p_run_id::text || ':coord:handshake:' || i),
      organization, chapter, 'handshake_workspace_item',
      'Chapter handshake step ' || i,
      'Reciprocal chapter coordination with an explicit lifecycle checkpoint.',
      (array['requested','active','completed'])[1 + (i % 3)], 'staff',
      pg_catalog.jsonb_build_object('demoRunId', p_run_id, 'stage', (array['request','reciprocal-review','shared-work'])[1 + (i % 3)]),
      actor, private.member_stress_uuid(p_run_id::text || ':coord:handshake-key:' || i),
      pg_catalog.now() - (i || ' days')::interval,
      pg_catalog.now() - ((70 + i) || ' minutes')::interval
    ) on conflict (id) do nothing;
  end loop;

  for i in 1..8 loop
    current_parent_id := private.member_stress_uuid(p_run_id::text || ':coord:coalition:' || i);
    insert into public.organization_coordination_records (
      id, organization_id, partner_organization_id, kind, title, summary,
      status, visibility, config, created_by, idempotency_key, created_at, updated_at
    ) values (
      current_parent_id, organization, partner, 'coalition',
      'Public service coalition ' || i,
      'A governed coalition with two active organizations and recorded approvals.',
      'active', 'participants', pg_catalog.jsonb_build_object('demoRunId', p_run_id),
      actor, private.member_stress_uuid(p_run_id::text || ':coord:coalition-key:' || i),
      pg_catalog.now() - (i || ' days')::interval,
      pg_catalog.now() - ((80 + i) || ' minutes')::interval
    ) on conflict (id) do nothing;
    insert into public.organization_coordination_organization_participants (
      record_id, organization_id, role, status, invited_by, responded_by
    ) values
      (current_parent_id, organization, 'owner', 'active', actor, actor),
      (current_parent_id, partner, 'approver', 'active', actor, actor)
    on conflict (record_id, organization_id) do update set status = 'active';
    current_campaign_id := private.member_stress_uuid(p_run_id::text || ':coord:coalition-campaign:' || i);
    insert into public.organization_coordination_records (
      id, organization_id, partner_organization_id, parent_id, kind,
      title, summary, status, visibility, config, created_by,
      idempotency_key, created_at, updated_at
    ) values (
      current_campaign_id, organization, partner, current_parent_id, 'coalition_campaign',
      'Joint action campaign ' || i,
      'Shared execution stays gated by explicit organization approvals.',
      'active', 'participants', pg_catalog.jsonb_build_object('demoRunId', p_run_id),
      actor, private.member_stress_uuid(p_run_id::text || ':coord:coalition-campaign-key:' || i),
      pg_catalog.now() - (i || ' days')::interval,
      pg_catalog.now() - ((90 + i) || ' minutes')::interval
    ) on conflict (id) do nothing;
    current_work_id := private.member_stress_uuid(p_run_id::text || ':coord:coalition-work:' || i);
    insert into public.organization_coordination_records (
      id, organization_id, partner_organization_id, parent_id, kind,
      title, summary, status, visibility, config, created_by,
      idempotency_key, created_at, updated_at
    ) values (
      current_work_id, organization, partner, current_campaign_id, 'coalition_work_item',
      'Joint field assignment ' || i,
      'A campaign work item controlled by the coalition decision record.',
      case when i % 3 = 0 then 'active' else 'draft' end,
      'participants', pg_catalog.jsonb_build_object('demoRunId', p_run_id),
      actor, private.member_stress_uuid(p_run_id::text || ':coord:coalition-work-key:' || i),
      pg_catalog.now() - (i || ' days')::interval,
      pg_catalog.now() - ((100 + i) || ' minutes')::interval
    ) on conflict (id) do nothing;
    current_decision_id := private.member_stress_uuid(p_run_id::text || ':coord:decision:' || i);
    insert into public.organization_coalition_decisions (
      id, campaign_id, subject_record_id, proposing_organization_id,
      title, rationale, action, status, required_approvals, proposed_by,
      resolved_at, idempotency_key, created_at, updated_at
    ) values (
      current_decision_id, current_campaign_id, current_work_id, organization,
      'Authorize joint assignment ' || i,
      'Both participating organizations review scope and responsibility before work starts.',
      'authorize_work', case when i % 3 = 0 then 'approved' else 'open' end,
      2, actor, case when i % 3 = 0 then pg_catalog.now() - interval '1 hour' else null end,
      private.member_stress_uuid(p_run_id::text || ':coord:decision-key:' || i),
      pg_catalog.now() - (i || ' days')::interval,
      pg_catalog.now() - ((110 + i) || ' minutes')::interval
    ) on conflict (id) do nothing;
    insert into public.organization_coalition_decision_votes (
      decision_id, organization_id, voter_user_id, vote, comment,
      idempotency_key, created_at, updated_at
    ) values (
      current_decision_id, organization, actor, 'approve',
      'Scope and responsibilities reviewed.',
      private.member_stress_uuid(p_run_id::text || ':coord:decision-vote-key:' || i),
      pg_catalog.now() - (i || ' hours')::interval,
      pg_catalog.now() - (i || ' hours')::interval
    ) on conflict (decision_id, organization_id) do nothing;
    if i % 3 = 0 then
      insert into public.organization_coalition_decision_votes (
        decision_id, organization_id, voter_user_id, vote, comment,
        idempotency_key, created_at, updated_at
      ) values (
        current_decision_id, partner, null, 'approve',
        'Partner organization approval recorded by its authorized representative.',
        private.member_stress_uuid(p_run_id::text || ':coord:decision-partner-vote-key:' || i),
        pg_catalog.now() - (i || ' hours')::interval,
        pg_catalog.now() - (i || ' hours')::interval
      ) on conflict (decision_id, organization_id) do nothing;
    end if;
  end loop;

  for i in 1..4 loop
    current_record_id := private.member_stress_uuid(p_run_id::text || ':coord:merger:' || i);
    insert into public.organization_coordination_records (
      id, organization_id, partner_organization_id, kind, title, summary,
      status, visibility, config, created_by, idempotency_key, created_at, updated_at
    ) values (
      current_record_id, organization, partner, 'merger_plan',
      'Organization consolidation plan ' || i,
      'A reversible mapping review with operator execution kept explicit.',
      'pending_operator', 'staff', pg_catalog.jsonb_build_object('demoRunId', p_run_id),
      actor, private.member_stress_uuid(p_run_id::text || ':coord:merger-key:' || i),
      pg_catalog.now() - (i || ' days')::interval,
      pg_catalog.now() - ((120 + i) || ' minutes')::interval
    ) on conflict (id) do nothing;
    insert into public.organization_merge_match_reviews (
      plan_id, source_user_id, target_user_id, decision, created_at
    ) values (
      current_record_id, private.demo_seed_user(p_lane, p_run_id, i + 10),
      private.demo_seed_user(p_lane, p_run_id, i + 20), 'pending',
      pg_catalog.now() - (i || ' days')::interval
    ) on conflict (plan_id, source_user_id, target_user_id) do nothing;
    insert into public.organization_merge_jobs (
      id, plan_id, source_organization_id, target_organization_id,
      status, requested_by, approved_match_count, requested_at
    ) values (
      private.member_stress_uuid(p_run_id::text || ':coord:merger-job:' || i),
      current_record_id, partner, organization, 'queued', actor, 0,
      pg_catalog.now() - (i || ' hours')::interval
    ) on conflict (plan_id) do nothing;
  end loop;

  for i in 1..8 loop
    insert into public.organization_coordination_records (
      id, organization_id, chapter_id, kind, title, summary, status,
      visibility, config, created_by, idempotency_key, created_at, updated_at
    ) values (
      private.member_stress_uuid(p_run_id::text || ':coord:coverage:' || i),
      organization, chapter, 'coverage_schedule',
      'Steward coverage window ' || i,
      'A recurring chapter coverage window with a selected active steward.',
      'active', 'staff', pg_catalog.jsonb_build_object(
        'demoRunId', p_run_id, 'stewardUserId', actor,
        'dayOfWeek', i % 7, 'startMinute', 540, 'endMinute', 1020,
        'timezone', 'America/New_York'
      ), actor, private.member_stress_uuid(p_run_id::text || ':coord:coverage-key:' || i),
      pg_catalog.now() - (i || ' days')::interval,
      pg_catalog.now() - ((130 + i) || ' minutes')::interval
    ) on conflict (id) do nothing;
    insert into public.organization_coordination_records (
      id, organization_id, chapter_id, kind, title, summary, status,
      visibility, config, created_by, idempotency_key, created_at, updated_at
    ) values (
      private.member_stress_uuid(p_run_id::text || ':coord:coverage-override:' || i),
      organization, chapter, 'coverage_override',
      'Coverage exception ' || i,
      'A dated availability exception that never overwrites the recurring schedule.',
      'active', 'staff', pg_catalog.jsonb_build_object(
        'demoRunId', p_run_id, 'stewardUserId', actor,
        'startsAt', (pg_catalog.now() + (i || ' days')::interval)::text,
        'endsAt', (pg_catalog.now() + (i || ' days')::interval + interval '4 hours')::text,
        'available', i % 2 = 0
      ), actor, private.member_stress_uuid(p_run_id::text || ':coord:coverage-override-key:' || i),
      pg_catalog.now() - (i || ' days')::interval,
      pg_catalog.now() - ((140 + i) || ' minutes')::interval
    ) on conflict (id) do nothing;
    current_record_id := private.member_stress_uuid(p_run_id::text || ':coord:committee:' || i);
    insert into public.organization_coordination_records (
      id, organization_id, chapter_id, kind, title, summary, status,
      visibility, config, created_by, idempotency_key, created_at, updated_at
    ) values (
      current_record_id, organization, chapter, 'committee',
      (array['Health and safety committee','Political education committee','New member committee'])[1 + (i % 3)] || ' ' || i,
      'A chapter committee with explicit member selections and role history.',
      'active', 'members', pg_catalog.jsonb_build_object('demoRunId', p_run_id),
      actor, private.member_stress_uuid(p_run_id::text || ':coord:committee-key:' || i),
      pg_catalog.now() - (i || ' days')::interval,
      pg_catalog.now() - ((150 + i) || ' minutes')::interval
    ) on conflict (id) do nothing;
    insert into public.organization_coordination_user_participants (
      record_id, organization_id, user_id, role, status, points,
      privacy_alias, config
    ) values (
      current_record_id, organization, private.demo_seed_user(p_lane, p_run_id, i + 30),
      'committee_member', 'active', 0,
      'Member ' || pg_catalog.upper(pg_catalog.substr(pg_catalog.md5(i::text || p_run_id::text), 1, 6)),
      pg_catalog.jsonb_build_object('demoRunId', p_run_id, 'selectedBy', actor)
    ) on conflict (record_id, organization_id, user_id) do nothing;
  end loop;

  for i in 1..6 loop
    insert into public.organization_coordination_records (
      id, organization_id, chapter_id, kind, title, summary, status,
      visibility, config, created_by, idempotency_key, created_at, updated_at
    ) values (
      private.member_stress_uuid(p_run_id::text || ':coord:microsite:' || i),
      organization, chapter, 'microsite_page',
      'Chapter information page ' || i,
      'A backed chapter page draft mirrored by the public hierarchy editor.',
      'active', 'public', pg_catalog.jsonb_build_object(
        'demoRunId', p_run_id, 'sectionSlug', prefix || '-section',
        'pageSlug', 'chapter-page-' || i
      ), actor, private.member_stress_uuid(p_run_id::text || ':coord:microsite-key:' || i),
      pg_catalog.now() - (i || ' days')::interval,
      pg_catalog.now() - ((160 + i) || ' minutes')::interval
    ) on conflict (id) do nothing;
  end loop;

  for i in 1..10 loop
    current_parent_id := private.member_stress_uuid(p_run_id::text || ':coord:mobilization:' || i);
    insert into public.organization_coordination_records (
      id, organization_id, kind, title, summary, status, visibility,
      config, created_by, idempotency_key, created_at, updated_at
    ) values (
      current_parent_id, organization, 'mobilization_campaign',
      (array['Meeting turnout','Member-to-member outreach','Community action'])[1 + (i % 3)] || ' ' || i,
      'A finite outreach campaign with disposition history and visible progress.',
      case when i % 4 = 0 then 'paused' else 'active' end, 'staff',
      pg_catalog.jsonb_build_object('demoRunId', p_run_id), actor,
      private.member_stress_uuid(p_run_id::text || ':coord:mobilization-key:' || i),
      pg_catalog.now() - (i || ' days')::interval,
      pg_catalog.now() - ((170 + i) || ' minutes')::interval
    ) on conflict (id) do nothing;
    insert into public.organization_coordination_records (
      id, organization_id, parent_id, kind, title, summary, status,
      visibility, config, created_by, idempotency_key, created_at, updated_at
    ) values (
      private.member_stress_uuid(p_run_id::text || ':coord:cohort:' || i),
      organization, current_parent_id, 'mobilization_cohort',
      'Outreach cohort ' || i,
      'A bounded member cohort assigned to the campaign.', 'active', 'staff',
      pg_catalog.jsonb_build_object('demoRunId', p_run_id, 'sequence', i), actor,
      private.member_stress_uuid(p_run_id::text || ':coord:cohort-key:' || i),
      pg_catalog.now() - (i || ' days')::interval,
      pg_catalog.now() - ((180 + i) || ' minutes')::interval
    ) on conflict (id) do nothing;
    insert into public.organization_coordination_outreach_events (
      id, campaign_id, organization_id, target_user_id, actor_user_id,
      disposition, note, idempotency_key, contacted_at
    ) select private.member_stress_uuid(p_run_id::text || ':coord:outreach:' || i || ':' || outreach_number),
      current_parent_id, organization,
      private.demo_seed_user(p_lane, p_run_id, i * 5 + outreach_number), actor,
      (array['attempted','reached','follow_up','committed','attended'])[1 + (outreach_number % 5)],
      case when outreach_number % 3 = 0 then 'Follow-up requested after the conversation.' else '' end,
      private.member_stress_uuid(p_run_id::text || ':coord:outreach-key:' || i || ':' || outreach_number),
      pg_catalog.now() - ((i * 10 + outreach_number) || ' hours')::interval
    from pg_catalog.generate_series(1, 10) outreach_number
    on conflict (id) do nothing;
  end loop;

  -- Two complete 24-page slices on the actual public chapter hierarchy.
  for i in 1..2 loop
    insert into public.public_chapter_sections (
      organization_id, chapter_code, slug, title_en, title_es,
      body_en, body_es, sort_order, is_published, published_at, created_by
    ) values (
      organization, chapter, prefix || '-section-' || i,
      case when i = 1 then 'Member resources' else 'Chapter participation' end,
      case when i = 1 then 'Recursos para miembros' else 'Participación del capítulo' end,
      'Practical information and current chapter resources.',
      'Información práctica y recursos actuales del capítulo.',
      80 + i, true, pg_catalog.now(), actor
    ) on conflict (organization_id, chapter_code, slug) do update set
      is_published = true,
      published_at = coalesce(public.public_chapter_sections.published_at, excluded.published_at),
      updated_at = pg_catalog.now();
    insert into public.public_chapter_pages (
      organization_id, chapter_code, section_slug, slug,
      title_en, title_es, body_en, body_es, sort_order,
      is_published, published_at, created_by
    ) select organization, chapter, prefix || '-section-' || i,
      'resource-' || pg_catalog.lpad(page_number::text, 2, '0'),
      'Chapter resource ' || page_number,
      'Recurso del capítulo ' || page_number,
      'A concise fictional resource page with current contacts, steps, and meeting information.',
      'Una página ficticia y concisa con contactos, pasos e información de reuniones.',
      page_number, true, pg_catalog.now(), actor
    from pg_catalog.generate_series(1, 24) page_number
    on conflict (organization_id, chapter_code, section_slug, slug) do update set
      is_published = true,
      updated_at = pg_catalog.now();
  end loop;

  return pg_catalog.jsonb_build_object(
    'ok', true,
    'records', (select pg_catalog.count(*)
      from public.organization_coordination_records record
      where record.organization_id = organization
        and record.config ->> 'demoRunId' = p_run_id::text),
    'publicPages', (select pg_catalog.count(*)
      from public.public_chapter_pages page
      where page.organization_id = organization and page.chapter_code = chapter
        and page.section_slug like prefix || '%'),
    'outboundDeliveries', 0
  );
end;
end;
end;
$function$

CREATE OR REPLACE FUNCTION private.demo_seed_apply_organization_intelligence(p_lane text, p_run_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  perform private.lock_case_graph(array[auth.uid()], array[]::uuid[]);

declare
  org uuid := private.member_stress_uuid(
    p_run_id::text || case when p_lane = 'presg' then ':presg:organization' else ':ud:organization' end
  );
  actor uuid := private.demo_seed_user(p_lane, p_run_id, 1);
  visible_users uuid[];
  n integer;
begin
  perform private.demo_seed_apply_organization_intelligence_unwindowed_20260829(p_lane, p_run_id);

  select pg_catalog.array_agg(scoped.user_id order by scoped.full_name, scoped.user_id)
  into visible_users
  from (
    select membership.user_id, profile.full_name
    from public.organization_memberships membership
    join public.member_profiles profile on profile.id = membership.user_id
    where membership.organization_id = org
      and membership.status = 'active'
    order by profile.full_name, membership.user_id
    limit 101
  ) scoped;

  delete from public.organization_topic_progress where organization_id = org;
  delete from public.organization_relationships where organization_id = org;

  for n in 1..least(100, greatest(0, coalesce(pg_catalog.array_length(visible_users, 1), 0) - 1)) loop
    insert into public.organization_relationships (
      id, organization_id, source_user_id, target_user_id, relationship_kind,
      strength, created_by, updated_by
    ) values (
      private.member_stress_uuid(p_run_id::text || ':org-intelligence:relationship:' || n),
      org, visible_users[n], visible_users[n + 1],
      (array['reports_to','works_with','mentors','organizes_with','trusted_contact'])[1 + (n % 5)],
      1 + (n % 5), actor, actor
    );
  end loop;

  for n in 1..least(100, coalesce(pg_catalog.array_length(visible_users, 1), 0)) loop
    insert into public.organization_topic_progress (
      organization_id, member_user_id, topic_key, topic_label,
      progress_state, progress, updated_by
    ) values (
      org, visible_users[n], 'organization_readiness', 'Organization readiness',
      (array['introduced','developing','ready'])[1 + (n % 3)],
      20 + (n % 81), actor
    );
  end loop;
end;
end;
$function$

CREATE OR REPLACE FUNCTION private.demo_seed_apply_organization_intelligence_unwindowed_20260829(p_lane text, p_run_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  perform private.lock_case_graph(array[auth.uid()], array[]::uuid[]);

declare
  org uuid := private.member_stress_uuid(
    p_run_id::text || case when p_lane = 'presg' then ':presg:organization' else ':ud:organization' end
  );
  chapter text;
  actor uuid;
  action_id uuid;
  row_user uuid;
  member_count integer;
  n integer;
  participant integer;
begin
  if p_lane not in ('presg', 'uniondemo') then raise exception 'unknown demo lane'; end if;
  if p_lane = 'presg' and not exists (
    select 1 from private.presg_demo_runs r where r.id = p_run_id and r.state in ('applied', 'verified')
  ) then raise exception 'presg demo run is not applied'; end if;
  if p_lane = 'uniondemo' and not exists (
    select 1 from private.uniondemo_runs r where r.id = p_run_id and r.state in ('applied', 'verified')
  ) then raise exception 'union demo run is not applied'; end if;
  if not exists (select 1 from public.organizations o where o.id = org and o.status = 'active') then
    raise exception 'demo organization is missing';
  end if;

  perform private.demo_seed_remove_organization_intelligence(p_lane, p_run_id);
  if p_lane = 'presg' then
    select r.member_count into member_count from private.presg_demo_runs r where r.id = p_run_id;
  else
    select r.member_count into member_count from private.uniondemo_runs r where r.id = p_run_id;
  end if;
  chapter := private.demo_seed_chapter(p_lane, p_run_id, 1);
  actor := private.demo_seed_user(p_lane, p_run_id, 1);

  for n in 1..25 loop
    insert into public.organization_chart_nodes (
      id, organization_id, chapter_id, chart_kind, node_kind, parent_id,
      label, subtitle, position_x, position_y, sort_order, created_by, updated_by
    ) values (
      private.member_stress_uuid(p_run_id::text || ':org-intelligence:chart:agency:' || n),
      org, null, 'agency', case when n = 1 then 'organization' else 'division' end,
      case when n = 1 then null else private.member_stress_uuid(p_run_id::text || ':org-intelligence:chart:agency:1') end,
      case when n = 1 then 'Human Services Agency' else 'Regional operations division ' || pg_catalog.lpad((n - 1)::text, 2, '0') end,
      case when n = 1 then 'Agency reporting structure' else 'Service delivery and workplace operations' end,
      case when n = 1 then 50 else 10 + (((n - 2) % 5) * 20) end,
      case when n = 1 then 5 else 22 + (((n - 2) / 5) * 16) end,
      n, actor, actor
    );

    insert into public.organization_chart_nodes (
      id, organization_id, chapter_id, chart_kind, node_kind, parent_id,
      label, subtitle, position_x, position_y, sort_order, created_by, updated_by
    ) values (
      private.member_stress_uuid(p_run_id::text || ':org-intelligence:chart:union:' || n),
      org, case when n = 1 then null else private.demo_seed_chapter(p_lane, p_run_id, n - 1) end,
      'union', case when n = 1 then 'organization' else 'chapter' end,
      case when n = 1 then null else private.member_stress_uuid(p_run_id::text || ':org-intelligence:chart:union:1') end,
      case when n = 1 then 'Statewide Council' else 'Chapter leadership circle ' || pg_catalog.lpad((n - 1)::text, 2, '0') end,
      case when n = 1 then 'Organization-wide member governance' else 'Chapter officers, stewards, and workplace leaders' end,
      case when n = 1 then 50 else 10 + (((n - 2) % 5) * 20) end,
      case when n = 1 then 5 else 22 + (((n - 2) / 5) * 16) end,
      n, actor, actor
    );
  end loop;

  for n in 1..least(100, member_count - 1) loop
    insert into public.organization_relationships (
      id, organization_id, source_user_id, target_user_id, relationship_kind,
      strength, created_by, updated_by
    ) values (
      private.member_stress_uuid(p_run_id::text || ':org-intelligence:relationship:' || n),
      org, private.demo_seed_user(p_lane, p_run_id, n),
      private.demo_seed_user(p_lane, p_run_id, n + 1),
      (array['reports_to','works_with','mentors','organizes_with','trusted_contact'])[1 + (n % 5)],
      1 + (n % 5), actor, actor
    );

    insert into public.organization_topic_progress (
      organization_id, member_user_id, topic_key, topic_label,
      progress_state, progress, updated_by
    ) values (
      org, private.demo_seed_user(p_lane, p_run_id, n),
      'organization_readiness', 'Organization readiness',
      (array['introduced','developing','ready'])[1 + (n % 3)],
      20 + (n % 81), actor
    );
  end loop;

  if member_count <= 100 then
    for n in greatest(1, member_count)..least(100, member_count) loop
      insert into public.organization_topic_progress (
        organization_id, member_user_id, topic_key, topic_label,
        progress_state, progress, updated_by
      ) values (
        org, private.demo_seed_user(p_lane, p_run_id, n),
        'organization_readiness', 'Organization readiness',
        (array['introduced','developing','ready'])[1 + (n % 3)],
        20 + (n % 81), actor
      ) on conflict (organization_id, member_user_id, topic_key) do nothing;
    end loop;
  end if;

  for n in 1..50 loop
    insert into public.organization_timeline_events (
      id, organization_id, chapter_id, event_kind, title, detail,
      effective_on, ended_on, amount_cents, amount_basis, source_label,
      source_as_of, created_by, updated_by
    ) values (
      private.member_stress_uuid(p_run_id::text || ':org-intelligence:timeline:' || n),
      org, case when n % 3 = 0 then chapter else null end,
      case when n % 4 = 0 then 'payroll_snapshot' else 'leadership_term' end,
      case when n % 4 = 0 then 'Annual workforce payroll summary ' || (2026 - (n / 4))
        else 'Leadership milestone ' || pg_catalog.lpad(n::text, 2, '0') end,
      case when n % 4 = 0 then 'Aggregate organization-provided workforce total.'
        else 'Recorded transition in the organization leadership history.' end,
      current_date - (n * 30), null,
      case when n % 4 = 0 then 1200000000 + (n * 2500000) else null end,
      case when n % 4 = 0 then 'Annual aggregate' else null end,
      case when n % 4 = 0 then 'Organization-provided payroll summary' else null end,
      case when n % 4 = 0 then current_date - (n * 30) else null end,
      actor, actor
    );
  end loop;

  for n in 1..60 loop
    action_id := private.member_stress_uuid(p_run_id::text || ':org-intelligence:action:' || n);
    insert into public.digital_actions (
      id, organization_id, chapter_id, action_kind, title, summary, status,
      target_count, starts_at, ends_at, published_at, created_by, updated_by,
      created_at, updated_at
    ) values (
      action_id, org, private.demo_seed_chapter(p_lane, p_run_id, n),
      (array['petition','rally','picket','meeting','other'])[1 + (n % 5)],
      (array['Safe staffing commitment','Budget hearing turnout','Fair schedule pledge','Workplace safety delegation','Member outreach drive'])[1 + (n % 5)] || ' ' || pg_catalog.lpad(n::text, 2, '0'),
      'A realistic collective action with a clear commitment, timeline, and measurable participation goal.',
      case when n <= 45 then 'published' when n <= 50 then 'closed' else 'draft' end,
      case when n = 1 then 600 else 100 + ((n % 5) * 25) end,
      pg_catalog.now() - ((90 - n) || ' days')::interval,
      case when n between 46 and 50 then pg_catalog.now() - ((51 - n) || ' days')::interval else null end,
      case when n <= 50 then pg_catalog.now() - ((90 - n) || ' days')::interval else null end,
      actor, actor, pg_catalog.now() - ((90 - n) || ' days')::interval,
      pg_catalog.now() - ((60 - n) || ' hours')::interval
    );

    if n = 1 then
      for participant in 1..least(300, member_count) loop
        insert into public.digital_action_participants (
          organization_id, action_id, user_id, participation_kind, joined_at, updated_at
        ) values (
          org, action_id, private.demo_seed_user(p_lane, p_run_id, participant),
          case when participant <= 100 then 'signature' when participant <= 200 then 'attendee' else 'volunteer' end,
          pg_catalog.now() - ((301 - participant) || ' minutes')::interval,
          pg_catalog.now() - ((301 - participant) || ' minutes')::interval
        );
      end loop;
    elsif n <= 50 then
      for participant in 1..(20 + (n % 20)) loop
        row_user := private.demo_seed_user(p_lane, p_run_id, participant + n);
        insert into public.digital_action_participants (
          organization_id, action_id, user_id, participation_kind, joined_at, updated_at
        ) values (
          org, action_id, row_user,
          (array['signature','attendee','volunteer'])[1 + (participant % 3)],
          pg_catalog.now() - ((participant + n) || ' hours')::interval,
          pg_catalog.now() - ((participant + n) || ' hours')::interval
        ) on conflict on constraint digital_action_participants_pkey do update set
          participation_kind = excluded.participation_kind,
          joined_at = excluded.joined_at,
          updated_at = excluded.updated_at;
      end loop;
    end if;
  end loop;
end;
end;
$function$

CREATE OR REPLACE FUNCTION private.demo_seed_apply_voice_operations(p_lane text, p_run_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET statement_timeout TO '300s'
AS $function$
begin
  perform private.lock_case_graph(array[auth.uid()], array[]::uuid[]);

declare
  v_organization_id uuid := private.member_stress_uuid(
    p_run_id::text || case when p_lane = 'presg' then ':presg:organization' else ':ud:organization' end
  );
  v_staff_user uuid := private.demo_seed_user(p_lane, p_run_id, 1);
  v_survey_id uuid;
  v_session_id uuid;
  v_state text;
  v_quarter_anchor timestamptz := pg_catalog.date_trunc(
    'quarter', pg_catalog.now(), 'UTC'
  );
  v_period_start timestamptz;
  v_period_end timestamptz;
  v_event_cap timestamptz := pg_catalog.date_trunc('day', pg_catalog.now(), 'UTC');
  v_event_at timestamptz;
  v_response_count integer;
  v_review_ordinal integer := 0;
  i integer;
  quarter_index integer;
  respondent integer;
begin
  if p_lane not in ('presg', 'uniondemo') then
    raise exception 'unknown demo lane';
  end if;
  if not exists (
    select 1 from public.organizations organization
    where organization.id = v_organization_id and organization.status = 'active'
  ) then
    raise exception 'demo organization is missing';
  end if;
  if not exists (
    select 1 from public.organization_surveys survey
    where survey.organization_id = v_organization_id
      and survey.id = private.member_stress_uuid(p_run_id::text || ':voice:survey:16')
  ) then
    raise exception 'Voice survey parity phase must run before Voice operations';
  end if;

  -- A SAMPLE staff persona can exercise the real distribution/reminder RPCs
  -- between reseeds. Those RPCs intentionally write the production outbox,
  -- but SAMPLE has no outbound dispatcher. Reset every run-owned survey key
  -- before rebuilding deterministic evidence so no queued residue survives or
  -- escapes the zero-egress status check.
  delete from public.engagement_delivery_outbox outbound
  where outbound.organization_id = v_organization_id
    and outbound.source_kind = 'survey'
    and outbound.source_id in (
      select private.member_stress_uuid(
        p_run_id::text || ':voice:survey:' || series.n
      )::text
      from pg_catalog.generate_series(1, 16) series(n)
    );

  -- A reseed is a bounded SAMPLE fixture reset. Remove mutable rows created by
  -- real Configure, Distribute, Remind, and response flows before rebuilding
  -- the exact run-owned operating history.
  delete from public.organization_survey_sessions session
  where session.organization_id = v_organization_id
    and session.survey_id in (
      select private.member_stress_uuid(p_run_id::text || ':voice:survey:' || series.n)
      from pg_catalog.generate_series(1, 12) series(n)
    );
  delete from public.organization_survey_deliveries delivery
  where delivery.organization_id = v_organization_id
    and delivery.survey_id in (
      select private.member_stress_uuid(p_run_id::text || ':voice:survey:' || series.n)
      from pg_catalog.generate_series(1, 16) series(n)
    );
  delete from public.organization_survey_tasks task
  where task.organization_id = v_organization_id
    and task.survey_id in (
      select private.member_stress_uuid(p_run_id::text || ':voice:survey:' || series.n)
      from pg_catalog.generate_series(1, 16) series(n)
    );

  if exists (
    select 1
    from public.organization_surveys survey
    where survey.organization_id = v_organization_id
      and survey.cadence = 'quarterly'
      and survey.period_key in (
        select pg_catalog.to_char(
          v_quarter_anchor - ((series.n * 3) || ' months')::interval,
          'YYYY'
        ) || '-Q' || pg_catalog.date_part(
          'quarter', v_quarter_anchor - ((series.n * 3) || ' months')::interval
        )::integer
        from pg_catalog.generate_series(0, 11) series(n)
      )
      and survey.id not in (
        select private.member_stress_uuid(p_run_id::text || ':voice:survey:' || series.n)
        from pg_catalog.generate_series(1, 12) series(n)
      )
  ) then
    raise exception 'a non-seed quarterly survey already owns a rolling-history period';
  end if;

  update public.organization_surveys survey
  set cadence = 'one_off', period_key = null, updated_at = pg_catalog.now()
  where survey.organization_id = v_organization_id
    and survey.id in (
      select private.member_stress_uuid(p_run_id::text || ':voice:survey:' || series.n)
      from pg_catalog.generate_series(1, 12) series(n)
    );

  for quarter_index in 0..11 loop
    i := quarter_index + 1;
    v_survey_id := private.member_stress_uuid(p_run_id::text || ':voice:survey:' || i);
    v_period_start := v_quarter_anchor - ((quarter_index * 3) || ' months')::interval;
    v_period_end := v_period_start + interval '3 months' - interval '1 second';

    update public.organization_surveys survey
    set title = 'Quarterly member experience — '
          || pg_catalog.to_char(v_period_start at time zone 'UTC', 'YYYY')
          || ' Q' || pg_catalog.date_part('quarter', v_period_start at time zone 'UTC')::integer,
        cadence = 'quarterly',
        period_key = pg_catalog.to_char(v_period_start at time zone 'UTC', 'YYYY')
          || '-Q' || pg_catalog.date_part('quarter', v_period_start at time zone 'UTC')::integer,
        status = case when quarter_index = 0 then 'open' else 'closed' end,
        opens_at = v_period_start,
        closes_at = v_period_end,
        owner_user_id = v_staff_user,
        operations_state = case when quarter_index = 0 then 'reviewing' else 'complete' end,
        review_due_at = v_period_end + interval '7 days',
        updated_at = pg_catalog.now()
    where survey.organization_id = v_organization_id and survey.id = v_survey_id;
  end loop;

  -- Rebuild deterministic submitted history through the real in-progress to
  -- submitted transition. The current quarter stays below the five-response
  -- privacy floor, the prior quarter clears it, and every older quarter keeps
  -- one valid long-form response in the rolling history.
  for quarter_index in 0..11 loop
    i := quarter_index + 1;
    v_survey_id := private.member_stress_uuid(p_run_id::text || ':voice:survey:' || i);
    v_period_start := v_quarter_anchor - ((quarter_index * 3) || ' months')::interval;
    v_response_count := case when i = 1 then 3 when i = 2 then 6 else 1 end;
    for respondent in 1..v_response_count loop
      v_session_id := private.member_stress_uuid(
        p_run_id::text || ':voice:survey:' || i || ':session:' || respondent
      );
      v_event_at := least(
        v_period_start + interval '21 days' + ((respondent - 1) || ' days')::interval,
        v_event_cap
      );
      insert into public.organization_survey_sessions (
        id, organization_id, survey_id, respondent_user_id, status,
        created_at, updated_at, submitted_at
      ) values (
        v_session_id, v_organization_id, v_survey_id,
        private.demo_seed_user(p_lane, p_run_id, 10 + respondent),
        'in_progress', v_event_at, v_event_at, null
      );

      insert into public.organization_survey_answers
        (organization_id, session_id, question_id, value, updated_at)
      values
        (v_organization_id, v_session_id,
         private.member_stress_uuid(p_run_id::text || ':voice:survey:' || i || ':question:1'),
         '"Often"'::jsonb, v_event_at),
        (v_organization_id, v_session_id,
         private.member_stress_uuid(p_run_id::text || ':voice:survey:' || i || ':question:2'),
         pg_catalog.to_jsonb('Workload changes made scheduling less predictable.'::text), v_event_at),
        (v_organization_id, v_session_id,
         private.member_stress_uuid(p_run_id::text || ':voice:survey:' || i || ':question:3'),
         pg_catalog.to_jsonb(('Program ' || respondent)::text), v_event_at),
        (v_organization_id, v_session_id,
         private.member_stress_uuid(p_run_id::text || ':voice:survey:' || i || ':question:4'),
         '["Scheduling","Workload"]'::jsonb, v_event_at),
        (v_organization_id, v_session_id,
         private.member_stress_uuid(p_run_id::text || ':voice:survey:' || i || ':question:5'),
         '"Email"'::jsonb, v_event_at),
        (v_organization_id, v_session_id,
         private.member_stress_uuid(p_run_id::text || ':voice:survey:' || i || ':question:6'),
         '4'::jsonb, v_event_at),
        (v_organization_id, v_session_id,
         private.member_stress_uuid(p_run_id::text || ':voice:survey:' || i || ':question:7'),
         pg_catalog.to_jsonb(least(respondent, 5)), v_event_at),
        (v_organization_id, v_session_id,
         private.member_stress_uuid(p_run_id::text || ':voice:survey:' || i || ':question:8'),
         '"yes"'::jsonb, v_event_at);

      update public.organization_survey_sessions session
      set status = 'submitted',
          submitted_at = least(v_event_at + interval '2 hours', v_event_cap),
          updated_at = least(v_event_at + interval '2 hours', v_event_cap)
      where session.id = v_session_id and session.status = 'in_progress';
    end loop;
  end loop;

  -- The status transition intentionally exercises the production trigger.
  -- Replace trigger-created mutable rows with the exact historical fixture.
  delete from public.organization_survey_reviews review
  where review.organization_id = v_organization_id
    and review.survey_id in (
      select private.member_stress_uuid(p_run_id::text || ':voice:survey:' || series.n)
      from pg_catalog.generate_series(1, 12) series(n)
    );
  delete from public.organization_survey_deliveries delivery
  where delivery.organization_id = v_organization_id
    and delivery.survey_id in (
      select private.member_stress_uuid(p_run_id::text || ':voice:survey:' || series.n)
      from pg_catalog.generate_series(1, 12) series(n)
    );

  for i in 1..16 loop
    v_survey_id := private.member_stress_uuid(p_run_id::text || ':voice:survey:' || i);
    v_event_at := case when i <= 12 then least(
      v_quarter_anchor - (((i - 1) * 3) || ' months')::interval + interval '42 days',
      v_event_cap
    ) else v_event_cap - ((i - 12) || ' days')::interval end;
    insert into public.organization_survey_tasks (
      id, organization_id, survey_id, reason, status,
      assigned_to, due_at, created_by, created_at, updated_at
    ) values (
      private.member_stress_uuid(p_run_id::text || ':voice:task:' || i),
      v_organization_id,
      v_survey_id,
      (array['readiness', 'distribution', 'response_review', 'closeout'])[1 + ((i - 1) % 4)],
      (array['open', 'in_progress', 'done', 'dismissed'])[1 + ((i - 1) % 4)],
      v_staff_user,
      v_event_at + interval '7 days',
      v_staff_user,
      v_event_at - interval '7 days',
      v_event_at
    )
    on conflict (survey_id, reason) do update set
      status = excluded.status,
      assigned_to = excluded.assigned_to,
      due_at = excluded.due_at,
      updated_at = excluded.updated_at;
  end loop;

  for i in 1..24 loop
    v_survey_id := private.member_stress_uuid(
      p_run_id::text || ':voice:survey:' || (1 + ((i - 1) % 12))
    );
    v_period_start := v_quarter_anchor
      - ((((i - 1) % 12) * 3) || ' months')::interval;
    v_event_at := least(
      v_period_start + interval '35 days' + (((i - 1) / 12) || ' days')::interval,
      v_event_cap
    );
    v_state := (array['queued', 'leased', 'sent', 'failed', 'engaged', 'suppressed'])[1 + ((i - 1) % 6)];
    insert into public.organization_survey_deliveries (
      id, organization_id, survey_id, recipient_user_id, state,
      attempt_count, last_attempt_at, sent_at, engaged_at,
      escalation_state, last_error_code, created_at, updated_at
    ) values (
      private.member_stress_uuid(p_run_id::text || ':voice:delivery:' || i),
      v_organization_id,
      v_survey_id,
      private.demo_seed_user(p_lane, p_run_id, 10 + i),
      v_state,
      case when v_state in ('queued', 'suppressed') then 0 when v_state = 'failed' then 2 else 1 end,
      case when v_state in ('queued', 'suppressed') then null else v_event_at end,
      case when v_state in ('sent', 'engaged') then v_event_at else null end,
      case when v_state = 'engaged' then least(v_event_at + interval '1 hour', v_event_cap) else null end,
      case when v_state = 'failed' then 'reminder_due' when v_state = 'engaged' then 'resolved' else 'none' end,
      case when v_state = 'failed' then 'sample-transient' else null end,
      v_event_at - interval '2 days',
      least(
        v_event_at + case when v_state = 'engaged' then interval '1 hour' else interval '0 hours' end,
        v_event_cap
      )
    )
    on conflict (survey_id, recipient_user_id) do update set
      state = excluded.state,
      attempt_count = excluded.attempt_count,
      last_attempt_at = excluded.last_attempt_at,
      sent_at = excluded.sent_at,
      engaged_at = excluded.engaged_at,
      escalation_state = excluded.escalation_state,
      last_error_code = excluded.last_error_code,
      updated_at = excluded.updated_at;
  end loop;

  for quarter_index in 0..11 loop
    i := quarter_index + 1;
    v_survey_id := private.member_stress_uuid(p_run_id::text || ':voice:survey:' || i);
    v_period_start := v_quarter_anchor - ((quarter_index * 3) || ' months')::interval;
    v_response_count := case when i = 1 then 3 when i = 2 then 6 else 1 end;
    for respondent in 1..v_response_count loop
      v_review_ordinal := v_review_ordinal + 1;
      v_session_id := private.member_stress_uuid(
        p_run_id::text || ':voice:survey:' || i || ':session:' || respondent
      );
      v_state := (array['unreviewed', 'assigned', 'follow_up', 'resolved', 'dismissed'])[
        1 + ((v_review_ordinal - 1) % 5)
      ];
      v_event_at := least(
        v_period_start + interval '24 days' + ((respondent - 1) || ' days')::interval,
        v_event_cap
      );
      insert into public.organization_survey_reviews (
        id, organization_id, survey_id, session_id, state, assigned_to,
        disposition, follow_up_due_at, created_at, updated_at
      ) values (
        private.member_stress_uuid(p_run_id::text || ':voice:review:' || v_review_ordinal),
        v_organization_id, v_survey_id, v_session_id, v_state,
        case when v_state = 'unreviewed' then null else v_staff_user end,
        case
          when v_state = 'follow_up' then 'Member requested a steward conversation.'
          when v_state = 'resolved' then 'Follow-up completed and documented.'
          when v_state = 'dismissed' then 'No staff action required after review.'
          else null
        end,
        case when v_state = 'follow_up' then v_event_at + interval '5 days' else null end,
        v_event_at, v_event_at
      );
    end loop;
  end loop;

  return private.demo_seed_voice_operations_status(p_lane, p_run_id);
end;
end;
$function$

CREATE OR REPLACE FUNCTION private.demo_seed_archive_organization_on_remove()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  perform private.lock_case_graph(array[auth.uid()], array[]::uuid[]);

declare
  organization uuid;
begin
  if new.state = 'removing' and old.state is distinct from 'removing' then
    organization := private.member_stress_uuid(
      new.id::text || case when tg_table_name = 'presg_demo_runs'
        then ':presg:organization' else ':ud:organization' end
    );
    update public.organizations target
    set status = 'archived', updated_at = pg_catalog.now()
    where target.id = organization and target.status = 'active';
  end if;
  return new;
end;
end;
$function$

CREATE OR REPLACE FUNCTION private.demo_seed_auth_operations_status(p_lane text, p_run_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_organization_id uuid;
  passkey_ready boolean;
  recovery_ready boolean;
  settings_ready boolean;
  labels_ready boolean;
  failed_login_ready boolean;
begin
  if p_lane = 'presg' then
    v_organization_id := private.member_stress_uuid(p_run_id::text || ':presg:organization');
  elsif p_lane = 'uniondemo' then
    v_organization_id := private.member_stress_uuid(p_run_id::text || ':ud:organization');
  else
    raise exception 'unknown demo lane';
  end if;

  select exists (
    select 1 from public.organization_setting_values v
    where v.organization_id = v_organization_id
      and v.setting_key = 'features.passkey_enrollment'
      and v.value = 'true'::jsonb
  ) into passkey_ready;

  select exists (
    select 1 from public.organization_setting_values v
    where v.organization_id = v_organization_id
      and v.setting_key = 'features.mfa_recovery_code_enrollment'
      and v.value = 'true'::jsonb
  ) into recovery_ready;

  select pg_catalog.count(*) = 4 into settings_ready
  from public.organization_setting_values v
  where v.organization_id = v_organization_id
    and (v.setting_key, v.value) in (
      ('features.passkey_enrollment', 'true'::jsonb),
      ('features.mfa_recovery_code_enrollment', 'true'::jsonb),
      ('security.failed_login_retention_days', '90'::jsonb),
      ('security.failed_login_alert_threshold', '3'::jsonb)
    );

  select pg_catalog.count(*) = 2 into labels_ready
  from public.organization_label_overrides o
  where o.organization_id = v_organization_id
    and (o.label_key, o.label_value) in (
      ('nav.myCases', 'Case support'),
      ('staff.chapterWork', 'Chapter work')
    );

  select pg_catalog.count(*) = 6 into failed_login_ready
  from public.organization_failed_login_attempts a
  where a.organization_id = v_organization_id
    and a.id in (
      select private.member_stress_uuid(p_run_id::text || ':auth:failed-login:' || n::text)
      from pg_catalog.generate_series(1, 6) as seeded(n)
    )
    and a.member_user_id is not null
    and a.identity_hash ~ '^[a-f0-9]{64}$';

  return pg_catalog.jsonb_build_object(
    'ok', passkey_ready and recovery_ready and settings_ready and labels_ready and failed_login_ready,
    'CR-100', passkey_ready,
    'CR-101', recovery_ready,
    'CR-102', settings_ready,
    'CR-103', labels_ready,
    'CR-105', failed_login_ready,
    'credentialRowsSeeded', 0,
    'outboundDeliveries', 0
  );
end;
$function$

CREATE OR REPLACE FUNCTION private.demo_seed_chapter(p_lane text, p_run_id uuid, p_ordinal integer)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  found_chapter text;
  lane_count integer;
begin
  if p_lane = 'presg' then
    return 'presg';
  elsif p_lane = 'uniondemo' then
    select pg_catalog.count(*)::integer into lane_count
    from private.uniondemo_chapters
    where run_id = p_run_id;

    if lane_count = 0 then
      raise exception 'union demo run has no seeded chapters';
    end if;

    select chapter_id into found_chapter
    from private.uniondemo_chapters
    where run_id = p_run_id
      and chapter_index = 1 + (greatest(p_ordinal, 1) - 1) % lane_count;

    if found_chapter is null then
      raise exception 'union demo chapter map is not contiguous';
    end if;
    return found_chapter;
  end if;
  raise exception 'unknown demo lane';
end;
$function$

