CREATE OR REPLACE FUNCTION private.demo_seed_institutional_records_from_evidence()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  perform private.lock_case_graph(array[auth.uid()], array[]::uuid[]);

declare
  run record;
  org uuid;
  chapter text;
  creator uuid;
  record_id uuid;
  grant_id uuid;
  i integer;
  record_kind text;
  record_version integer;
  previous_claims text;
begin
  if pg_catalog.pg_trigger_depth() > 1 then return null; end if;
  for run in
    select distinct evidence.lane, evidence.run_id
    from inserted_institutional_evidence evidence
    where evidence.surface = 'memberWeeklyQuestions'
  loop
    if run.lane not in ('presg','uniondemo') then continue; end if;
    org := private.member_stress_uuid(run.run_id::text || case when run.lane = 'presg' then ':presg:organization' else ':ud:organization' end);
    chapter := private.demo_seed_chapter(run.lane, run.run_id, 1);
    creator := private.demo_seed_user(run.lane, run.run_id, 1);
    if not exists (select 1 from public.organizations o where o.id = org)
       or not exists (select 1 from public.chapters c where c.id = chapter and c.organization_id = org)
       or not exists (select 1 from auth.users u where u.id = creator) then
      continue;
    end if;

    previous_claims := pg_catalog.current_setting('request.jwt.claims', true);
    perform pg_catalog.set_config(
      'request.jwt.claims',
      pg_catalog.jsonb_build_object(
        'sub', creator,
        'role', 'service_role',
        'aal', 'aal2'
      )::text,
      true
    );

    for i in 1..18 loop
      record_id := private.member_stress_uuid(run.run_id::text || ':institutional:record:' || i);
      record_kind := case when i % 3 = 0 then 'minutes' when i % 2 = 0 then 'decision' else 'milestone' end;
      record_version := case when i in (3, 8, 15) then 2 else 1 end;
      insert into public.chapter_records (
        id, chapter_id, record_type, title, body, occurred_at, created_by,
        lifecycle_status, visibility, version, published_at, updated_at,
        pinned_at, gap_note, archived_at
      ) values (
        record_id, chapter, record_kind,
        (array[
          'Member orientation program launched', 'Caseload documentation standard adopted',
          'Quarterly chapter meeting', 'Bargaining priorities confirmed',
          'Safety committee formed', 'Labor-management meeting',
          'New steward cohort completed training', 'Scheduling proposal approved',
          'Annual chapter meeting', 'Contract education series opened',
          'Community coalition partnership began', 'Benefits briefing',
          'Workload evidence review completed', 'Member communication standard adopted',
          'Fall chapter meeting', 'Representation coverage expanded',
          'Records retention practice confirmed', 'Winter chapter meeting'
        ])[i],
        (array[
          'The chapter established a recurring welcome session and assigned follow-up owners.',
          'Members approved one shared method for recording workload and short-notice changes.',
          'Members reviewed open work, confirmed decisions, and assigned the next steps.',
          'The chapter adopted member-ranked priorities for the next bargaining cycle.',
          'A member-led committee began a regular hazard review and escalation cadence.',
          'Representatives presented documented scheduling and workload issues to management.'
        ])[1 + ((i - 1) % 6)],
        pg_catalog.now() - ((18 - i) * 62 || ' days')::interval,
        creator, 'published', 'chapter', record_version,
        pg_catalog.now() - ((18 - i) * 62 || ' days')::interval,
        pg_catalog.now() - ((18 - i) * 62 || ' days')::interval,
        case when i in (5, 14, 18) then pg_catalog.now() - ((18 - i) * 62 || ' days')::interval end,
        case when i = 10 then 'Earlier organizing notes are held in a paper archive and are queued for digitization.' end,
        null
      ) on conflict (id) do update set
        chapter_id = excluded.chapter_id, record_type = excluded.record_type,
        title = excluded.title, body = excluded.body, occurred_at = excluded.occurred_at,
        lifecycle_status = excluded.lifecycle_status, visibility = excluded.visibility,
        version = excluded.version, published_at = excluded.published_at,
        updated_at = excluded.updated_at, pinned_at = excluded.pinned_at,
        gap_note = excluded.gap_note, archived_at = null;

      insert into public.chapter_record_versions (
        id, record_id, chapter_id, version, record_type, title, body, occurred_at,
        lifecycle_status, visibility, gap_note, changed_by, created_at
      ) values (
        private.member_stress_uuid(run.run_id::text || ':institutional:record:' || i || ':version:1'),
        record_id, chapter, 1, record_kind,
        (select title from public.chapter_records where id = record_id),
        case when record_version = 2 then 'Initial draft retained for the institutional record.' else (select body from public.chapter_records where id = record_id) end,
        (select occurred_at from public.chapter_records where id = record_id),
        case when record_version = 2 then 'draft' else 'published' end,
        'chapter', (select gap_note from public.chapter_records where id = record_id), creator,
        (select occurred_at from public.chapter_records where id = record_id)
      ) on conflict (record_id, version) do update set body = excluded.body, lifecycle_status = excluded.lifecycle_status;
      if record_version = 2 then
        insert into public.chapter_record_versions (
          id, record_id, chapter_id, version, record_type, title, body, occurred_at,
          lifecycle_status, visibility, gap_note, changed_by, created_at
        ) select
          private.member_stress_uuid(run.run_id::text || ':institutional:record:' || i || ':version:2'),
          r.id, r.chapter_id, 2, r.record_type, r.title, r.body, r.occurred_at,
          'published', r.visibility, r.gap_note, creator, r.updated_at
        from public.chapter_records r where r.id = record_id
        on conflict (record_id, version) do update set body = excluded.body, lifecycle_status = excluded.lifecycle_status;
      end if;

      if record_kind = 'minutes' then
        insert into public.meeting_attendance (record_id, chapter_id, user_id, attendance_status, recorded_by, recorded_at)
        select record_id, chapter, private.demo_seed_user(run.lane, run.run_id, member_index),
          case member_index % 6 when 0 then 'excused' else 'present' end,
          creator, (select occurred_at from public.chapter_records where id = record_id)
        from pg_catalog.generate_series(1, 24) member_index
        where exists (select 1 from auth.users u where u.id = private.demo_seed_user(run.lane, run.run_id, member_index))
        on conflict (record_id, user_id) do update set attendance_status = excluded.attendance_status, recorded_at = excluded.recorded_at;
        insert into public.meeting_minutes_dispatches (
          id, record_id, chapter_id, version, recipient_id, status, delivered_at, created_at
        ) select
          private.member_stress_uuid(run.run_id::text || ':institutional:dispatch:' || i || ':' || member_index),
          record_id, chapter, record_version,
          private.demo_seed_user(run.lane, run.run_id, member_index), 'delivered',
          (select published_at from public.chapter_records where id = record_id),
          (select published_at from public.chapter_records where id = record_id)
        from pg_catalog.generate_series(1, 24) member_index
        where exists (select 1 from auth.users u where u.id = private.demo_seed_user(run.lane, run.run_id, member_index))
        on conflict (record_id, version, recipient_id, channel) do update set status = 'delivered', delivered_at = excluded.delivered_at;
      end if;
    end loop;

    for i in 1..36 loop
      insert into public.chapter_contact_log (
        id, organization_id, chapter_id, subject_user_id, contact_kind, channel,
        purpose, summary, outcome, occurred_at, follow_up_at, created_by, updated_by,
        created_at, updated_at
      ) values (
        private.member_stress_uuid(run.run_id::text || ':institutional:contact:' || i),
        org, chapter,
        case when i % 4 = 0 then null else private.demo_seed_user(run.lane, run.run_id, 2 + (i % 40)) end,
        (array['member','management','community','provider'])[1 + ((i - 1) % 4)],
        (array['phone','email','meeting','in_person','message'])[1 + ((i - 1) % 5)],
        (array['Scheduling follow-up','Workload documentation','Community coordination','Benefits question'])[1 + ((i - 1) % 4)],
        'Recorded the conversation, agreed on a next step, and assigned follow-up where needed.',
        case when i % 3 = 0 then 'Follow-up completed and documented.' else 'Awaiting the agreed follow-up.' end,
        pg_catalog.now() - (i * 26 || ' days')::interval,
        case when i <= 4 then pg_catalog.now() + (i || ' days')::interval end,
        creator, creator,
        pg_catalog.now() - (i * 26 || ' days')::interval,
        pg_catalog.now() - (i * 26 || ' days')::interval
      ) on conflict (id) do update set summary = excluded.summary, outcome = excluded.outcome, follow_up_at = excluded.follow_up_at, archived_at = null;
    end loop;

    insert into public.organization_data_export_runs (
      id, organization_id, requested_by, format, domains, filters, row_count, expires_at, status, created_at
    ) values
      (private.member_stress_uuid(run.run_id::text || ':institutional:export:1'), org, creator, 'csv', array['members','cases','tasks'], '{}'::jsonb, 128, pg_catalog.now() + interval '15 minutes', 'ready', pg_catalog.now() - interval '2 days'),
      (private.member_stress_uuid(run.run_id::text || ':institutional:export:2'), org, creator, 'json', array['minutes','timeline','contacts'], '{}'::jsonb, 54, pg_catalog.now() + interval '15 minutes', 'ready', pg_catalog.now() - interval '9 days')
    on conflict (id) do update set row_count = excluded.row_count, expires_at = excluded.expires_at, status = excluded.status;

    -- Give one current-week question an explicit, already-spent promotion and
    -- leave the featured member's own grant unused so the control is visible.
    select g.id into grant_id
    from public.member_reward_grants g
    where g.organization_id = org and g.user_id = private.demo_seed_user(run.lane, run.run_id, 3)
      and g.item_key = 'priority-wq-slot' and g.status <> 'revoked'
    limit 1;
    if grant_id is null then
      grant_id := private.member_stress_uuid(run.run_id::text || ':institutional:promotion-grant');
      insert into public.member_reward_grants (id, organization_id, user_id, item_key, status, source, reason)
      values (grant_id, org, private.demo_seed_user(run.lane, run.run_id, 3), 'priority-wq-slot', 'granted', 'admin_grant', 'Chapter participation recognition')
      on conflict do nothing;
    end if;
    insert into public.member_weekly_question_promotions (question_id, reward_grant_id, organization_id, chapter_id, user_id)
    select q.id, grant_id, org, chapter, q.user_id
    from public.member_weekly_questions q
    where q.id = private.member_stress_uuid(run.run_id::text || ':voice:weekly:1')
      and q.user_id = private.demo_seed_user(run.lane, run.run_id, 3)
    on conflict (question_id) do nothing;

    perform pg_catalog.set_config(
      'request.jwt.claims', coalesce(previous_claims, ''), true
    );
  end loop;
  return null;
end;
end;
$function$

CREATE OR REPLACE FUNCTION private.demo_seed_knowledge_library_status(p_lane text, p_run_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  org uuid := case when p_lane = 'presg'
    then private.member_stress_uuid(p_run_id::text || ':presg:organization')
    when p_lane = 'uniondemo'
    then private.member_stress_uuid(p_run_id::text || ':ud:organization')
    else null end;
  files bigint;
  sources bigint;
  collections bigint;
  articles bigint;
  revisions bigint;
  objects bigint;
  evidence bigint;
  drive_unset boolean;
  drive_status text;
  activation_state text;
begin
  select pg_catalog.count(*) into files
  from public.organization_knowledge_files file
  where file.id in (
    select private.member_stress_uuid(p_run_id::text || ':knowledge:file:' || series.n)
    from pg_catalog.generate_series(1, 200) series(n)
  ) and file.organization_id = org and file.review_status = 'approved'
    and file.scan_status = 'clean' and file.published_to_catalog;
  select pg_catalog.count(*) into sources
  from public.organization_knowledge_sources source
  where source.id in (
    select private.member_stress_uuid(p_run_id::text || ':knowledge:source:' || series.n)
    from pg_catalog.generate_series(1, 200) series(n)
  ) and source.organization_id = org and source.chunk_count = 2;
  select pg_catalog.count(*) into collections
  from public.knowledge_collections collection
  where collection.id in (
    select private.member_stress_uuid(p_run_id::text || ':knowledge:collection:' || series.n)
    from pg_catalog.generate_series(1, 20) series(n)
  ) and collection.organization_id = org;
  select pg_catalog.count(*) into articles
  from public.member_kb_articles article
  where article.id in (
    select private.member_stress_uuid(p_run_id::text || ':knowledge:article:' || series.n)
    from pg_catalog.generate_series(1, 12) series(n)
  ) and article.chapter_id = private.demo_seed_chapter(p_lane, p_run_id, 1)
    and article.status = 'published' and not article.is_sample;
  select pg_catalog.count(*) into revisions
  from public.member_kb_article_revisions revision
  where revision.article_id in (
    select private.member_stress_uuid(p_run_id::text || ':knowledge:article:' || series.n)
    from pg_catalog.generate_series(1, 12) series(n)
  );
  select pg_catalog.count(*) into objects
  from storage.objects object
  where object.bucket_id = 'organization-knowledge'
    and object.name in (
      select file.storage_path from public.organization_knowledge_files file
      where file.id in (
        select private.member_stress_uuid(p_run_id::text || ':knowledge:file:' || series.n)
        from pg_catalog.generate_series(1, 200) series(n)
      )
    );
  select pg_catalog.count(*) into evidence
  from private.demo_seed_function_evidence evidence_row
  where evidence_row.lane = p_lane and evidence_row.run_id = p_run_id
    and evidence_row.function_id in ('CR-071', 'CR-072', 'CR-073', 'CR-074', 'CR-075')
    and evidence_row.status = 'seeded';
  select coalesce((
    select integration.status
    from public.organization_integrations integration
    where integration.organization_id = org and integration.provider = 'google_drive'
  ), 'unset') into drive_status;
  select not exists (
    select 1 from public.organization_integrations integration
    where integration.organization_id = org and integration.provider = 'google_drive'
      and (integration.status <> 'unset' or integration.credential_ref is not null)
  ) and not exists (
    select 1 from private.google_drive_oauth_states oauth_state
    where oauth_state.organization_id = org
      and oauth_state.expires_at > pg_catalog.now()
  ) into drive_unset;
  activation_state := case
    when files = 0 and sources = 0 and collections = 0 and articles = 0
      and revisions = 0 and objects = 0 and evidence = 0 then 'absent'
    when files = 200 and sources = 200 and collections = 20
      and articles = 12 and revisions = 36 and objects = 200
      and evidence = 5 and drive_unset then 'complete'
    else 'partial'
  end;
  return pg_catalog.jsonb_build_object(
    'ok', activation_state = 'complete',
    'activationState', activation_state,
    'files', files,
    'sources', sources,
    'collections', collections,
    'articles', articles,
    'revisions', revisions,
    'objects', objects,
    'evidence', evidence,
    'driveStatus', drive_status,
    'driveUnset', drive_unset,
    'outboundDeliveries', 0
  );
end;
$function$

CREATE OR REPLACE FUNCTION private.demo_seed_member_operations_from_evidence()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  perform private.lock_case_graph(array[auth.uid()], array[]::uuid[]);

declare
  run record;
  org uuid;
  chapter text;
  creator uuid;
  seed_campaign_id uuid;
  seed_step_id uuid;
  seed_enrollment_id uuid;
  seed_batch_id uuid;
  seed_member_id uuid;
  i integer;
begin
  if pg_catalog.pg_trigger_depth() > 1 then return null; end if;
  for run in select distinct lane, run_id from inserted_member_operations_evidence
  loop
    if run.lane not in ('presg','uniondemo') then continue; end if;
    org := private.member_stress_uuid(run.run_id::text || case when run.lane = 'presg' then ':presg:organization' else ':ud:organization' end);
    chapter := private.demo_seed_chapter(run.lane, run.run_id, 1);
    creator := private.demo_seed_user(run.lane, run.run_id, 1);
    if not exists (select 1 from public.organizations source where source.id = org)
       or not exists (select 1 from public.chapters source where source.id = chapter and source.organization_id = org)
       or not exists (select 1 from auth.users source where source.id = creator) then
      continue;
    end if;

    insert into public.weekly_question_selection_policies (
      organization_id, chapter_id, enabled, cadence_days, minimum_pool_size,
      selection_count, priority_rule, next_run_at, last_run_at, last_result, updated_by
    ) values (
      org, chapter, true, 7, 3, 1, 'support_then_oldest',
      pg_catalog.now() + interval '3 days', pg_catalog.now() - interval '4 days',
      pg_catalog.jsonb_build_object('selectedCount',1,'poolCount',52,'seeded',true), creator
    ) on conflict (organization_id, chapter_id) do update set
      enabled = true, next_run_at = excluded.next_run_at, last_run_at = excluded.last_run_at,
      last_result = excluded.last_result, updated_by = excluded.updated_by, updated_at = pg_catalog.now();

    for i in 1..104 loop
      seed_member_id := private.demo_seed_user(run.lane, run.run_id, 2 + ((i - 1) % 80));
      if exists (select 1 from public.organization_memberships membership
        where membership.organization_id = org and membership.user_id = seed_member_id and membership.status = 'active') then
        insert into public.member_weekly_questions (
          id, chapter_id, user_id, week_start, body, options, editorial_state,
          editor_note, created_at, updated_at
        ) values (
          private.member_stress_uuid(run.run_id::text || ':member-operations:weekly:' || i),
          chapter, seed_member_id,
          (pg_catalog.date_trunc('week', pg_catalog.now() at time zone 'UTC')::date - (i * 7)),
          'Which workplace priority should the chapter discuss next? ' || i,
          '["Scheduling","Workload","Safety"]'::jsonb,
          case when i <= 26 then 'submitted' when i <= 52 then 'reserved' else 'archived' end,
          case when i > 26 then 'Reviewed in the weekly editorial cycle.' end,
          pg_catalog.now() - (i * 7 || ' days')::interval,
          pg_catalog.now() - (i * 7 || ' days')::interval
        ) on conflict (id) do update set
          editorial_state = excluded.editorial_state, editor_note = excluded.editor_note,
          updated_at = excluded.updated_at;
      end if;
    end loop;

    insert into public.organization_member_operational_profiles (
      organization_id, member_user_id, member_number, job_title, department,
      work_location, hire_date, membership_class, preferred_language,
      administrative_notes, updated_by
    )
    select org, membership.user_id,
      'UG-' || pg_catalog.lpad(roster.ordinality::text, 5, '0'),
      (array['Program specialist','Field representative','Analyst','Coordinator'])[1 + ((roster.ordinality - 1) % 4)],
      (array['Member services','Operations','Education','Field support'])[1 + ((roster.ordinality - 1) % 4)],
      (array['Pine Harbor','Maple Crossing','Cedar Ridge','Remote'])[1 + ((roster.ordinality - 1) % 4)],
      current_date - ((365 + roster.ordinality * 19) || ' days')::interval,
      case when roster.ordinality % 5 = 0 then 'Temporary' else 'Regular' end,
      case when roster.ordinality % 6 = 0 then 'es' else 'en' end,
      case when roster.ordinality % 7 = 0 then 'Follow up at the next scheduled roster review.' end,
      creator
    from (
      select source.user_id, pg_catalog.row_number() over (order by source.user_id) as ordinality
      from public.organization_memberships source
      where source.organization_id = org and source.status = 'active'
      order by source.user_id limit 50
    ) roster
    join public.organization_memberships membership
      on membership.organization_id = org and membership.user_id = roster.user_id
    on conflict (organization_id, member_user_id) do update set
      member_number = excluded.member_number, job_title = excluded.job_title,
      department = excluded.department, work_location = excluded.work_location,
      hire_date = excluded.hire_date, membership_class = excluded.membership_class,
      preferred_language = excluded.preferred_language,
      administrative_notes = excluded.administrative_notes, updated_by = excluded.updated_by,
      updated_at = pg_catalog.now();

    for i in 1..40 loop
      seed_member_id := private.demo_seed_user(run.lane, run.run_id, 10 + i);
      if exists (select 1 from public.organization_memberships membership
        where membership.organization_id = org and membership.user_id = seed_member_id and membership.status = 'active') then
        insert into public.member_handoffs (
          id, organization_id, chapter_id, member_user_id, from_steward_id,
          to_steward_id, initiated_by, status, note, idempotency_key,
          created_at, acknowledged_at, resolved_at
        ) values (
          private.member_stress_uuid(run.run_id::text || ':member-operations:handoff:' || i),
          org, chapter, seed_member_id,
          private.demo_seed_user(run.lane, run.run_id, 1),
          private.demo_seed_user(run.lane, run.run_id, 2), creator,
          case when i <= 2 then 'pending' when i % 4 = 0 then 'declined' when i % 5 = 0 then 'cancelled' else 'acknowledged' end,
          'Transfer includes current contacts, open follow-up, and the next agreed check-in.',
          private.member_stress_uuid(run.run_id::text || ':member-operations:handoff-key:' || i),
          pg_catalog.now() - (i * 24 || ' days')::interval,
          case when i > 2 and i % 4 <> 0 and i % 5 <> 0 then pg_catalog.now() - ((i * 24 - 1) || ' days')::interval end,
          case when i > 2 then pg_catalog.now() - ((i * 24 - 1) || ' days')::interval end
        ) on conflict (id) do update set status = excluded.status, note = excluded.note,
          acknowledged_at = excluded.acknowledged_at, resolved_at = excluded.resolved_at;
      end if;
    end loop;

    for i in 1..2 loop
      seed_campaign_id := private.member_stress_uuid(run.run_id::text || ':member-operations:campaign:' || i);
      insert into public.organization_welcome_campaigns (
        id, organization_id, name, state, created_by, updated_by, created_at, updated_at
      ) values (
        seed_campaign_id, org,
        case i when 1 then 'New member orientation' else 'First-month check-in' end,
        case i when 1 then 'active' else 'paused' end,
        creator, creator, pg_catalog.now() - (i * 180 || ' days')::interval, pg_catalog.now() - (i * 9 || ' days')::interval
      ) on conflict (id) do update set name = excluded.name, state = excluded.state, updated_at = excluded.updated_at;
      for step_number in 0..2 loop
        seed_step_id := private.member_stress_uuid(run.run_id::text || ':member-operations:campaign:' || i || ':step:' || step_number);
        insert into public.organization_welcome_campaign_steps (
          id, organization_id, campaign_id, position, delay_days, locale, subject, body, active
        ) values (
          seed_step_id, org, seed_campaign_id, step_number, step_number * 7, 'en',
          (array['Welcome to Union Ground','Your first-week guide','One-month check-in'])[step_number + 1],
          (array[
            'Your account is ready. Start with your chapter, rights, and message inbox.',
            'Review the member guide and choose the updates you want to receive.',
            'Tell your chapter team what would make the next month more useful.'
          ])[step_number + 1], true
        ) on conflict (campaign_id, position, locale) do update set
          subject = excluded.subject, body = excluded.body, active = true, updated_at = pg_catalog.now();
      end loop;
      for enrollment_number in 1..20 loop
        seed_member_id := private.demo_seed_user(run.lane, run.run_id, 20 + ((i - 1) * 20) + enrollment_number);
        if exists (select 1 from public.organization_memberships membership
          where membership.organization_id = org and membership.user_id = seed_member_id and membership.status = 'active') then
          seed_enrollment_id := private.member_stress_uuid(run.run_id::text || ':member-operations:campaign:' || i || ':enrollment:' || enrollment_number);
          insert into public.member_welcome_enrollments (
            id, organization_id, campaign_id, member_user_id, state,
            next_step_position, next_due_at, enrolled_by, enrolled_at, completed_at
          ) values (
            seed_enrollment_id, org, seed_campaign_id, seed_member_id,
            case when enrollment_number % 7 = 0 then 'paused' when enrollment_number % 5 = 0 then 'completed' else 'active' end,
            case when enrollment_number % 5 = 0 then 3 else 1 + (enrollment_number % 2) end,
            pg_catalog.now() + ((enrollment_number % 9) || ' days')::interval,
            creator, pg_catalog.now() - (enrollment_number * 11 || ' days')::interval,
            case when enrollment_number % 5 = 0 then pg_catalog.now() - interval '2 days' end
          ) on conflict (campaign_id, member_user_id) do update set
            state = excluded.state, next_step_position = excluded.next_step_position,
            next_due_at = excluded.next_due_at, completed_at = excluded.completed_at;
          seed_step_id := private.member_stress_uuid(run.run_id::text || ':member-operations:campaign:' || i || ':step:0');
          insert into public.engagement_delivery_outbox (
            id, organization_id, recipient_user_id, delivery_kind, source_kind,
            source_id, locale, state, attempt_count, sent_at, last_error_code,
            available_at, created_at, updated_at,
            subject_snapshot, body_snapshot, action_path_snapshot
          ) values (
            private.member_stress_uuid(run.run_id::text || ':member-operations:delivery:' || i || ':' || enrollment_number),
            org, seed_member_id, 'welcome', 'welcome_campaign', seed_enrollment_id::text || ':' || seed_step_id::text,
            'en', 'suppressed', 0, null, 'sample.seed',
            pg_catalog.now() - (enrollment_number || ' days')::interval,
            pg_catalog.now() - (enrollment_number || ' days')::interval,
            pg_catalog.now() - (enrollment_number || ' days')::interval,
            'Welcome to Union Ground',
            'Your account is ready. Start with your chapter, rights, and message inbox.',
            '/m/support?welcome=' || seed_enrollment_id::text
          ) on conflict (delivery_kind, source_id, recipient_user_id) do update set
            state = excluded.state, attempt_count = excluded.attempt_count,
            sent_at = excluded.sent_at, last_error_code = excluded.last_error_code;
        end if;
      end loop;
    end loop;

    for i in 1..20 loop
      seed_batch_id := private.member_stress_uuid(run.run_id::text || ':member-operations:import:' || i);
      seed_member_id := private.demo_seed_user(run.lane, run.run_id, 2 + i);
      insert into public.organization_import_batches (
        id, organization_id, kind, filename, mapping, state, row_count,
        valid_count, error_count, created_by, created_at, validated_at, committed_at
      ) values (
        seed_batch_id, org, case when i % 2 = 0 then 'member' else 'grievance' end,
        case when i % 2 = 0 then 'member-records-' || i || '.csv' else 'grievances-' || i || '.csv' end,
        case when i % 2 = 0 then '{"member_id":"member_id","department":"department"}'::jsonb
          else '{"member_id":"member_id","chapter_id":"chapter_id","reference":"reference","title":"title"}'::jsonb end,
        case when i <= 4 then 'validated' else 'committed' end,
        1, 1, 0, creator, pg_catalog.now() - (i * 17 || ' days')::interval,
        pg_catalog.now() - (i * 17 - 1 || ' days')::interval,
        case when i > 4 then pg_catalog.now() - (i * 17 - 2 || ' days')::interval end
      ) on conflict (id) do update set state = excluded.state, committed_at = excluded.committed_at;
      insert into public.organization_import_rows (
        organization_id, batch_id, row_number, normalized_data, validation_errors, created_at
      ) values (
        org, seed_batch_id, 1,
        case when i % 2 = 0 then pg_catalog.jsonb_build_object(
          'member_id',seed_member_id,'department','Member services','_resolved_member_id',seed_member_id
        ) else pg_catalog.jsonb_build_object(
          'member_id',seed_member_id,'chapter_id',chapter,'reference','DEMO-GR-' || pg_catalog.lpad(i::text,3,'0'),
          'title','Imported workplace concern','_resolved_member_id',seed_member_id
        ) end,
        '[]'::jsonb, pg_catalog.now() - (i * 17 || ' days')::interval
      ) on conflict (batch_id, row_number) do update set normalized_data = excluded.normalized_data, validation_errors = '[]'::jsonb;
    end loop;

    insert into private.demo_seed_page_evidence (lane, run_id, surface, actual_rows) values
      (run.lane, run.run_id, 'member-operations-weekly-admin', (
        select least(
          pg_catalog.count(*) filter (where question.editorial_state in ('submitted','reserved')),
          pg_catalog.count(*) filter (where question.editorial_state in ('published','archived'))
        )::integer
        from public.member_weekly_questions question
        where question.chapter_id = chapter
      )),
      (run.lane, run.run_id, 'member-operations-records', 50),
      (run.lane, run.run_id, 'member-operations-handoffs', 40),
      (run.lane, run.run_id, 'member-operations-welcome', 40),
      (run.lane, run.run_id, 'member-operations-imports', 20)
    on conflict (lane, run_id, surface) do update set actual_rows = excluded.actual_rows, recorded_at = pg_catalog.now();
  end loop;
  return null;
end;
end;
$function$

CREATE OR REPLACE FUNCTION private.demo_seed_member_support_status(p_lane text, p_run_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  org uuid := private.member_stress_uuid(
    p_run_id::text || case when p_lane = 'presg' then ':presg:organization' else ':ud:organization' end
  );
  emergency_count bigint;
  accommodation_count bigint;
  hr_contact_count bigint;
  onboarding_step_count bigint;
  onboarding_plan_count bigint;
  mentorship_pair_count bigint;
  mentorship_goal_count bigint;
  mentorship_note_count bigint;
  history_years bigint;
begin
  if p_lane not in ('presg', 'uniondemo') then raise exception 'unknown demo lane'; end if;
  select pg_catalog.count(*) into emergency_count from public.member_emergency_checklists where organization_id = org;
  select pg_catalog.count(*) into accommodation_count from public.member_accommodation_requests where organization_id = org;
  select pg_catalog.count(*) into hr_contact_count from public.member_hr_contacts where organization_id = org;
  select pg_catalog.count(*) into onboarding_step_count from public.organization_onboarding_steps where organization_id = org;
  select pg_catalog.count(*) into onboarding_plan_count from public.member_onboarding_plans where organization_id = org;
  select pg_catalog.count(*) into mentorship_pair_count from public.member_mentorship_pairs where organization_id = org;
  select pg_catalog.count(*) into mentorship_goal_count from public.member_mentorship_goals where organization_id = org;
  select pg_catalog.count(*) into mentorship_note_count from public.member_mentorship_notes where organization_id = org;
  select pg_catalog.count(distinct pg_catalog.date_part('year', occurred_at)) into history_years
  from public.member_support_events where organization_id = org;
  return pg_catalog.jsonb_build_object(
    'ok', emergency_count >= 3 and accommodation_count >= 36 and hr_contact_count >= 36
      and onboarding_step_count >= 4 and onboarding_plan_count >= 30
      and mentorship_pair_count >= 24 and mentorship_goal_count >= 48
      and mentorship_note_count >= 48 and history_years >= 3,
    'emergencyChecklists', emergency_count,
    'accommodationRequests', accommodation_count,
    'hrContacts', hr_contact_count,
    'onboardingSteps', onboarding_step_count,
    'onboardingPlans', onboarding_plan_count,
    'mentorshipPairs', mentorship_pair_count,
    'mentorshipGoals', mentorship_goal_count,
    'mentorshipNotes', mentorship_note_count,
    'historyYears', history_years,
    'outboundDeliveries', 0
  );
end
$function$

