CREATE OR REPLACE FUNCTION private.demo_seed_user(p_lane text, p_run_id uuid, p_ordinal integer)
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  found_user uuid;
  lane_count integer;
begin
  if p_lane = 'presg' then
    select member_count into lane_count from private.presg_demo_runs where id = p_run_id;
    select user_id into found_user from private.presg_demo_ledger
    where run_id = p_run_id and ordinal = 1 + (greatest(p_ordinal, 1) - 1) % lane_count;
  elsif p_lane = 'uniondemo' then
    select member_count into lane_count from private.uniondemo_runs where id = p_run_id;
    select user_id into found_user from private.uniondemo_ledger
    where run_id = p_run_id and ordinal = 1 + (greatest(p_ordinal, 1) - 1) % lane_count;
  else
    raise exception 'unknown demo lane';
  end if;
  if found_user is null then raise exception 'demo lane has no seeded users'; end if;
  return found_user;
end;
$function$

CREATE OR REPLACE FUNCTION private.demo_seed_verify_dues(p_lane text, p_run_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  seeded private.dues_sample_seed_runs%rowtype;
  obligation_count integer;
  assessment_count integer;
  receipt_count integer;
  reminder_count integer;
  open_count integer;
  overdue_count integer;
  partial_count integer;
  paid_count integer;
  waived_count integer;
begin
  select * into seeded from private.dues_sample_seed_runs row
  where row.lane = p_lane and row.run_id = p_run_id;
  if not found or seeded.state <> 'applied' then
    raise exception 'Dues SAMPLE seed is not applied' using errcode = '42501';
  end if;
  select count(*) into obligation_count from private.dues_sample_seed_ledger
  where lane = p_lane and run_id = p_run_id;
  select count(*) into assessment_count
  from public.dues_ledger_events event
  join private.dues_sample_seed_ledger ledger on ledger.assessment_event_id = event.id
  where ledger.lane = p_lane and ledger.run_id = p_run_id and event.event_kind = 'assessment';
  select count(*) into receipt_count
  from public.dues_ledger_events event
  join private.dues_sample_seed_ledger ledger on ledger.settlement_event_id = event.id
  where ledger.lane = p_lane and ledger.run_id = p_run_id and event.receipt_number is not null;
  select count(*) into reminder_count from public.dues_reminder_attempts reminder
  join private.dues_sample_seed_ledger ledger on ledger.reminder_attempt_id = reminder.id
  where ledger.lane = p_lane and ledger.run_id = p_run_id and reminder.state = 'sent';
  with state_rows as (
    select obligation.id, obligation.due_on,
      coalesce(sum(event.amount_cents) filter (where event.event_kind = 'payment'), 0) as paid_cents,
      coalesce(sum(event.amount_cents) filter (where event.event_kind = 'waiver'), 0) as waived_cents
    from public.dues_obligations obligation
    join private.dues_sample_seed_ledger ledger on ledger.obligation_id = obligation.id
    left join public.dues_ledger_events event on event.obligation_id = obligation.id
    where ledger.lane = p_lane and ledger.run_id = p_run_id
    group by obligation.id, obligation.due_on
  ), standing as (
    select case
      when waived_cents >= 5000 and paid_cents = 0 then 'waived'
      when paid_cents >= 5000 then 'paid'
      when paid_cents > 0 or waived_cents > 0 then 'partial'
      when due_on < current_date then 'overdue'
      else 'open'
    end as value from state_rows
  )
  select count(*) filter (where value = 'open'), count(*) filter (where value = 'overdue'),
    count(*) filter (where value = 'partial'), count(*) filter (where value = 'paid'),
    count(*) filter (where value = 'waived')
  into open_count, overdue_count, partial_count, paid_count, waived_count
  from standing;
  if obligation_count <> 60 or assessment_count <> 60 or receipt_count <> 30
     or reminder_count <> 12 or open_count <> 3 or overdue_count <> 12
     or partial_count <> 15 or paid_count <> 15 or waived_count <> 15 then
    raise exception 'Dues SAMPLE verification failed' using errcode = '55000';
  end if;
  if exists (
    select 1 from public.dues_provider_connections connection
    where connection.organization_id = seeded.organization_id and connection.state <> 'unset'
  ) or exists (
    select 1 from public.dues_stripe_events event
    join public.dues_checkout_reservations reservation on reservation.id = event.reservation_id
    join private.dues_sample_seed_ledger ledger on ledger.obligation_id = reservation.obligation_id
    where ledger.lane = p_lane and ledger.run_id = p_run_id
  ) then
    raise exception 'SAMPLE Stripe must remain unset' using errcode = '55000';
  end if;
  return pg_catalog.jsonb_build_object(
    'ok', true, 'lane', p_lane, 'runId', p_run_id,
    'obligations', obligation_count, 'staffRows', 60, 'memberRows', 60,
    'receipts', receipt_count, 'reminders', reminder_count,
    'standing', pg_catalog.jsonb_build_object('open', open_count, 'overdue', overdue_count, 'partial', partial_count, 'paid', paid_count, 'waived', waived_count),
    'stripeUnset', true
  );
end;
$function$

CREATE OR REPLACE FUNCTION private.demo_seed_voice_operations_status(p_lane text, p_run_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_organization_id uuid := private.member_stress_uuid(
    p_run_id::text || case when p_lane = 'presg' then ':presg:organization' else ':ud:organization' end
  );
  v_current_period text := pg_catalog.to_char(
    pg_catalog.now() at time zone 'UTC', 'YYYY'
  ) || '-Q' || pg_catalog.date_part(
    'quarter', pg_catalog.now() at time zone 'UTC'
  )::integer;
  v_quarterly_count bigint;
  v_current_quarter_count bigint;
  v_current_responses bigint;
  v_prior_responses bigint;
  v_incomplete_examples bigint;
  v_owner_count bigint;
  v_task_count bigint;
  v_task_reason_count bigint;
  v_task_state_count bigint;
  v_delivery_count bigint;
  v_delivery_state_count bigint;
  v_review_count bigint;
  v_review_state_count bigint;
  v_history_session_count bigint;
  v_outbound_count bigint;
begin
  if p_lane not in ('presg', 'uniondemo') then
    raise exception 'unknown demo lane';
  end if;

  select pg_catalog.count(*),
         pg_catalog.count(*) filter (where survey.period_key = v_current_period),
         pg_catalog.count(*) filter (where survey.owner_user_id is not null)
  into v_quarterly_count, v_current_quarter_count, v_owner_count
  from public.organization_surveys survey
  where survey.organization_id = v_organization_id
    and survey.id in (
      select private.member_stress_uuid(p_run_id::text || ':voice:survey:' || series.n)
      from pg_catalog.generate_series(1, 12) series(n)
    )
    and survey.cadence = 'quarterly';

  select pg_catalog.count(*) into v_current_responses
  from public.organization_survey_sessions session
  where session.survey_id = private.member_stress_uuid(p_run_id::text || ':voice:survey:1')
    and session.id in (
      select private.member_stress_uuid(
        p_run_id::text || ':voice:survey:1:session:' || series.n
      ) from pg_catalog.generate_series(1, 3) series(n)
    )
    and session.status = 'submitted';

  select pg_catalog.count(*) into v_prior_responses
  from public.organization_survey_sessions session
  where session.survey_id = private.member_stress_uuid(p_run_id::text || ':voice:survey:2')
    and session.id in (
      select private.member_stress_uuid(
        p_run_id::text || ':voice:survey:2:session:' || series.n
      ) from pg_catalog.generate_series(1, 6) series(n)
    )
    and session.status = 'submitted';

  select pg_catalog.count(*) into v_incomplete_examples
  from public.organization_surveys survey
  where survey.id = private.member_stress_uuid(p_run_id::text || ':voice:survey:1')
    and not exists (
      select 1
      from public.organization_survey_sessions session
      where session.survey_id = survey.id
        and session.respondent_user_id = private.demo_seed_user(p_lane, p_run_id, 70)
        and session.status = 'submitted'
    );

  select pg_catalog.count(*) into v_history_session_count
  from public.organization_survey_sessions session
  where session.id in (
    select private.member_stress_uuid(
      p_run_id::text || ':voice:survey:' || quarter.n || ':session:' || respondent.n
    )
    from pg_catalog.generate_series(1, 12) quarter(n)
    cross join lateral pg_catalog.generate_series(
      1, case when quarter.n = 1 then 3 when quarter.n = 2 then 6 else 1 end
    ) respondent(n)
  ) and session.status = 'submitted';

  select pg_catalog.count(*),
         pg_catalog.count(distinct task.reason),
         pg_catalog.count(distinct task.status)
  into v_task_count, v_task_reason_count, v_task_state_count
  from public.organization_survey_tasks task
  where task.organization_id = v_organization_id
    and task.id in (
      select private.member_stress_uuid(p_run_id::text || ':voice:task:' || series.n)
      from pg_catalog.generate_series(1, 16) series(n)
    );

  select pg_catalog.count(*), pg_catalog.count(distinct delivery.state)
  into v_delivery_count, v_delivery_state_count
  from public.organization_survey_deliveries delivery
  where delivery.organization_id = v_organization_id
    and delivery.id in (
      select private.member_stress_uuid(p_run_id::text || ':voice:delivery:' || series.n)
      from pg_catalog.generate_series(1, 24) series(n)
    );

  select pg_catalog.count(*), pg_catalog.count(distinct review.state)
  into v_review_count, v_review_state_count
  from public.organization_survey_reviews review
  where review.organization_id = v_organization_id
    and review.id in (
      select private.member_stress_uuid(p_run_id::text || ':voice:review:' || series.n)
      from pg_catalog.generate_series(1, 19) series(n)
    );

  select pg_catalog.count(*) into v_outbound_count
  from public.engagement_delivery_outbox outbound
  where outbound.organization_id = v_organization_id
    and outbound.source_kind = 'survey'
    and outbound.source_id in (
      select private.member_stress_uuid(
        p_run_id::text || ':voice:survey:' || series.n
      )::text
      from pg_catalog.generate_series(1, 16) series(n)
    );

  return pg_catalog.jsonb_build_object(
    'ok', v_quarterly_count = 12
      and v_current_quarter_count = 1
      and v_current_responses = 3
      and v_prior_responses = 6
      and v_incomplete_examples = 1
      and v_owner_count = 12
      and v_history_session_count = 19
      and v_task_count = 16
      and v_task_reason_count = 4
      and v_task_state_count = 4
      and v_delivery_count = 24
      and v_delivery_state_count = 6
      and v_review_count = 19
      and v_review_state_count = 5
      and v_outbound_count = 0,
    'quarterlySurveys', v_quarterly_count,
    'currentQuarterSurveys', v_current_quarter_count,
    'currentQuarterResponses', v_current_responses,
    'priorQuarterResponses', v_prior_responses,
    'incompleteGateExamples', v_incomplete_examples,
    'ownedQuarterlySurveys', v_owner_count,
    'historySessions', v_history_session_count,
    'surveyTasks', v_task_count,
    'taskReasons', v_task_reason_count,
    'taskStates', v_task_state_count,
    'surveyDeliveries', v_delivery_count,
    'deliveryStates', v_delivery_state_count,
    'surveyReviews', v_review_count,
    'reviewStates', v_review_state_count,
    'outboundDeliveries', v_outbound_count
  );
end;
$function$

CREATE OR REPLACE FUNCTION private.demo_seed_voice_parity_status(p_lane text, p_run_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_organization_id uuid := private.member_stress_uuid(
    p_run_id::text || case when p_lane = 'presg' then ':presg:organization' else ':ud:organization' end
  );
  v_chapter_id text := private.demo_seed_chapter(p_lane, p_run_id, 1);
  v_survey_count bigint;
  v_question_type_count bigint;
  v_conditional_count bigint;
  v_withheld_count bigint;
  v_available_count bigint;
  v_weekly_count bigint;
  v_weekly_visible bigint;
  v_weekly_state_count bigint;
begin
  select pg_catalog.count(*) into v_survey_count
  from public.organization_surveys survey
  where survey.organization_id = v_organization_id
    and survey.id in (
      select private.member_stress_uuid(p_run_id::text || ':voice:survey:' || series.n)
      from pg_catalog.generate_series(1, 16) series(n)
    );

  select pg_catalog.count(distinct question.question_type),
         pg_catalog.count(*) filter (where question.branch_parent_id is not null)
  into v_question_type_count, v_conditional_count
  from public.organization_survey_questions question
  where question.organization_id = v_organization_id
    and question.survey_id in (
      select private.member_stress_uuid(p_run_id::text || ':voice:survey:' || series.n)
      from pg_catalog.generate_series(1, 16) series(n)
    );

  select pg_catalog.count(*) into v_withheld_count
  from public.organization_survey_sessions session
  where session.id in (
    select private.member_stress_uuid(
      p_run_id::text || ':voice:survey:1:session:' || series.n
    ) from pg_catalog.generate_series(1, 3) series(n)
  ) and session.status = 'submitted';
  select pg_catalog.count(*) into v_available_count
  from public.organization_survey_sessions session
  where session.id in (
    select private.member_stress_uuid(
      p_run_id::text || ':voice:survey:2:session:' || series.n
    ) from pg_catalog.generate_series(1, 6) series(n)
  ) and session.status = 'submitted';

  select pg_catalog.count(*),
         pg_catalog.count(*) filter (where weekly.editorial_state in ('submitted', 'reserved', 'published')),
         pg_catalog.count(distinct weekly.editorial_state)
  into v_weekly_count, v_weekly_visible, v_weekly_state_count
  from public.member_weekly_questions weekly
  where weekly.chapter_id = v_chapter_id
    and weekly.id in (
      select private.member_stress_uuid(p_run_id::text || ':voice:weekly:' || series.n)
      from pg_catalog.generate_series(1, 52) series(n)
    );

  return pg_catalog.jsonb_build_object(
    'ok', v_survey_count = 16
      and v_question_type_count = 8
      and v_conditional_count = 16
      and v_withheld_count = 3
      and v_available_count = 6
      and v_weekly_count = 52
      and v_weekly_visible = 50
      and v_weekly_state_count = 4,
    'surveys', v_survey_count,
    'questionTypes', v_question_type_count,
    'conditionalQuestions', v_conditional_count,
    'withheldResponses', v_withheld_count,
    'availableResponses', v_available_count,
    'weeklyQuestions', v_weekly_count,
    'weeklyVisible', v_weekly_visible,
    'weeklyEditorialStates', v_weekly_state_count,
    'outboundDeliveries', 0
  );
end;
$function$

CREATE OR REPLACE FUNCTION private.dues_sample_remove_subjects_on_lane_removal()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  perform private.lock_case_graph(array[auth.uid()], array[]::uuid[]);

declare
  lane_name text := case when tg_table_name = 'presg_demo_runs' then 'presg' else 'uniondemo' end;
  org uuid;
begin
  if new.state <> 'removing' or old.state = 'removing' then
    return new;
  end if;
  org := private.dues_sample_seed_organization(lane_name, new.id);
  if exists (
    select 1 from public.dues_obligations obligation
    where obligation.organization_id = org
  ) then
    raise exception 'remove Dues SAMPLE history before normal lane removal' using errcode = '55000';
  end if;
  delete from public.dues_member_subjects subject where subject.organization_id = org;
  return new;
end;
end;
$function$

CREATE OR REPLACE FUNCTION private.dues_sample_seed_authorize(p_target_ref text, p_confirm_token text, p_lane text, p_run_id uuid, p_mode text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  org uuid;
begin
  if (select auth.role()) <> 'service_role' then
    raise exception 'dues SAMPLE seed requires service_role' using errcode = '42501';
  end if;
  if p_target_ref = 'productionprojectref' then
    raise exception 'production project refused' using errcode = '42501';
  end if;
  if p_target_ref <> 'sampledemoprojectref' then
    raise exception 'SAMPLE project required' using errcode = '42501';
  end if;
  if p_lane = 'presg' then
    perform private.presg_demo_authorize(p_target_ref, p_confirm_token);
    if not exists (select 1 from private.presg_demo_runs row where row.id = p_run_id and row.state in ('applied', 'verified')) then
      raise exception 'presg demo run is not applied' using errcode = '42501';
    end if;
  elsif p_lane = 'uniondemo' then
    perform private.uniondemo_authorize(p_target_ref, p_confirm_token);
    if not exists (select 1 from private.uniondemo_runs row where row.id = p_run_id and row.state in ('applied', 'verified')) then
      raise exception 'union demo run is not applied' using errcode = '42501';
    end if;
  else
    raise exception 'unknown demo lane' using errcode = '22023';
  end if;
  if p_mode not in ('apply', 'verify', 'remove') then
    raise exception 'invalid dues SAMPLE seed mode' using errcode = '22023';
  end if;
  org := private.dues_sample_seed_organization(p_lane, p_run_id);
  if not exists (select 1 from public.organizations organization where organization.id = org and organization.status = 'active') then
    raise exception 'demo organization is missing' using errcode = '42501';
  end if;
  return org;
end;
$function$

CREATE OR REPLACE FUNCTION private.ensure_dues_sample_seed_covering_indexes()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  is_sample_installation boolean := false;
begin
  -- Table presence alone is not an environment identity: historical SAMPLE
  -- schema objects can exist on production while their mutation entrypoints
  -- remain disabled. Require the out-of-band SAMPLE binding to match this
  -- exact Postgres cluster and database before creating any SAMPLE-only index.
  if pg_catalog.to_regclass('private.demo_seed_installation_bindings') is not null then
    select exists (
      select 1
      from private.demo_seed_installation_bindings as binding
      cross join pg_catalog.pg_control_system() as control
      join pg_catalog.pg_database as database
        on database.datname = pg_catalog.current_database()
      where binding.project_ref = 'sampledemoprojectref'
        and binding.system_identifier = control.system_identifier::numeric
        and binding.database_oid = database.oid
    )
    into is_sample_installation;
  end if;

  if not is_sample_installation then
    return;
  end if;

  perform pg_catalog.set_config('lock_timeout', '5s', true);

  if pg_catalog.to_regclass('private.dues_sample_seed_ledger') is not null then
    execute 'create index if not exists dues_sample_seed_ledger_assessment_event_idx
      on private.dues_sample_seed_ledger (assessment_event_id)';
    execute 'create index if not exists dues_sample_seed_ledger_settlement_event_idx
      on private.dues_sample_seed_ledger (settlement_event_id)';
    execute 'create index if not exists dues_sample_seed_ledger_reminder_attempt_idx
      on private.dues_sample_seed_ledger (reminder_attempt_id)';
  end if;

  if pg_catalog.to_regclass('private.dues_sample_seed_runs') is not null then
    execute 'create index if not exists dues_sample_seed_runs_subject_idx
      on private.dues_sample_seed_runs (featured_subject_id)';
    execute 'create index if not exists dues_sample_seed_runs_org_idx
      on private.dues_sample_seed_runs (organization_id)';
  end if;
end
$function$

CREATE OR REPLACE FUNCTION private.guard_casework_restriction_update()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  seed_scope_text text := pg_catalog.current_setting('unionground.demo_seed_casework_scope', true);
  seed_scope_json jsonb;
  seed_lane text;
  seed_run uuid;
  seed_organization uuid;
  seed_run_valid boolean := false;
  seed_scope boolean := false;
begin
  if tg_op = 'INSERT' then
    if new.is_restricted and new.restricted_by is null then
      raise exception 'restricted case requires an attribution actor' using errcode = '23514';
    end if;
    return new;
  end if;

  if old.restricted_by is not null
     and new.restricted_by is null
     and new.is_restricted then
    if private.account_lifecycle_is_nested_auth_detachment(old.restricted_by, new.restricted_by)
       and (pg_catalog.to_jsonb(new) - 'restricted_by')
         is not distinct from (pg_catalog.to_jsonb(old) - 'restricted_by') then
      return new;
    end if;
    raise exception 'restricted-case attribution cannot be detached' using errcode = '42501';
  end if;
  if not old.is_restricted and new.is_restricted and new.restricted_by is null then
    raise exception 'restricted case requires an attribution actor' using errcode = '23514';
  end if;

  begin
    seed_scope_json := seed_scope_text::jsonb;
    seed_lane := seed_scope_json ->> 'lane';
    if seed_lane not in ('presg', 'uniondemo')
       or (seed_scope_json ->> 'runId') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
      raise exception 'invalid casework seed scope';
    end if;
    seed_run := (seed_scope_json ->> 'runId')::uuid;
    seed_organization := private.member_stress_uuid(
      seed_run::text || case when seed_lane = 'presg'
        then ':presg:organization' else ':ud:organization' end
    );
    if seed_lane = 'presg' then
      select exists (
        select 1 from private.presg_demo_runs row
        where row.id = seed_run and row.state in ('applied', 'verified')
      ) into seed_run_valid;
    else
      select exists (
        select 1 from private.uniondemo_runs row
        where row.id = seed_run and row.state in ('applied', 'verified')
      ) into seed_run_valid;
    end if;
    seed_scope := (select auth.role()) = 'service_role'
      and seed_run_valid
      and (seed_scope_json ->> 'organizationId')::uuid = seed_organization
      and seed_organization = old.organization_id;
  exception when others then
    seed_scope := false;
  end;

  if row(old.is_restricted, old.restriction_reason, old.restricted_at, old.restricted_by)
     is distinct from
     row(new.is_restricted, new.restriction_reason, new.restricted_at, new.restricted_by)
     and not seed_scope
     and not private.casework_staff_can_access(old.id) then
    raise exception 'restricted-case fields require authorized staff' using errcode = '42501';
  end if;
  return new;
end;
$function$

