CREATE OR REPLACE FUNCTION private.presg_demo_authorize(p_target_ref text, p_confirm_token text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  live_system_identifier numeric;
  live_database_oid oid;
begin
  if (select auth.role()) <> 'service_role' then
    raise exception 'presg demo RPC requires service_role';
  end if;
  if p_target_ref <> 'sampledemoprojectref' then
    raise exception 'presg demo target mismatch';
  end if;

  select control.system_identifier::numeric
  into live_system_identifier
  from pg_catalog.pg_control_system() as control;

  select database.oid
  into live_database_oid
  from pg_catalog.pg_database as database
  where database.datname = pg_catalog.current_database();

  if not exists (
    select 1
    from private.demo_seed_installation_bindings as binding
    where binding.project_ref = p_target_ref
      and binding.system_identifier = live_system_identifier
      and binding.database_oid = live_database_oid
  ) then
    raise exception 'presg demo database identity is not bound to SAMPLE';
  end if;

  if p_confirm_token <> 'SEED_PRE_SOLID_GROUND_SAMPLE_DEMO' then
    raise exception 'presg demo confirmation mismatch';
  end if;
end;
$function$

CREATE OR REPLACE FUNCTION private.presg_demo_receipt_code(p_seed text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE STRICT
 SET search_path TO ''
AS $function$
declare
  alphabet constant text := '0123456789ABCDEFGHJKMNPQRSTVWXYZ';
  digest text := pg_catalog.md5(p_seed);
  body text := '';
  i integer;
begin
  for i in 0..7 loop
    body := body || pg_catalog.substr(alphabet,
      ((('x' || pg_catalog.substr(digest, i * 2 + 1, 2))::bit(8)::integer) % 32) + 1, 1);
  end loop;
  return 'SG-' || pg_catalog.substr(body, 1, 4) || '-' || pg_catalog.substr(body, 5, 4);
end;
$function$

CREATE OR REPLACE FUNCTION private.presg_demo_sweep_trigger_rows(p_run_id uuid)
 RETURNS bigint
 LANGUAGE plpgsql
