CREATE OR REPLACE FUNCTION private.presg_demo_verify_pre_function_parity(p_run_id uuid, p_password text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET statement_timeout TO '300s'
AS $function$
begin
  perform private.lock_case_graph(array[auth.uid()], array[]::uuid[]);

begin
  perform private.lock_message_lifecycle();

declare
  run private.presg_demo_runs%rowtype;
  result jsonb;
  typed_kinds bigint;
  deliveries bigint;
  fresh_points bigint;
  cases_total bigint;
  cases_distinct bigint;
  guarded_prefs bigint;
  login_rows bigint;
  password_sample bigint;
  sample_size integer;
  passed boolean;
begin
  if (select auth.role()) <> 'service_role' then raise exception 'presg demo RPC requires service_role'; end if;
  if pg_catalog.char_length(coalesce(p_password, '')) < 24 then raise exception 'demo password is too short'; end if;
  select * into run from private.presg_demo_runs where id = p_run_id for update;
  if not found then raise exception 'unknown presg demo run'; end if;
  if run.state not in ('applied', 'verified') then raise exception 'run is not fully applied'; end if;

  result := public.presg_demo_status(p_run_id);

  select pg_catalog.count(*) into typed_kinds
  from public.member_notifications n
  join private.presg_demo_ledger l on l.user_id = n.user_id and l.run_id = p_run_id
  where n.kind <> 'general';

  select pg_catalog.count(*) into deliveries
  from public.member_notification_deliveries d
  join private.presg_demo_ledger l on l.user_id = d.user_id and l.run_id = p_run_id;

  select pg_catalog.count(*) into fresh_points
  from public.member_point_events e
  join private.presg_demo_ledger l on l.user_id = e.user_id and l.run_id = p_run_id
  where e.occurred_at >= pg_catalog.date_trunc('week', pg_catalog.now());

  select pg_catalog.count(*), pg_catalog.count(distinct c.reference)
    into cases_total, cases_distinct
  from public.member_cases c
  join private.presg_demo_ledger l on l.user_id = c.user_id and l.run_id = p_run_id;

  select pg_catalog.count(*) into guarded_prefs
  from public.member_profiles p
  join private.presg_demo_ledger l on l.user_id = p.id and l.run_id = p_run_id
  where p.notification_prefs @> '{"deadlines": false, "cases": false, "forms": false, "votes": false, "events": false, "tasks": false, "appointments": false, "workload": false}'::jsonb;

  -- bcrypt comparison is ~100ms per row; a deterministic sample proves the
  -- shared password while the cheap count proves every login row is non-empty.
  sample_size := least(run.login_count, 20);
  select pg_catalog.count(*) into password_sample
  from auth.users u
  join private.presg_demo_ledger l on l.user_id = u.id
  where l.run_id = p_run_id and l.login_capable and l.ordinal <= sample_size
    -- The CASE is load-bearing: without it the planner may evaluate crypt()
    -- against a non-login row's empty hash first and raise "invalid salt".
    and case when u.encrypted_password like '$2%'
      then u.encrypted_password = extensions.crypt(p_password, u.encrypted_password)
      else false end;

  select pg_catalog.count(*) into login_rows
  from auth.users u
  join private.presg_demo_ledger l on l.user_id = u.id
  where l.run_id = p_run_id and l.login_capable and u.encrypted_password <> '';

  passed :=
    (result ->> 'ledger_rows')::bigint = run.member_count
    and (result ->> 'auth_users')::bigint = run.member_count
    and (result ->> 'profiles')::bigint = run.member_count
    and (result ->> 'steward_roles')::bigint = run.committee_count
    and guarded_prefs = run.member_count
    and typed_kinds = 0
    and deliveries = 0
    and fresh_points = 0
    and cases_total = cases_distinct
    and password_sample = sample_size
    and login_rows = run.login_count
    and (result ->> 'conversations')::bigint >= run.member_count
    and (result ->> 'messages')::bigint >= run.member_count * 4
    and (result ->> 'org_events')::bigint >= 60
    and (result ->> 'org_ballots')::bigint = 6
    and (result ->> 'org_broadcasts')::bigint >= 90
    and (result ->> 'org_threads')::bigint >= 100
    and (result ->> 'org_thread_posts')::bigint >= 1500
    and (result ->> 'protected_unchanged')::boolean;

  if passed then
    update private.presg_demo_runs
    set state = 'verified', verified_at = pg_catalog.now(), updated_at = pg_catalog.now()
    where id = p_run_id;
  end if;
  return result || jsonb_build_object(
    'typed_notification_kinds', typed_kinds,
    'outbound_deliveries', deliveries,
    'points_in_current_week', fresh_points,
    'cases_distinct_refs', cases_distinct,
    'guarded_prefs', guarded_prefs,
    'password_sample', password_sample,
    'password_sample_size', sample_size,
    'login_rows', login_rows,
    'state', case when passed then 'verified' else run.state end,
    'ok', passed);
end;
end;
end;
$function$

CREATE OR REPLACE FUNCTION private.require_sensitive_envelopes()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  source jsonb := '{}'::jsonb; operation text; allowed text[] := array[]::text[];
  maintenance boolean := session_user in ('postgres','supabase_admin')
    and current_setting('role') in ('none','postgres','supabase_admin')
    and current_setting('app.sensitive_maintenance',true) = 'on';
  fields text[]; field_name text; envelope jsonb; value text; previous jsonb;
begin
  if maintenance then
    source := coalesce(nullif(current_setting('app.sensitive_envelopes',true),'')::jsonb,'{}'::jsonb);
  else
    select t.envelopes, t.operation into source, operation from private.sensitive_write_tickets t
      where t.id = nullif(current_setting('app.sensitive_ticket',true),'')::uuid
      and t.actor = (select auth.uid()) and t.expires_at > clock_timestamp();
  end if;
  fields := case tg_table_name
    when 'casework_retaliation_patterns' then array['subject_label']
    when 'member_accommodation_requests' then array['description','staff_note']
    when 'casework_retaliation_reports' then array['management_person','protected_activity','adverse_action','requested_support','withdrawal_reason']
  end;
  -- SAMPLE fixtures are sealed by the server before the seed RPC executes.
  -- Client roles cannot activate this channel, even with a forged GUC/ticket.
  if tg_op = 'INSERT' and current_setting('role') in ('service_role','none','postgres','supabase_admin') then
    select t.envelopes->tg_table_name->new.id::text into envelope
      from private.sensitive_write_tickets t
      where t.id = nullif(current_setting('app.sensitive_seed_ticket',true),'')::uuid
        and t.operation = 'demo_seed' and t.actor = new.organization_id
        and t.expires_at > clock_timestamp()
        and t.actor = private.member_stress_uuid((t.arguments->>'runId') ||
          case t.arguments->>'lane' when 'presg' then ':presg:organization' when 'uniondemo' then ':ud:organization' end);
    if envelope is not null then source := envelope; operation := 'demo_seed'; end if;
  end if;
  if maintenance or operation = 'demo_seed' then allowed := fields;
  elsif tg_table_name = 'casework_retaliation_patterns' and tg_op = 'INSERT'
    and operation = 'casework_scan_retaliation_patterns'
    and private.member_has_chapter_role(to_jsonb(new)->>'chapter_id', array['coordinator','advisor','admin','vp']) then
    select jsonb_build_object('subject_label',g->'label') into source
      from jsonb_array_elements(source->'groups') g where g->>'id' = new.id::text;
    allowed := array['subject_label'];
  elsif tg_table_name = 'member_accommodation_requests' then
    if tg_op = 'INSERT' and operation = 'create_member_accommodation_request'
      and (to_jsonb(new)->>'member_user_id')::uuid = (select auth.uid()) then allowed := array['description'];
    elsif tg_op = 'UPDATE' and operation = 'transition_member_accommodation_request'
      and new.status <> 'withdrawn' and old.status <> 'withdrawn'
      and private.member_support_is_staff(new.organization_id) then allowed := array['staff_note']; end if;
  elsif tg_table_name = 'casework_retaliation_reports' then
    if tg_op = 'INSERT' and operation = 'casework_submit_retaliation_report'
      and (to_jsonb(new)->>'reporter_user_id')::uuid = (select auth.uid()) then
      allowed := array['management_person','protected_activity','adverse_action','requested_support'];
    elsif tg_op = 'UPDATE' and operation = 'casework_withdraw_retaliation_report'
      and new.status = 'withdrawn' and old.status <> 'withdrawn'
      and (to_jsonb(new)->>'reporter_user_id')::uuid = (select auth.uid()) then allowed := array['withdrawal_reason']; end if;
  end if;
  previous := case when tg_op = 'UPDATE' then to_jsonb(old) else '{}'::jsonb end;
  if tg_op = 'UPDATE' and (new.id <> old.id or new.organization_id <> old.organization_id) then
    raise exception 'sensitive-data-identity-immutable' using errcode = '22023';
  end if;
  -- Metadata is writable only through this transaction's envelope channel.
  if tg_op = 'UPDATE' then new.encrypted_content := old.encrypted_content;
  else new.encrypted_content := '{}'::jsonb; end if;
  foreach field_name in array fields loop
    value := to_jsonb(new)->>field_name;
    envelope := source->field_name;
    if not (field_name = any(allowed)) then
      -- Ignore surplus ciphertext on a no-op field, including a member's
      -- withdrawal, but reject any actual plaintext/marker change.
      if coalesce(value,'') is distinct from coalesce(previous->>field_name,'') then
        raise exception 'sensitive-data-encryption-required' using errcode = '22023';
      end if;
      continue;
    end if;
    if envelope is not null then
      if value is distinct from '[encrypted]'
        or envelope->>'organization' is distinct from new.organization_id::text
        or envelope->>'record' is distinct from new.id::text
        or envelope->>'field' is distinct from field_name
        or envelope->>'purpose' is distinct from tg_table_name
        or envelope->>'schema' is distinct from '1'
        or jsonb_typeof(envelope->'payload') is distinct from 'object'
        or jsonb_typeof(envelope->'wrappedKey') is distinct from 'object'
        or coalesce(envelope->>'keyVersion','') !~ '^[a-zA-Z0-9_-]{1,64}$'
        or coalesce(envelope->>'dataVersion','') !~ '^[0-9a-f-]{36}$'
      then raise exception 'sensitive-data-envelope-required' using errcode = '22023'; end if;
      new.encrypted_content := new.encrypted_content || jsonb_build_object(field_name, envelope);
    elsif coalesce(value, '') <> '' and (tg_op = 'INSERT' or value is distinct from previous->>field_name) then
      raise exception 'sensitive-data-encryption-required' using errcode = '22023';
    elsif coalesce(value, '') = '' and value is distinct from previous->>field_name then
      new.encrypted_content := new.encrypted_content - field_name;
    end if;
  end loop;
  return new;
end
$function$

CREATE OR REPLACE FUNCTION private.uniondemo_authorize(p_target_ref text, p_confirm_token text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  live_system_identifier numeric;
  live_database_oid oid;
begin
  if (select auth.role()) <> 'service_role' then
    raise exception 'union demo RPC requires service_role';
  end if;
  if p_target_ref <> 'sampledemoprojectref' then
    raise exception 'union demo target mismatch';
  end if;

  select control.system_identifier::numeric
  into live_system_identifier
  from pg_catalog.pg_control_system() as control;

  select database.oid
  into live_database_oid
  from pg_catalog.pg_database as database
  where database.datname = pg_catalog.current_database();

  if not exists (
    select 1
    from private.demo_seed_installation_bindings as binding
    where binding.project_ref = p_target_ref
      and binding.system_identifier = live_system_identifier
      and binding.database_oid = live_database_oid
  ) then
    raise exception 'union demo database identity is not bound to SAMPLE';
  end if;

  if p_confirm_token <> 'SEED_UNION_DEMO_ORG_SAMPLE_30K' then
    raise exception 'union demo confirmation mismatch';
  end if;
end;
$function$

CREATE OR REPLACE FUNCTION private.uniondemo_receipt_code(p_seed text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE STRICT
 SET search_path TO ''
AS $function$
declare
  alphabet constant text := '0123456789ABCDEFGHJKMNPQRSTVWXYZ';
  digest text := pg_catalog.md5(p_seed);
  body text := '';
  i integer;
begin
  for i in 0..7 loop
    body := body || pg_catalog.substr(alphabet,
      ((('x' || pg_catalog.substr(digest, i * 2 + 1, 2))::bit(8)::integer) % 32) + 1, 1);
  end loop;
  return 'SG-' || pg_catalog.substr(body, 1, 4) || '-' || pg_catalog.substr(body, 5, 4);
end;
$function$

CREATE OR REPLACE FUNCTION private.uniondemo_sweep_trigger_rows(p_run_id uuid)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  perform private.lock_case_graph(array[auth.uid()], array[]::uuid[]);

declare
  swept bigint;
begin
  delete from public.member_notification_deliveries d
  using private.uniondemo_ledger l
  where l.run_id = p_run_id and d.user_id = l.user_id and d.created_at >= pg_catalog.now();

  delete from public.member_notifications n
  using private.uniondemo_ledger l
  where l.run_id = p_run_id and n.user_id = l.user_id and n.created_at >= pg_catalog.now();
  get diagnostics swept = row_count;
  return swept;
end;
end;
$function$

CREATE OR REPLACE FUNCTION private.uniondemo_verify_pre_function_parity(p_run_id uuid, p_password text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET statement_timeout TO '300s'
AS $function$
begin
  perform private.lock_case_graph(array[auth.uid()], array[]::uuid[]);

begin
  perform private.lock_message_lifecycle();

declare
  run private.uniondemo_runs%rowtype;
  result jsonb;
  typed_kinds bigint;
  deliveries bigint;
  fresh_points bigint;
  cases_total bigint;
  cases_distinct bigint;
  guarded_prefs bigint;
  chapter_mismatches bigint;
  login_rows bigint;
  password_sample bigint;
  sample_size integer;
  passed boolean;
begin
  if (select auth.role()) <> 'service_role' then raise exception 'union demo RPC requires service_role'; end if;
  if pg_catalog.char_length(coalesce(p_password, '')) < 24 then raise exception 'demo password is too short'; end if;
  select * into run from private.uniondemo_runs where id = p_run_id for update;
  if not found then raise exception 'unknown union demo run'; end if;
  if run.state not in ('applied', 'verified') then raise exception 'run is not fully applied'; end if;

  result := public.uniondemo_status(p_run_id);

  select pg_catalog.count(*) into typed_kinds
  from public.member_notifications n
  join private.uniondemo_ledger l on l.user_id = n.user_id and l.run_id = p_run_id
  where n.kind <> 'general';

  select pg_catalog.count(*) into deliveries
  from public.member_notification_deliveries d
  join private.uniondemo_ledger l on l.user_id = d.user_id and l.run_id = p_run_id;

  select pg_catalog.count(*) into fresh_points
  from public.member_point_events e
  join private.uniondemo_ledger l on l.user_id = e.user_id and l.run_id = p_run_id
  where e.occurred_at >= pg_catalog.date_trunc('week', pg_catalog.now());

  select pg_catalog.count(*), pg_catalog.count(distinct c.reference)
    into cases_total, cases_distinct
  from public.member_cases c
  join private.uniondemo_ledger l on l.user_id = c.user_id and l.run_id = p_run_id;

  select pg_catalog.count(*) into guarded_prefs
  from public.member_profiles p
  join private.uniondemo_ledger l on l.user_id = p.id and l.run_id = p_run_id
  where p.notification_prefs @> '{"deadlines": false, "cases": false, "forms": false, "votes": false, "events": false, "tasks": false, "appointments": false, "workload": false}'::jsonb;

  -- The 20-chapter distribution is exact: every chapter's profile count must
  -- equal its mapped member count.
  select pg_catalog.count(*) into chapter_mismatches
  from private.uniondemo_chapters map
  where map.run_id = p_run_id
    and map.member_count <> (
      select pg_catalog.count(*) from public.member_profiles p
      join private.uniondemo_ledger l on l.user_id = p.id and l.run_id = p_run_id
      where p.chapter_id = map.chapter_id);

  sample_size := least(run.login_count, 20);
  select pg_catalog.count(*) into password_sample
  from auth.users u
  join private.uniondemo_ledger l on l.user_id = u.id
  where l.run_id = p_run_id and l.login_capable and l.ordinal <= sample_size
    -- The CASE is load-bearing: without it the planner may evaluate crypt()
    -- against a non-login row's empty hash first and raise "invalid salt".
    and case when u.encrypted_password like '$2%'
      then u.encrypted_password = extensions.crypt(p_password, u.encrypted_password)
      else false end;

  select pg_catalog.count(*) into login_rows
  from auth.users u
  join private.uniondemo_ledger l on l.user_id = u.id
  where l.run_id = p_run_id and l.login_capable and u.encrypted_password <> '';

  passed :=
    (result ->> 'ledger_rows')::bigint = run.member_count
    and (result ->> 'auth_users')::bigint = run.member_count
    and (result ->> 'profiles')::bigint = run.member_count
    and (result ->> 'chapters')::bigint = 20
    and (result ->> 'steward_roles')::bigint = run.steward_count
    and (result ->> 'officer_roles')::bigint = 61
    and chapter_mismatches = 0
    and guarded_prefs = run.member_count
    and typed_kinds = 0
    and deliveries = 0
    and fresh_points = 0
    and cases_total = cases_distinct
    and password_sample = sample_size
    and login_rows = run.login_count
    and (result ->> 'conversations')::bigint >= run.member_count
    and (result ->> 'messages')::bigint >= run.member_count * 4
    and (result ->> 'org_events')::bigint >= 20 * 60
    and (result ->> 'org_ballots')::bigint = 20 * 9
    and (result ->> 'org_broadcasts')::bigint >= 200
    and (result ->> 'org_threads')::bigint >= 20 * 30
    and (result ->> 'org_thread_posts')::bigint >= 20 * 300
    and (result ->> 'org_tasks')::bigint >= 20 * 40
    and (result ->> 'appointments')::bigint >= run.steward_count
    and (result ->> 'protected_unchanged')::boolean;

  if passed then
    update private.uniondemo_runs
    set state = 'verified', verified_at = pg_catalog.now(), updated_at = pg_catalog.now()
    where id = p_run_id;
  end if;
  return result || jsonb_build_object(
    'typed_notification_kinds', typed_kinds,
    'outbound_deliveries', deliveries,
    'points_in_current_week', fresh_points,
    'cases_distinct_refs', cases_distinct,
    'guarded_prefs', guarded_prefs,
    'chapter_mismatches', chapter_mismatches,
    'password_sample', password_sample,
    'password_sample_size', sample_size,
    'login_rows', login_rows,
    'state', case when passed then 'verified' else run.state end,
    'ok', passed);
end;
end;
end;
$function$

